var MREST=[{"id":6331,"bg":"Когато при преминаване през жп прелез се включат звуковия сигнал и червените светлини на светофара, водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да продължи движението си и да освободи прелеза","ok":true,"i":null,"es":"continuar y abandonar el paso a nivel lo antes posible"},{"t":"да спре незабавно и да включи аварийните светлини","ok":false,"i":null,"es":"parar inmediatamente y activar las luces de emergencia"},{"t":"да завие в обратна посока за да освободи прелеза по-бързо","ok":false,"i":null,"es":"dar la vuelta para salir más rápido"}],"f":8,"es":"Cuando al cruzar el paso a nivel se activan las señales de alarma, el conductor que ya está sobre las vías debe:","explain":"Si ya estás SOBRE las vías cuando se activan las señales, nunca pares ni des la vuelta: continúa y libera el paso cuanto antes. Detenerse sobre las vías (aunque sea con luces de emergencia) te deja en la trayectoria del tren."},{"id":6341,"bg":"На водача е забранено да навлиза на железопътния прелез когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"бариерите се спускат","ok":true,"i":null,"es":"las barreras están bajando"},{"t":"бариерите са спуснати","ok":true,"i":null,"es":"las barreras están bajadas"},{"t":"на прелеза трябва да се размине с друго ППС","ok":false,"i":null,"es":"en el paso debe cruzarse con otro vehículo"},{"t":"на прелеза няма съоръжения за подаване на звуков и светлинен сигнал","ok":false,"i":null,"es":"el paso no tiene señalización"}],"f":8,"es":"Al conductor le está PROHIBIDO entrar al paso a nivel cuando: (2 correctas)","explain":"Está prohibido entrar cuando las barreras BAJAN o están BAJADAS: el tren viene. Cruzarse con otro vehículo en el paso no está prohibido, y un paso sin señalización se puede cruzar tras parar y comprobar que no viene tren."},{"id":6355,"bg":"Задължително ли е спирането пред жп прелез, когато той е без бариери?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато към прелеза приближава влак","ok":false,"i":null,"es":"sí, pero solo cuando se aproxima un tren"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Es obligatorio parar ante un paso a nivel sin barreras?","explain":"Sí, SIEMPRE: ante un paso a nivel sin barreras la parada es obligatoria en todos los casos, haya o no tren a la vista. Es la única forma segura de comprobar; 'solo si se acerca un tren' invierte la lógica de la norma."},{"id":6460,"bg":"Ще извърши ли нарушение водачът на автомобила, ако при тази ситуация завие наляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/82690.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Cometerá infracción el conductor si gira a la izquierda en esta situación?","explain":"SÍ, comete infracción.\n\nLO QUE MANDA AQUÍ. Sobre el semáforo hay un disco azul de DIRECCIÓN OBLIGATORIA que solo dibuja recto y derecha. La izquierda no está entre las direcciones autorizadas.\n\nPOR QUÉ EL VERDE NO LE SALVA. El semáforo en verde te autoriza a PASAR, no a tomar cualquier dirección. Un semáforo deja sin efecto las señales de prioridad (STOP, ceda el paso, rombo), pero nunca las de obligación ni las de prohibición.\n\nLAS MARCAS DE LA CALZADA repiten lo mismo con flechas pintadas, así que el aviso te llega por dos vías a la vez.\n\nCLAVE: verde significa 'puedes pasar', no 'puedes ir donde quieras'."},{"id":6475,"bg":"При спиране в тунел с дължина над 500 м, дистанцията между автомобилите трябва да е не по-малка от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 м","ok":true,"i":null,"es":"5 m"},{"t":"4 м","ok":false,"i":null,"es":"4 m"},{"t":"3 м","ok":false,"i":null,"es":"3 m"},{"t":"2 м","ok":false,"i":null,"es":"2 m"}],"f":8,"explain":"En túnel de más de 500 m, al parar (retención) deja mínimo 5 m con el de delante: ese hueco permite evacuar, maniobrar a los servicios de emergencia y aleja el fuego en caso de incendio. Es el dato numérico de túneles: 500 m → 5 m.","es":"Al parar en túnel de más de 500 m la distancia entre vehículos debe ser de no menos de:"},{"id":6479,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54367.png","v":null,"a":[{"t":"трябва да премина преди синия автомобил","ok":true,"i":null,"es":"debo pasar antes que el coche azul"},{"t":"спирам, за да пропусна синия автомобил и преминавам след него","ok":false,"i":null,"es":"paro para dejar al azul y paso después"},{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":false,"i":null,"es":"paro para esperar señal de paso del agente"}],"f":8,"es":"En esta situación:","explain":"Debo PASAR ANTES que el coche azul.\n\nEL AGENTE MANDA SOBRE EL STOP. Hay una señal de STOP en el cruce, pero cuando un agente dirige el tráfico, sus indicaciones dejan sin efecto las señales que reparten la prioridad. El orden es: regulador, después semáforo, después señales.\n\nSU POSTURA. Lo ves DE PERFIL, por su costado, con el brazo derecho extendido al frente. Desde el costado izquierdo con el brazo al frente se abren todas las direcciones.\n\nEL AZUL espera, porque a él la misma señal no le autoriza.\n\nCLAVE: si hay agente, deja de mirar las señales de prioridad. Ya no deciden nada."},{"id":6524,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57242.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"}],"f":8,"es":"En esta situación debo: (2 correctas)","explain":"MULTIRESPUESTA: paso antes que el rojo y antes que el azul.\n\nPOR QUÉ. El rombo amarillo mira hacia ti: circulas por la VÍA CON PRIORIDAD. Los dos coches llegan por brazos secundarios, así que ambos te ceden el paso a ti.\n\nUN COCHE A CADA LADO no cambia nada cuando tú vas por la prioritaria. La regla de la derecha decide entre vehículos de vías del mismo valor, y aquí no lo son.\n\nCLAVE: identifica primero si hay señal de prioridad. Solo cuando no la hay entras a mirar quién viene por la derecha."},{"id":6536,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58116.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al azul"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"}],"f":8,"es":"En esta situación debo: (2 correctas)","explain":"Dos cosas: paso antes que el vehículo rojo Y cedo el paso al azul.\n\nEL ROMBO AMARILLO A MI DERECHA es «vía con prioridad». Me dice que la calle por la que voy manda sobre las que la cruzan.\n\nEL ROJO LLEGA POR LA CALLE TRANSVERSAL, sin prioridad. Frente a él no tengo que hacer nada: es él quien me cede a mí. Por eso «paso antes que el rojo» es correcto y «dejar pasar al rojo» es falso.\n\nDEBAJO DEL ROMBO HAY UN CÍRCULO AZUL CON LA FLECHA DOBLADA A LA IZQUIERDA: dirección obligatoria a la izquierda. Mi intermitente izquierdo, encendido en el salpicadero, confirma la maniobra.\n\nEL AZUL VIENE DE FRENTE Y AHÍ ENTRA OTRA REGLA DISTINTA: el чл. 37 obliga al que gira a la izquierda a ceder el paso a los que circulan en sentido contrario. Estar en la vía con prioridad no me libera: el azul también está en ella, viene de cara, y yo soy el que cruza su trayectoria.\n\nCLAVE: dos reglas trabajando a la vez. El rombo resuelve el cruce con las calles laterales; el giro a la izquierda se resuelve aparte, con чл. 37, frente a los que vienen de cara. Contesta el cruce coche por coche, no de un golpe."},{"id":6553,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66833.png","v":null,"a":[{"t":"пропускам синия автомобил","ok":true,"i":null,"es":"cedo el paso al azul"},{"t":"преминавам преди синия автомобил","ok":false,"i":null,"es":"paso antes que el coche azul"}],"f":8,"es":"En esta situación:","explain":"Cedo el paso a la furgoneta azul.\n\nES UN CRUCE SIN SEÑALES Y SIN SEMÁFORO. Cuando no hay nada que reparta la prioridad, las dos vías valen lo mismo y se aplica la regla de la derecha del чл. 50, ал. 1: cedo a todo el que se me acerque por la derecha.\n\nEL AZUL LLEGA POR MI DERECHA. Con eso está resuelto: pasa él primero.\n\nQUE YO VAYA RECTO NO CAMBIA NADA. Es el error clásico: seguir de frente no es una maniobra privilegiada, no me da ninguna preferencia sobre el que llega por la derecha.\n\nPOR ESO «PASO ANTES QUE EL AZUL» ES FALSO: solo sería cierto si él llegara por mi izquierda, o si yo tuviera una señal de vía con prioridad, o un semáforo o un agente que me diera paso. No hay nada de eso.\n\nCLAVE: sin señales, sin semáforo y sin agente, manda la derecha. Vaya yo recto o gire."},{"id":6555,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68438.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"}],"f":8,"explain":"Dos cosas: cedo el paso al coche rojo Y paso antes que el azul.\n\nES UN CRUCE SIN SEÑALES NI SEMÁFORO, así que las tres vías valen lo mismo y todo se resuelve con la regla de la derecha (чл. 50, ал. 1). La forma segura de contestar es ir de uno en uno.\n\nEL ROJO ESTÁ A MI DERECHA. Le cedo. Por eso «pasar antes que el coche rojo» es falso.\n\nEL AZUL ESTÁ A MI IZQUIERDA. Yo estoy a la derecha de él, así que me cede a mí y paso antes. Por eso «dejar pasar al azul» es falso.\n\nYO GIRO A LA IZQUIERDA — el intermitente está encendido — PERO ESO NO AÑADE NADA AQUÍ. El чл. 37 obliga a ceder a los que vienen de frente cuando giras a la izquierda, y en esta escena no viene nadie de frente. La maniobra no me quita ni me da prioridad frente a los laterales.\n\nCLAVE: cruce sin señales = resuélvelo coche por coche, no de un vistazo. El de mi izquierda me cede; al de mi derecha le cedo yo. Y solo si hay alguien de frente entra además el чл. 37.","es":"En esta situación debo: (2 correctas)"},{"id":6560,"bg":"При тази ситуация с предимство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67148.png","v":null,"a":[{"t":"автомобила","ok":true,"i":null,"es":"el coche"},{"t":"мотоциклета","ok":false,"i":null,"es":"la moto"}],"f":8,"es":"En esta situación tiene prioridad:"},{"id":6563,"bg":"При тази ситуация първи трябва да премине:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68370.png","v":null,"a":[{"t":"червеният автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"зеленият автомобил","ok":false,"i":null,"es":"el coche verde"},{"t":"синият автомобил","ok":false,"i":null,"es":"el coche azul"}],"f":8,"es":"En esta situación el primero en pasar debe ser:"},{"id":6567,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68303.png","v":null,"a":[{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"}],"f":8,"es":"En esta situación debo: (2 correctas)"},{"id":6588,"bg":"Този знак изисква от водачите да спрат:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55422.png","v":null,"a":[{"t":"винаги, независимо дали по пресичания път се движи превозно средство","ok":true,"i":null,"es":"siempre, independientemente de si hay vehículos en la vía cruzada"},{"t":"само ако по пресичания път се движи превозно средство","ok":false,"i":null,"es":"solo si hay vehículos en la vía cruzada"},{"t":"ако те преценят, че е необходимо","ok":false,"i":null,"es":"si el conductor lo considera necesario"}],"f":8,"es":"Esta señal obliga a los conductores a parar:"},{"id":6594,"bg":"При този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56647.png","v":null,"a":[{"t":"е разрешено да премина, без да спирам, защото пътят, по който се движа, е с предимство","ok":true,"i":null,"es":"puedo pasar sin parar porque estoy en vía preferente"},{"t":"задължен съм да спра, преди да премина през кръстовището","ok":false,"i":null,"es":"estoy obligado a parar antes de cruzar"},{"t":"мога да премина, без да спирам, но трябва да пропусна ППС от другия път","ok":false,"i":null,"es":"puedo pasar sin parar pero cediendo el paso"}],"f":8,"explain":"Puedo pasar sin parar, porque circulo por la vía con prioridad.\n\nLA SEÑAL. Rombo amarillo con borde blanco: «Път с предимство» — vía con prioridad. Es del grupo Б, señales relativas a la prioridad.\n\nQUÉ TE DA. Preferencia sobre todos los que llegan por las vías que cruzan la tuya, durante todo el tramo hasta que aparezca «Край на пътя с предимство» — fin de vía con prioridad — o hasta que una tabla indique que la preferente tuerce.\n\nQUÉ NO TE DA. No te libera de nada más: sigues obligado a ceder a los que vienen de frente si giras a la izquierda, a los peatones y a quien ya está dentro del cruce. Y no te autoriza a entrar sin mirar.\n\n«ESTOY OBLIGADO A PARAR» describe el STOP, que es octogonal y rojo. «PUEDO PASAR SIN PARAR PERO CEDIENDO» describe el ceda el paso, triángulo invertido. Las tres señales conviven en las mismas preguntas y solo se distinguen por la forma.\n\nCLAVE: rombo = tengo prioridad. Triángulo invertido = cedo pero no paro. Octógono = paro siempre. Tres formas, tres conductas.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo».","es":"Con esta señal:"},{"id":6603,"bg":"Разрешено ли е на водача на ППС да навлезе в кръстовище, ако обстановката ще го принуди да спре в кръстовището и да възпрепятства преминаването през него?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, при разрешаващ сигнал на светофар","ok":false,"i":null,"es":"sí, con semáforo verde"},{"t":"да, но само когато се намира на пътя с предимство","ok":false,"i":null,"es":"sí, si estás en vía preferente"}],"f":8,"es":"¿Está permitido entrar en una intersección si la situación le obligará a parar dentro?","explain":"No: si vas a quedar detenido DENTRO de la intersección obstaculizando el cruce, no debes entrar, ni con semáforo verde ni circulando por vía con prioridad. Bloquear el cruce es infracción independiente de tu prioridad."},{"id":6605,"bg":"В кой от случаите водачът не трябва да навлиза в кръстовище?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато обстановката ще го принуди да спре в кръстовището, при което ще възпрепятства напречното движение","ok":true,"i":null,"es":"cuando tendría que parar en la intersección obstaculizando el paso"},{"t":"когато по напречния път приближава автомобил със специален режим на движение","ok":true,"i":null,"es":"cuando se acerca un vehículo de emergencia por la vía cruzada"},{"t":"когато преминаването се регулира от светофар със жълта мигаща светлина","ok":false,"i":null,"es":"cuando el semáforo tiene luz amarilla parpadeante"}],"f":8,"es":"¿En qué casos el conductor NO debe entrar en la intersección? (2 correctas)","explain":"Dos supuestos: cuando quedarías parado dentro obstaculizando el tráfico transversal, y cuando se aproxima un vehículo de emergencia con señales especiales. El ámbar intermitente solo exige precaución, no prohíbe entrar."},{"id":6679,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62132.png","v":null,"a":[{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"жълтият автомобил","ok":true,"i":null,"es":"el coche amarillo"}],"f":8,"es":"En esta situación tiene prioridad:"},{"id":6680,"bg":"При тази ситуация трябва да премина преди червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64639.png","v":null,"a":[{"t":"съм на пътя с предимство","ok":true,"i":null,"es":"estoy en vía preferente"},{"t":"се движа направо","ok":false,"i":null,"es":"voy recto"},{"t":"червеният автомобил завива наляво","ok":false,"i":null,"es":"el rojo gira a la izquierda"}],"f":8,"es":"En esta situación paso antes que el rojo porque:"},{"id":7965,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917965.png","v":null,"a":[{"t":"трябва да премина преди лекия автомобил","ok":true,"i":null,"es":"debo pasar antes que el turismo"},{"t":"трябва да пропусна лекия автомобил, който се движи направо","ok":false,"i":null,"es":"debo ceder el paso al turismo que va recto"}],"f":8,"es":"En esta situación:"},{"id":5334,"bg":"С този пътен знак се обозначава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40658.png","v":null,"a":[{"t":"автомобилен път","ok":true,"i":null,"es":"vía rápida"},{"t":"автомагистрала","ok":false,"i":null,"es":"autopista"},{"t":"път, за движение само на леки автомобили","ok":false,"i":null,"es":"vía solo para turismos"},{"t":"задължетелен път само за леки автомобили","ok":false,"i":null,"es":"vía obligatoria solo para turismos"}],"f":8,"es":"Esta señal de tráfico indica:","explain":"El camino de automoviles (pat za avtomobili) se distingue de la autopista. Solo para vehiculos de motor con velocidad maxima constructiva superior a 50 km/h."},{"id":5409,"bg":"При тази ситуация на автомагистрала:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41739.png","v":null,"a":[{"t":"на водача на лекия автомобил е забранено да пресича разделителната ивица","ok":true,"i":null,"es":"al conductor del turismo le está prohibido cruzar la franja divisoria"},{"t":"водачът на лекия автомобил може да пресече раздилителната ивица, когато няма автомобили в другото платно","ok":false,"i":null,"es":"el conductor del turismo puede cruzar la franja divisoria cuando no hay automóviles en la otra calzada"},{"t":"водачът на лекия автомобил трябва да пропусне товарния автомобил","ok":false,"i":null,"es":"el conductor del turismo debe ceder el paso al camión"},{"t":"водачът на лекия автомобил преминава преди товарния автомобил","ok":false,"i":null,"es":"el conductor del turismo pasa antes que el camión"}],"f":8,"es":"En esta situación en autopista:","explain":"En autopista NUNCA se puede cruzar la mediana, aunque el otro carril este libre. Es una de las prohibiciones absolutas de la autopista."},{"id":8277,"bg":"При движение по скоростен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира пътното превозно средство за престой извън специално обозначените за това места","ok":true,"i":null,"es":"detener el vehículo para una parada fuera de los lugares especialmente señalizados para ello"},{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"invadir o cruzar la mediana, incluso en los lugares donde está interrumpida"},{"t":"да завива в обратна посока","ok":true,"i":null,"es":"girar en sentido contrario"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":8,"es":"Al circular por vía rápida al conductor le está prohibido: (3 correctas)","explain":"Tres prohibiciones de vía rápida: parar fuera de los lugares señalizados, invadir o cruzar la mediana (incluso interrumpida) y girar en sentido contrario. Remolcar con barra rígida está permitido: es la opción trampa recurrente."},{"id":5621,"bg":"Паркирането в жилищна зона, обозначена със съответния пътен знак, е разрешено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"само на специално обозначените за това места","ok":true,"i":null,"es":"solo en los lugares especialmente señalizados para ello"},{"t":"в най-дясната пътна лента","ok":false,"i":null,"es":"en el carril más a la derecha"},{"t":"най-вдясно на пътното платно","ok":false,"i":null,"es":"lo más a la derecha de la calzada"},{"t":"най-вдясно на платното за движение","ok":false,"i":null,"es":"lo más a la derecha de la calzada de circulación"}],"f":8,"es":"El estacionamiento en una zona residencial, señalizada con la señal correspondiente, está permitido:","explain":"En zona residencial señalizada solo se estaciona en los lugares específicamente marcados para ello: la calle es espacio compartido con peatones y niños, no un aparcamiento libre."},{"id":11624,"bg":"В жилищна зона обозначена със съответния пътен знак, водачите на МПС трябва да се движат със скорост не по-висока от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"20 km/h","ok":true,"i":null,"es":"20 km/h"},{"t":"30 km/h","ok":false,"i":null,"es":"30 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"}],"f":8,"es":"En una zona residencial señalizada con la señal correspondiente, los conductores deben circular a una velocidad no superior a:","explain":"20 km/h: en zona residencial señalizada la calle es espacio compartido con peatones y niños jugando, por eso el límite es el más bajo del código."},{"id":5558,"bg":"Задължително ли е присъствието на водача в близост до превозното средство, когато то е спряно за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Es obligatoria la presencia del conductor cerca del vehículo cuando está detenido en una parada?","explain":"Sí: el conductor debe permanecer cerca del vehículo durante la parada breve (престой), para poder moverlo si estorba. Eso es precisamente lo que distingue la parada del estacionamiento."},{"id":5572,"bg":"Спирането след знака върху платното за движение за качване на пътника е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42890.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":8,"es":"Detenerse después de la señal, sobre la calzada, para que suba el pasajero es:","explain":""},{"id":5576,"bg":"При тази ситуация правилно ли е спрян за престой лекият автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/160581.png","v":null,"a":[{"t":"да, защото не пречи на движението","ok":true,"i":null,"es":"sí, porque no interfiere con el tráfico"},{"t":"не, защото престоят е разрешен само от дясната страна на платното за движение","ok":false,"i":null,"es":"no, porque la parada solo está permitida en el lado derecho de la calzada"}],"f":8,"es":"En esta situación, ¿está el turismo correctamente detenido (parada)?","explain":""},{"id":5612,"bg":"Кой от автомобилите е спрян правилно за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43862.png","v":null,"a":[{"t":"товарният автомобил","ok":false,"i":null,"es":"el camión"},{"t":"автобусът","ok":true,"i":null,"es":"el autobús"}],"f":8,"es":"¿Cuál de los automóviles está correctamente detenido (parada)?","explain":""},{"id":5620,"bg":"На кое от изброените места е забранено спирането за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на места, където ППС създава опасност или е пречка за движението","ok":true,"i":null,"es":"en lugares donde el vehículo crea peligro u obstaculiza el tráfico"},{"t":"на място, където ППС закрива от другите участници в движението сигнал на светофара","ok":true,"i":null,"es":"en un lugar donde el vehículo oculta a los demás usuarios la señal del semáforo"},{"t":"до друго, спряно за престой или паркирано ППС, от страната на движението","ok":true,"i":null,"es":"junto a otro vehículo parado o aparcado, en el lado de la circulación"},{"t":"на път с еднопосочно движение","ok":false,"i":null,"es":"en vía de sentido único"}],"f":8,"es":"¿En cuál de los lugares indicados está prohibida la detención (parada)? (3 correctas)","explain":"La parada está prohibida donde el vehículo crea peligro u obstáculo, donde tapa un semáforo o señal a los demás, y en doble fila (junto a otro vehículo parado por el lado de circulación). En vía de sentido único la parada no está prohibida por sí misma."},{"id":5634,"bg":"Кой от автомобилите е паркиран в нарушение на правилата за движение?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43879.png","v":null,"a":[{"t":"товарният автомобил","ok":true,"i":null,"es":"el camión"},{"t":"автобусът","ok":false,"i":null,"es":"el autobús"}],"f":8,"es":"¿Cuál de los automóviles está estacionado infringiendo las normas de circulación?","explain":""},{"id":5643,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"пред входовете на паркове, театри, кина, предприятия","ok":true,"i":null,"es":"delante de las entradas de parques, teatros, cines y empresas"},{"t":"на места, където е възможно да влизат или да излизат пътни превозни средства","ok":true,"i":null,"es":"en lugares donde los vehículos puedan entrar o salir"},{"t":"непосредствено пред входовете на гаражи, когато това затруднява достъпа до тях","ok":true,"i":null,"es":"inmediatamente ante las entradas de garajes, cuando dificulta el acceso"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en un tramo de carretera en obras"}],"f":8,"es":"El estacionamiento está prohibido: (3 correctas)","explain":"Prohibido estacionar delante de entradas de parques, teatros, cines y empresas, en accesos de vehículos y ante entradas de garajes cuando se dificulta su uso. Un tramo en obras prohíbe el estacionamiento solo si está señalizado."},{"id":5649,"bg":"При паркиране върху платното за движение, водачът е в нарушение, ако разстоянието между ППС и пътната маркировка, забранена за пресичане, е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"1 м","ok":true,"i":null,"es":"1 m"},{"t":"2 м","ok":true,"i":null,"es":"2 m"},{"t":"2.5 м","ok":true,"i":null,"es":"2,5 m"},{"t":"3.5 м","ok":false,"i":null,"es":"3,5 m"}],"f":8,"es":"Al estacionar en la calzada, el conductor comete infracción si la distancia entre el vehículo y la marca vial que está prohibido cruzar es: (3 correctas)","explain":"Hay infracción si al estacionar dejas menos de 3 m hasta una marca vial que está prohibido cruzar: obligarías a los demás a pisarla. Por eso 1 m, 2 m y 2,5 m son infracción y 3,5 m no."},{"id":5650,"bg":"Разрешен ли е престоят на ППС в участъци от пътя, които са в ремонт?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Está permitida la parada de vehículos en tramos de vía en obras?","explain":"Sí: la PARADA (detención breve) en tramos en obras está permitida. Lo que puede estar restringido por señalización es el estacionamiento prolongado."},{"id":5662,"bg":"При отстраняване на повреда по ППС, което се намира на платно за движение, водачът е задължен:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да е облечен със светлоотразителна жилетка, когато се намира извън превозното средство","ok":true,"i":null,"es":"llevar chaleco reflectante cuando se encuentre fuera del vehículo"},{"t":"да обозначи превозното средство","ok":true,"i":null,"es":"señalizar el vehículo"},{"t":"да съобщи на контролните органи за повредата","ok":false,"i":null,"es":"comunicar la avería a las autoridades de control"},{"t":"да се обади на „пътна помощ”","ok":false,"i":null,"es":"llamar a la asistencia en carretera"}],"f":8,"es":"Al reparar una avería de un vehículo que se encuentra en la calzada, el conductor está obligado a: (2 correctas)","explain":"Al reparar una avería en la calzada: chaleco reflectante fuera del vehículo y señalizar el vehículo (triángulo, luces de emergencia). Avisar a las autoridades o llamar a la grúa no son obligaciones legales."},{"id":8283,"bg":"Този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/125668477.png","v":null,"a":[{"t":"указва място, определено за паркиране на ППС, обслужващи хора с трайни увреждания","ok":true,"i":null,"es":"indica lugar reservado para aparcar vehículos que sirven a personas con discapacidad"},{"t":"предупреждава за възможна поява на ППС, обслужващи хора с трайни увреждания","ok":false,"i":null,"es":"advierte de posible presencia de esos vehículos"},{"t":"забранява движението на ППС, обслужващи хора с трайни увреждания","ok":false,"i":null,"es":"prohíbe la circulación de esos vehículos"},{"t":"указва пътна лента за ППС, обслужващи хора с трайни увреждания","ok":false,"i":null,"es":"indica carril para esos vehículos"}],"f":8,"es":"Esta señal:"},{"id":5682,"bg":"Допълнителна задна светлина за мъгла е разрешено да се използва:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"при движение през нощта","ok":false,"i":null,"es":"de noche"},{"t":"винаги при намалена видимост","ok":false,"i":null,"es":"siempre con visibilidad reducida"},{"t":"само когато видимостта е намалена под 50 м","ok":true,"i":null,"es":"solo cuando la visibilidad está reducida por debajo de 50 m"}],"f":8,"es":"La luz antiniebla trasera adicional está permitido usarla:","explain":"La antiniebla trasera solo con visibilidad reducida por debajo de 50 m: es una luz muy intensa que deslumbra al que te sigue. De noche despejada o con niebla ligera está prohibida."},{"id":5712,"bg":"При пътуване на дълги разстояния за водачът с малък опит ще бъде по-безопасно ако:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"избягва пътуването през нощта","ok":true,"i":null,"es":"evitar viajar de noche"},{"t":"не се движи с високи скорости","ok":true,"i":null,"es":"no circular a altas velocidades"},{"t":"избягва движението по автомагистрали","ok":false,"i":null,"es":"evitar circular por autopistas"}],"f":8,"es":"En viajes de larga distancia, para el conductor con poca experiencia será más seguro si: (2 correctas)","explain":"Para el conductor novato es más seguro evitar la noche (menos visibilidad, más fatiga) y no ir a altas velocidades. Las autopistas NO deben evitarse: estadísticamente son las vías más seguras."},{"id":5716,"bg":"Какви са последиците за водача, когато той управлява продържително време при нерегулирана седалка?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"по-бързо настъпване на умора","ok":true,"i":null,"es":"la aparición más rápida de la fatiga"},{"t":"натоварване и болки в гръбначния стълб и мускулатурата","ok":true,"i":null,"es":"sobrecarga y dolores en la columna vertebral y la musculatura"},{"t":"остава по-дълго време концентриран","ok":false,"i":null,"es":"permanece concentrado durante más tiempo"},{"t":"намаляване на умората","ok":false,"i":null,"es":"la reducción de la fatiga"}],"f":8,"es":"¿Cuáles son las consecuencias para el conductor cuando conduce mucho tiempo con el asiento mal regulado? (2 correctas)","explain":"Asiento mal regulado durante horas = fatiga más rápida y sobrecarga con dolores en columna y musculatura. Jamás mejora la concentración: la postura incorrecta la deteriora."},{"id":6129,"bg":"Какво въздействие оказва приемането на голямо количество тонизиращи напитки - кафе или чай, за преодоляване умората на водача?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"има кратковременен ободрителен ефект","ok":true,"i":null,"es":"tiene un efecto estimulante de corta duración"},{"t":"може да предизвика нервно напрежение","ok":true,"i":null,"es":"puede provocar tensión nerviosa"},{"t":"позволява на водача да управлява продължително време без да чувства умора","ok":false,"i":null,"es":"permite al conductor conducir durante mucho tiempo sin sentir fatiga"}],"f":8,"es":"¿Qué efecto tiene tomar gran cantidad de bebidas estimulantes —café o té— para superar la fatiga del conductor? (2 correctas)","explain":"El café o té en gran cantidad da un estímulo de CORTA duración y puede provocar tensión nerviosa. No elimina la fatiga real: el único remedio verdadero es descansar."},{"id":6151,"bg":"При умора на водача риска от попадане в ПТП се повишава поради:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"притъпяване на бдителността","ok":true,"i":null,"es":"embotamiento de la atención (vigilancia)"},{"t":"понижаване на концентрацията на вниманието","ok":true,"i":null,"es":"la disminución de la concentración de la atención"},{"t":"намаляване на времето за реакция","ok":false,"i":null,"es":"la reducción del tiempo de reacción"}],"f":8,"es":"Con el conductor fatigado, el riesgo de accidente aumenta debido a: (2 correctas)","explain":"La fatiga aumenta el riesgo por el embotamiento de la vigilancia y la caída de la concentración. Ojo: el tiempo de reacción AUMENTA con la fatiga (la opción dice 'reducción', por eso es falsa)."},{"id":5993,"bg":"Разрешено ли е да превозвате пътници в товарно ремарке?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"¿Está permitido transportar pasajeros en un remolque de carga?","explain":"No: está prohibido transportar pasajeros en un remolque de carga. No tiene asientos, cinturones ni protección alguna para personas."},{"id":5996,"bg":"Задължение на водача е превозваният товар да бъде:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"покрит, когато отразява светлината и може да заслепи други участници в движението","ok":true,"i":null,"es":"cubierto, cuando refleja la luz y puede deslumbrar a otros usuarios de la vía"},{"t":"укрепен","ok":true,"i":null,"es":"sujeto (asegurado)"},{"t":"застрахован","ok":false,"i":null,"es":"asegurado"},{"t":"опакован съгласно изискванията на производителя","ok":false,"i":null,"es":"embalado según los requisitos del fabricante"}],"f":8,"es":"Es obligación del conductor que la carga transportada esté: (2 correctas)","explain":"La carga debe estar SUJETA (укрепен = bien amarrada) y cubierta cuando refleja la luz y puede deslumbrar. Ojo con la trampa lingüística: 'застрахован' (asegurado = con seguro) no es un requisito de la carga."},{"id":6008,"bg":"При движение през нощта по кой от изброените начини може да се обозначи товар, който излиза с повече от 1 м отпред на най-издадената част на превозното средство?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с бял светлоотразител","ok":true,"i":null,"es":"con reflectante BLANCO"},{"t":"с бяла светлина","ok":true,"i":null,"es":"con luz BLANCA"},{"t":"с червен флаг","ok":false,"i":null,"es":"con bandera roja"},{"t":"с червена светлина","ok":false,"i":null,"es":"con luz ROJA"}],"f":8,"es":"De noche, ¿cómo puede señalizarse la carga que sobresale más de 1 m por DELANTE de la parte más saliente del vehículo? (2 correctas)","explain":"La carga sobresale por DELANTE (ojo: la pregunta dice 'отпред'): de noche se señaliza con reflectante BLANCO o luz BLANCA, los colores que corresponden al frente del vehículo. La bandera roja es señalización diurna y la luz roja corresponde a salientes TRASEROS."},{"id":6013,"bg":"Товарът не се обозначава, ако излиза отстрани на най-издадената част на ППС на разстояние:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"до 0,2 м","ok":true,"i":null,"es":"hasta 0.2 m"},{"t":"до 0,5 м","ok":false,"i":null,"es":"hasta 0.5 m"},{"t":"до 1,0 м","ok":false,"i":null,"es":"hasta 1.0 m"},{"t":"до 1,5 м","ok":false,"i":null,"es":"hasta 1.5 m"}],"f":8,"es":"La carga no necesita señalizarse si sobresale POR LOS LADOS:","explain":"Hasta 0,2 m por los lados no se exige señalización: es el margen tolerado. Cualquier saliente lateral mayor debe señalizarse porque invade el espacio de otros carriles."},{"id":5451,"bg":"Извършва ли нарушение водач, който при изпреварване принуждава изпреварваното ППС да промени посоката си на движение?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Comete infracción el conductor que, al adelantar, obliga al vehículo adelantado a cambiar su dirección de marcha?","explain":"Sí, comete infracción: el que adelanta no puede obligar al adelantado a cambiar su trayectoria ni su velocidad. Si tu maniobra fuerza al otro a apartarse, la has hecho mal legalmente."},{"id":8300,"bg":"Подлежи ли на наказание водач, който без да има това право, паркира на място определено за превозно средство обслужващо хора с трайни увреждания?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"},{"t":"не, освен в случаите, когато превозното средство се паркира на това място през нощта","ok":false,"i":null,"es":"no, salvo cuando el vehículo se estaciona en ese lugar durante la noche"}],"f":8,"es":"¿Es sancionable el conductor que, sin tener derecho, estaciona en un lugar reservado a vehículos que atienden a personas con discapacidad permanente?","explain":"Sí, es sancionable: estacionar sin derecho en plaza reservada para personas con discapacidad es infracción a cualquier hora, también de noche."},{"id":5319,"bg":"Разрешено ли е да се премества превозно средство участвало в пътнотранспортно произшествие с пострадали хора?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да, когато с него трябва да се превозят пострадалите до здравно заведение","ok":true,"i":null,"es":"sí, cuando con él haya que transportar a los heridos a un centro de salud"},{"t":"да, когато пречи на движението","ok":true,"i":null,"es":"sí, cuando obstaculiza el tráfico"},{"t":"да, разрешено е във всички случаи","ok":false,"i":null,"es":"sí, está permitido en todos los casos"},{"t":"не, забранено е във всички случаи","ok":false,"i":null,"es":"no, está prohibido en todos los casos"}],"f":8,"es":"¿Está permitido mover un vehículo implicado en un accidente de tráfico con personas heridas? (2 correctas)","explain":"Se puede mover el vehículo del accidente con heridos en dos casos: para transportar a los heridos a un centro de salud o cuando obstaculiza el tráfico. Fuera de eso, la posición debe conservarse para el atestado."},{"id":5321,"bg":"Кои от изброените действия трябва да предприеме водачът при ПТП с превозно средство обозначено с опознавателен знак за опасен товар:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да стои на безопасно разстояние от превозното средство освен ако се налага да спаси нечий живот","ok":true,"i":null,"es":"mantenerse a distancia segura del vehículo, salvo que haya que salvar la vida de alguien"},{"t":"да се отнася внимателно с изсипания на пътя товар независимо от неговото количество","ok":true,"i":null,"es":"tratar con cuidado la carga derramada en la vía, independientemente de su cantidad"},{"t":"да премести това превозно средство извън платното за движение","ok":false,"i":null,"es":"apartar ese vehículo fuera de la calzada"},{"t":"да отстрани опасния товар от пътя","ok":false,"i":null,"es":"retirar la carga peligrosa de la vía"}],"f":8,"es":"¿Cuáles de las acciones indicadas debe emprender el conductor en un accidente con un vehículo señalizado con el distintivo de mercancías peligrosas?: (2 correctas)","explain":"Con mercancías peligrosas: mantente a distancia segura (salvo para salvar una vida) y trata con extremo cuidado cualquier derrame. Apartar el vehículo o retirar la carga tú mismo puede provocar la catástrofe que intentas evitar."},{"id":5348,"bg":"Задължен ли е водачът участник в ПТП без пострадали хора да оказва съдействие за установяване на вредите от произшествието?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато вредите са значителни","ok":false,"i":null,"es":"sí, pero solo cuando los daños son significativos"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Está obligado el conductor implicado en un accidente sin heridos a colaborar en la determinación de los daños del accidente?","explain":"Sí, en todos los casos: en un accidente sin heridos los implicados están obligados a colaborar en la determinación de los daños, sean grandes o pequeños (rellenar el parte amistoso, intercambiar datos)."},{"id":5354,"bg":"Телефонен номер 112 е:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"единен европейски телефонен номер за спешни и аварийни обаждания","ok":true,"i":null,"es":"el número único europeo de emergencias"},{"t":"телефонен номер за денонощна пътна помощ","ok":false,"i":null,"es":"el número de asistencia en carretera 24 horas"}],"f":8,"es":"El número de teléfono 112 es:","explain":"El 112 es el número único europeo de emergencias: policía, bomberos y ambulancia en toda la UE. No es un servicio de asistencia mecánica en carretera."},{"id":5543,"bg":"След кой от тези знаци е забранено спирането за престой върху платното за движение?","p":1,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42085.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42086.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42087.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42088.png","es":""}],"f":8,"es":"¿Después de cuál de estas señales está prohibida la parada breve en la calzada? (3 correctas)","explain":""},{"id":5902,"bg":"Значението на кой от показаните немигащи сигнали на светофара е “Преминаването е забранено”?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42121.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42122.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42123.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42124.png","es":""}],"f":8,"es":"¿Cuál de las señales fijas (no parpadeantes) del semáforo mostradas significa 'Prohibido el paso'? (2 correctas)","explain":"Las DOS primeras: el semáforo con la luz ROJA sola y el semáforo con ROJA + ÁMBAR encendidas a la vez.\n\nROJO SOLO es la prohibición básica: no puedes entrar en el cruce ni rebasar la línea de detención.\n\nROJO + ÁMBAR es la misma prohibición con un aviso añadido: el verde está a punto de llegar. El rojo sigue encendido, así que el paso sigue prohibido. Es la que más gente falla, porque el ámbar hace pensar en «prepárate para salir» y se lee como permiso.\n\nEL VERDE es la tercera imagen: paso permitido. Descartado.\n\nEL ÁMBAR SOLO es la cuarta y aquí está la trampa fina. También impide entrar en el cruce, pero su significado oficial en la ley es «Внимание! Спри!» — atención, para —, no «преминаването е забранено». La pregunta pide literalmente las señales que significan «prohibido el paso», y esa etiqueta la llevan solo el rojo y el rojo+ámbar.\n\nCLAVE: para esta pregunta, «prohibido el paso» = las dos que llevan rojo encendido. El ámbar solo tiene nombre propio y va en otra pregunta."},{"id":13554,"bg":"Когато няма други ограничения, водачът на МПС от категория В при движение по автомагистрала не трябва да превишава:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"140 km/h","ok":true,"i":null,"es":"140 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"}],"f":8,"es":"Cuando no hay otras restricciones, el conductor de un vehículo categoría B en autopista no debe superar:","explain":"140 km/h: es el límite de los turismos categoría B en autopista búlgara cuando no hay otra restricción señalizada. En vía rápida baja a 120 y fuera de población a 90."},{"id":5239,"bg":"Номерът на път по международната класификация се означава с:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20034.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20035.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20036.png","es":""}],"f":8,"es":"El número de una carretera según la clasificación internacional se indica con:","explain":"Las carreteras internacionales en Bulgaria usan la clasificacion E (Europa). Las nacionales usan A (autopista), I/II/III segun categoria."},{"id":5249,"bg":"Кой от пътните знаци предупреждава, че платното за движение е стеснено отдясно?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334669.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21263.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21264.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334667.png","es":""}],"f":8,"es":"¿Cuál de las señales advierte que la calzada se estrecha por la derecha?","explain":"Las senales de estrechamiento muestran flechas que se juntan. Si la derecha desaparece = estrechamiento por la derecha."},{"id":5548,"bg":"След кой от тези знаци е забранено паркирането върху платното за движение?","p":1,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42142.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/160215.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42087.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42088.png","es":""}],"f":8,"es":"¿Después de cuál de estas señales está prohibido el estacionamiento en la calzada? (3 correctas)","explain":""},{"id":5432,"bg":"Когато налягането на въздуха в автомобилната гума е по-ниско от предписаното, протекторът на гумата се износва:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"в двата края, по цялата окръжност","ok":true,"i":null,"es":"en ambos bordes, en toda la circunferencia"},{"t":"неравномерно, на отделни места","ok":false,"i":null,"es":"de forma irregular, en puntos aislados"},{"t":"в средата на протектора по цялата окръжност","ok":false,"i":null,"es":"en el centro de la banda de rodadura, en toda la circunferencia"},{"t":"винаги в дясната част по посока на въртенето","ok":false,"i":null,"es":"siempre en la parte derecha según el sentido de giro"}],"f":7,"es":"Cuando la presión de aire del neumático es más baja que la prescrita, la banda de rodadura se desgasta:","explain":"Con presión baja el neumático se apoya en los BORDES y se desgasta por ambos lados de la banda en toda la circunferencia. El desgaste central es el síntoma contrario (presión alta); los puntos aislados indican otros defectos."},{"id":6159,"bg":"Антиблокиращата спирачна система (ABS) не допуска блокирането на:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"колелата на автомобила в процеса на спиране","ok":true,"i":null,"es":"las ruedas del automóvil durante la frenada"},{"t":"спирачния педал","ok":false,"i":null,"es":"el pedal de freno"},{"t":"буталото в главния спирачен цилиндър","ok":false,"i":null,"es":"el pistón del cilindro maestro de freno"}],"f":7,"es":"El sistema antibloqueo de frenos (ABS) no permite el bloqueo de:","explain":"El ABS impide el bloqueo de las RUEDAS al frenar: modula la presión para que sigan girando y puedas dirigir. No tiene nada que ver con bloquear el pedal ni el pistón del cilindro maestro."},{"id":6163,"bg":"В кой случай ефектът от действието на антиблокиращата спирачна система (ABS) е най–голям?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при спиране на хлъзгъв път","ok":true,"i":null,"es":"al frenar en carretera resbaladiza"},{"t":"при спиране на сух път","ok":false,"i":null,"es":"al frenar en carretera seca"},{"t":"когато накладките на спирачните механизми са износени","ok":false,"i":null,"es":"cuando las pastillas de freno están desgastadas"}],"f":7,"es":"¿Cuándo es mayor el efecto del sistema ABS?","explain":"El ABS rinde más en carretera RESBALADIZA: ahí es donde las ruedas se bloquearían con facilidad y el sistema marca la diferencia entre dirigir o deslizar. En seco casi no interviene, y las pastillas gastadas son otro problema."},{"id":5442,"bg":"Как се контролира нивото на течността в охладителната уредба на МПС?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"като се следи нивото на течността в разширителния резервоар","ok":true,"i":null,"es":"vigilando el nivel del líquido en el depósito de expansión"},{"t":"зависи от вида на охладителната течност","ok":false,"i":null,"es":"depende del tipo de líquido refrigerante"},{"t":"нивото на течността в охладителната уредба не се контролира","ok":false,"i":null,"es":"el nivel del líquido del sistema de refrigeración no se controla"}],"f":7,"es":"¿Cómo se controla el nivel del líquido del sistema de refrigeración del vehículo?","explain":"El nivel del refrigerante se controla mirando el depósito de expansión (entre MIN y MAX, en frío). No depende del tipo de líquido y por supuesto que se controla: quedarse sin refrigerante funde el motor."},{"id":6156,"bg":"Вредно ли е за хората шумовото замърсяване, предизвикано от превозните средства при движение?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Es dañina para las personas la contaminación acústica que producen los vehículos al circular?","explain":"Sí: el ruido del tráfico es contaminación acústica dañina: estrés, trastornos del sueño y problemas cardiovasculares en la población expuesta. Es parte del bloque de conducción responsable."},{"id":5220,"bg":"Кои от изброените правила се прилагат при движение в населено място?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътниците в лекия автомобил може да не използват обезопасителните колани","ok":false,"i":null,"es":"los pasajeros del turismo pueden no usar los cinturones de seguridad"},{"t":"по двулентовите двупосочни пътища пешеходците могат да пресичат платното за движение и извън пешеходните пътеки","ok":true,"i":null,"es":"en vías de dos carriles y doble sentido los peatones pueden cruzar la calzada también fuera de los pasos de peatones"},{"t":"допуска се паркиране на платното за движение","ok":true,"i":null,"es":"se permite estacionar en la calzada"},{"t":"може да се паркира на обозначени места върху тротоарите","ok":true,"i":null,"es":"se puede estacionar en lugares señalizados sobre las aceras"}],"f":7,"es":"¿Cuáles de las siguientes normas se aplican al circular en población? (3 correctas)","explain":"En población: los peatones pueden cruzar fuera de los pasos en vías de dos carriles y doble sentido, se permite estacionar en la calzada y también sobre aceras EN lugares señalizados. Los cinturones son SIEMPRE obligatorios: esa es la falsa."},{"id":5233,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23560.png","v":null,"a":[{"t":"предупреждава за кръстовище с път без предимство","ok":true,"i":null,"es":"advierte de una intersección con una vía sin prioridad"},{"t":"указва, че на следващото кръстовище задължително трябва да се премине направо","ok":false,"i":null,"es":"indica que en la próxima intersección es obligatorio seguir de frente"},{"t":"сигнализира за край на пътя с предимство","ok":false,"i":null,"es":"señaliza el fin de la vía con prioridad"},{"t":"сигнализира за начало на пътя с предимство","ok":false,"i":null,"es":"señaliza el inicio de la vía con prioridad"}],"f":7,"es":"Esta señal de tráfico:","explain":"Advierte de una intersección con una vía SIN prioridad.\n\nLA SEÑAL. Triángulo rojo con un trazo vertical GRUESO y ramales FINOS a los lados: «Кръстовище с път без предимство».\n\nCÓMO SE LEE. El trazo grueso eres tú, la vía por la que circulas: la preferente. Los finos son las secundarias que se te incorporan. El aviso es «atención, viene un cruce en el que tú mandas».\n\nQUÉ NO SIGNIFICA. No te obliga a nada. Los triángulos rojos son señales de PELIGRO: avisan, no ordenan. Sigues teniendo que moderar y comprobar que los de las secundarias te ceden de verdad.\n\n«FIN DE LA VÍA CON PRIORIDAD» e «INICIO DE LA VÍA CON PRIORIDAD» son señales del grupo de prioridad, con forma de rombo amarillo, no de triángulo. El grupo se distingue por la forma antes que por el dibujo.\n\n«OBLIGATORIO SEGUIR DE FRENTE» sería un círculo azul: obligación, no peligro.\n\nCLAVE: es la misma gramática del grosor que ya usas en las tablas de dirección — grueso manda, fino cede. Aquí aplicada a un triángulo de peligro.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6028,"bg":"При тази ситуация задължени ли сте да се съобразявате с поведението на децата?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25999.png","v":null,"a":[{"t":"да, защото са в близост до платното за движение","ok":true,"i":null,"es":"sí, porque están cerca de la calzada"},{"t":"да, защото са деца","ok":true,"i":null,"es":"sí, porque son niños"},{"t":"не, защото се движат по тротоара","ok":false,"i":null,"es":"no, porque van por la acera"},{"t":"не, защото ме виждат","ok":false,"i":null,"es":"no, porque me ven"}],"f":7,"es":"En esta situación, ¿estás obligado a tener en cuenta el comportamiento de los niños? (2 correctas)","explain":"SI, siempre que haya ninos cerca de la calzada, aunque esten en la acera. Son participantes impredecibles."},{"id":6066,"bg":"За какво сигнализира стоящият на тротоара пешеходец, когато е с изпъната нагоре или напречно на пътя ръка?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"за намерението си да навлезе на платното за движение","ok":true,"i":null,"es":"de su intención de entrar en la calzada"},{"t":"указва на водачите, че ще изчака преминаващите автомобили","ok":false,"i":null,"es":"indica a los conductores que esperará a que pasen los automóviles"},{"t":"дава знак на другите пешеходци, че могат да преминат през платното за движение","ok":false,"i":null,"es":"hace una señal a los demás peatones de que pueden cruzar la calzada"},{"t":"дава знак на другите пешеходци, да не преминават през платното за движение","ok":false,"i":null,"es":"hace una señal a los demás peatones de que no crucen la calzada"}],"f":7,"es":"¿Qué señaliza el peatón parado en la acera con el brazo extendido hacia arriba o en perpendicular a la carretera?","explain":"El peatón con el brazo extendido en alto o perpendicular a la vía señala su INTENCIÓN DE ENTRAR en la calzada: es su forma legal de anunciar el cruce. No es una señal hacia otros peatones ni una renuncia a cruzar."},{"id":6692,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височината му, включително товара, е 4,5 м","ok":true,"i":null,"es":"4.5 m"},{"t":"широчината му, включително товара, е 2,8 м","ok":true,"i":null,"es":"su ANCHURA, incluyendo carga, es 2.8 m"},{"t":"дължината му, включително товара, е 9 м","ok":false,"i":null,"es":"su LONGITUD, incluyendo carga, es 9 m"}],"f":7,"es":"Un vehículo es 'fuera de gálibo' cuando: (2 correctas)","explain":"Un vehículo es 'fuera de gálibo' si supera los límites: altura mayor de 4 m (por eso 4,5 m cuenta) o anchura mayor de 2,55 m (por eso 2,8 m cuenta). Una longitud de 9 m NO supera el límite legal de longitud."},{"id":11820,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828421.png","v":null,"a":[{"t":"само ремаркетата с маса над 750 kg","ok":false,"i":null,"es":"solo los remolques de masa superior a 750 kg"},{"t":"всички ремаркета, независимо от тяхната маса","ok":true,"i":null,"es":"todos los remolques, independientemente de su masa"},{"t":"само ремаркетата с две и повече оси","ok":false,"i":null,"es":"solo los remolques de dos o más ejes"},{"t":"всички ремаркета, независимо от броя на осите","ok":true,"i":null,"es":"todos los remolques, independientemente del número de ejes"}],"f":7,"es":"Con este signo distintivo se identifican: (2 correctas)","explain":"Dos: TODOS los remolques, sea cual sea su masa, y todos, sea cual sea su número de ejes.\n\nQUÉ VES. La parte trasera de un remolque con las placas reflectantes: rectángulos amarillos con borde rojo. Es el «опознавателен знак» — signo distintivo — obligatorio para remolques.\n\nLAS DOS RESPUESTAS DICEN LO MISMO desde dos ángulos: la obligación no depende de la masa ni del número de ejes. Cualquier remolque las lleva.\n\n«SOLO LOS DE MÁS DE 750 kg» y «SOLO LOS DE DOS O MÁS EJES» son los distractores, y otra vez el problema está en la palabra «SOLO». Los 750 kg son un umbral real pero de OTRA cosa: separa la categoría B de la BE del permiso. Aquí no pinta nada.\n\nPOR QUÉ IMPORTAN ESAS PLACAS. De noche indican al que se acerca por detrás que lo que ve es un conjunto largo y lento, no un coche. Confundirlos es una causa habitual de alcance en carretera.\n\nCLAVE: cuando una opción dice «solo cuando...», comprueba si el requisito pertenece de verdad a esa norma o lo han traído de otra. Aquí los 750 kg vienen de las categorías del permiso.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6280,"bg":"В кои случаи, при тази допълнителна табела, водачът е задължен да спазва забраната, въведена с пътния знак?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/159579.png","v":null,"a":[{"t":"при снеговалеж","ok":true,"i":null,"es":"cuando nieva"},{"t":"при сняг на платното за движение","ok":true,"i":null,"es":"con nieve en la calzada"},{"t":"при температури, при които пътното покритие може да се заледи","ok":true,"i":null,"es":"con temperaturas en las que el pavimento puede helarse"},{"t":"при силен дъжд","ok":false,"i":null,"es":"con lluvia intensa"}],"f":7,"es":"¿En qué casos, con esta tablilla adicional, el conductor está obligado a respetar la prohibición de la señal? (3 correctas)","explain":"Tres casos: cuando nieva, cuando hay nieve sobre la calzada, y cuando la temperatura permite que el pavimento se hiele.\n\nQUÉ VES. La señal de prohibido estacionar con una tablilla adicional debajo con un copo de nieve.\n\nQUÉ HACE UNA TABLILLA ADICIONAL. No cambia la prohibición: limita CUÁNDO se aplica. Con el copo, la prohibición de estacionar solo rige mientras se den condiciones invernales — para que las máquinas quitanieves puedan trabajar.\n\nLOS TRES CASOS CORRECTOS cubren el ciclo completo: mientras nieva, mientras la nieve sigue en el suelo, y cuando aún no ha nevado pero la temperatura hace previsible el hielo. Este tercero es el que más se falla, porque no hay nieve visible.\n\n«CON LLUVIA INTENSA» es el distractor y es falso: la lluvia no es una condición invernal. El símbolo es un copo, no una gota.\n\nFUERA DE ESAS CONDICIONES, la prohibición no se aplica y puedes estacionar ahí.\n\nCLAVE: la tablilla acota la señal — por horario, por tipo de vehículo o, como aquí, por condiciones. Léela siempre: sin ella la respuesta sería otra.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Rombo amarillo = prioridad. Rectángulo = información. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":6287,"bg":"На какво разстояние след знака, когато е поставен извън населено място, се намира опасният завой?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55851.png","v":null,"a":[{"t":"от 100 до 150 м","ok":true,"i":null,"es":"entre 100 y 150 m"},{"t":"от 150 до 200 м","ok":false,"i":null,"es":"entre 150 y 200 m"},{"t":"от 200 до 500 м","ok":false,"i":null,"es":"entre 200 y 500 m"},{"t":"над 500 м","ok":false,"i":null,"es":"más de 500 m"}],"f":7,"es":"¿A qué distancia después de la señal, colocada fuera de población, está la curva peligrosa?"},{"id":5834,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че може да премине направо или да завие надясно?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24064.png","v":null,"a":[{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche azul"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche verde"}],"f":7,"es":"¿Para qué conductores esta posición del cuerpo y los brazos del agente significa que pueden seguir recto o girar a la derecha? (2 correctas)","explain":"El AMARILLO y el AZUL.\n\nEL AGENTE ESTÁ DE CARA A TI, el del coche rojo, con los dos brazos bajados.\n\nQUIÉN VE QUÉ. Pecho hacia el rojo, espalda hacia el verde, costados hacia el amarillo (izquierda) y el azul (derecha).\n\nBRAZOS BAJADOS ABREN LOS DOS COSTADOS. La ley: «Преминаването е разрешено» para quien está frente al hombro izquierdo o derecho — pero SOLO para seguir recto o girar a la derecha. Amarillo y azul cumplen las dos condiciones, y la pregunta pide exactamente eso: recto o derecha.\n\nROJO Y VERDE ESTÁN PARADOS. Pecho y espalda son muro: paso prohibido en cualquier dirección.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 2 ЗДвП): «ръка или ръце, протегнати хоризонтално встрани» — brazo o brazos extendidos horizontalmente a los lados; hecho el gesto, el agente puede bajar los brazos y la señal sigue valiendo. Significa «Преминаването е разрешено» para quien está frente a su hombro izquierdo o derecho Y va a seguir recto o girar a la derecha, y «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: los brazos bajados nunca autorizan girar a la izquierda ni dar media vuelta, ni siquiera a los que tienen paso. Solo recto o derecha."},{"id":5853,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/35066.png","v":null,"a":[{"t":"мога да премина направо","ok":true,"i":null,"es":"continuar recto"},{"t":"мога да завия надясно","ok":true,"i":null,"es":"puedo girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":7,"es":"La señal del agente regulador significa que puedo: (2 correctas)","explain":"Puedo seguir RECTO o girar a la DERECHA.\n\nLO QUE VES. Igual que la anterior pero con el agente girado al otro lado: le ves el otro costado, con los brazos bajados.\n\nDA IGUAL QUÉ COSTADO SEA. La ley trata el hombro izquierdo y el derecho exactamente igual mientras los brazos estén bajados: ambos abren, y ambos abren solo para recto o derecha.\n\nIZQUIERDA Y MEDIA VUELTA SIGUEN PROHIBIDAS. La restricción no depende del lado, depende del gesto.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 2 ЗДвП): «ръка или ръце, протегнати хоризонтално встрани» — brazo o brazos extendidos horizontalmente a los lados; hecho el gesto, el agente puede bajar los brazos y la señal sigue valiendo. Significa «Преминаването е разрешено» para quien está frente a su hombro izquierdo o derecho Y va a seguir recto o girar a la derecha, y «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: con los brazos bajados no tienes que averiguar si es el hombro izquierdo o el derecho. Solo tienes que ver que es un COSTADO y no el pecho ni la espalda. Esa distinción sí importará en cuanto el agente extienda el brazo."},{"id":5867,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е забранено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36578.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":7,"es":"¿Para qué conductores esta posición del cuerpo y los brazos del agente es una señal cuyo significado es 'El paso está prohibido'? (3 correctas)","explain":"El ROJO, el VERDE y el AMARILLO. Tres de los cuatro.\n\nLA POSTURA. El agente está DE CARA a ti (el coche rojo), con el brazo derecho extendido horizontalmente hacia delante.\n\nCON ESTE GESTO SOLO PASA UNO: el que está frente a su hombro izquierdo. Como está de cara a ti, su izquierda es tu derecha: el AZUL. Todos los demás quedan prohibidos, y por eso la respuesta son tres.\n\nEL ROJO le ve el pecho. EL VERDE le ve la espalda. EL AMARILLO le ve el hombro derecho — y es hacia donde apunta la porra, que es justo lo que hace caer a mucha gente.\n\nEL GESTO, EN LA LEY (чл. 10, ал. 2, т. 3 ЗДвП): «дясна ръка, протегната хоризонтално напред» — brazo derecho extendido horizontalmente hacia delante. «Преминаването е разрешено» solo para quien está frente al hombro IZQUIERDO del agente (y para los peatones que cruzan por detrás de su espalda); «Преминаването е забранено» para todos los demás.\n\nMÉTODO: 1) ¿brazo vertical? alto total. 2) ¿qué te muestra a TI: pecho, espalda o costado? pecho y espalda son muro siempre. 3) ¿costado sin brazo extendido? pasas, recto o derecha. 4) ¿costado CON brazo extendido? solo el izquierdo pasa. Está desarrollado con casos en Leyes → «El agente regulador: los 3 gestos y el método».\n\nCLAVE: es la pregunta espejo de la 5857 sobre la misma postura. Con brazo extendido, tres de cuatro siempre están parados. Si dudas, busca primero el ÚNICO que pasa y marca el resto."},{"id":5891,"bg":"Значението на този немигащ сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39865.png","v":null,"a":[{"t":"„Преминаването е забранено”","ok":true,"i":null,"es":"'El paso está prohibido'"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"}],"f":7,"es":"El significado de esta señal fija del semáforo es:"},{"id":5918,"bg":"Значението на жълтата мигаща светлина на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43915.png","v":null,"a":[{"t":"„Внимание”","ok":true,"i":null,"es":"'¡Atención!'"},{"t":"„Преминаването е забранено”","ok":false,"i":null,"es":"'El paso está prohibido'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"},{"t":"„Преминаването без спиране е забранено”","ok":false,"i":null,"es":"'Paso sin detenerse prohibido'"}],"f":7,"es":"El significado de la luz amarilla parpadeante del semáforo es:"},{"id":5933,"bg":"Този светлинен сигнал:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44686.png","v":null,"a":[{"t":"сигнализира, че навлизането по пътната лента, над която е поставен, е забранено","ok":true,"i":null,"es":"indica que la entrada al carril sobre el que está es PROHIBIDA"},{"t":"указва, че е забранено движението в най-лявата пътна лента","ok":false,"i":null,"es":"indica que está prohibido el carril izquierdo"},{"t":"указва място за задължително спиране","ok":false,"i":null,"es":"indica lugar de parada obligatoria"},{"t":"забранява движението по пътното платно над което е поставен","ok":false,"i":null,"es":"prohíbe la circulación en toda la calzada"}],"f":7,"es":"Esta señal luminosa:"},{"id":6073,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60166.png","v":null,"a":[{"t":"следва участък от пътя с двупосочно движение","ok":true,"i":null,"es":"sigue un tramo de doble sentido"},{"t":"лявата част на пътното платно е за автомобилите от насрещното движение","ok":true,"i":null,"es":"la parte izquierda es para el tráfico contrario"},{"t":"движещите се насреща автомобили са с предимство","ok":false,"i":null,"es":"los vehículos de frente tienen prioridad"},{"t":"навлизаме в участък от пътя, в който е забранено разминаването","ok":false,"i":null,"es":"entramos en tramo donde está prohibido el cruce"}],"f":7,"es":"En esta situación: (2 correctas)"},{"id":6075,"bg":"На двулентов път с двупосочно движение водачът трябва да се движи:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"възможно най-вдясно по платното за движение, когато лентите не са очертани с пътна маркировка","ok":true,"i":null,"es":"todo lo posible a la derecha cuando los carriles no están marcados"},{"t":"в дясната лента, когато лентите са очертани с пътна маркировка","ok":true,"i":null,"es":"en el carril derecho cuando hay marcas"},{"t":"в по-удобната за него пътна лента","ok":false,"i":null,"es":"en el carril más cómodo"},{"t":"в лявата пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"siempre en el carril izquierdo cuando esté libre"}],"f":7,"es":"En vía de dos carriles de doble sentido el conductor debe circular: (2 correctas)","explain":"Regla de posición básica: sin carriles marcados, circula lo más a la derecha posible; con marcas, por el carril derecho. El 'carril más cómodo' no existe legalmente y el izquierdo se reserva para adelantar."},{"id":6085,"bg":"При тази ситуация, на път извън населено място, на водачите е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/140619.png","v":null,"a":[{"t":"да се движат в най-дясната свободна лента","ok":true,"i":null,"es":"circular en el carril disponible más a la derecha"},{"t":"да се движат в средната пътна лента, когато дясната е заета","ok":true,"i":null,"es":"circular en el carril central cuando el derecho está ocupado"},{"t":"да се движат в най удобната за тях пътна лента","ok":false,"i":null,"es":"circular en el carril más cómodo"},{"t":"да се движат в средната пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"circular en el central siempre que esté libre"}],"f":7,"es":"En esta situación fuera de población, está PERMITIDO: (2 correctas)"},{"id":6095,"bg":"При тази ситуация задължени ли сте да преминете в крайната дясна лента, ако не успеете да изпреварите двата автомобила?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63478.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"En esta situación ¿está obligado a pasar al carril derecho si no puede adelantar?"},{"id":6100,"bg":"Разположението на автомобила върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64020.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":7,"explain":"Cuando una pregunta menciona la \"posición del vehículo en la calzada\" junto a una imagen, te están mostrando una situación de circulación y debes evaluar si el coche está en el carril correcto según las normas: circulando lo más a la derecha posible (salvo para adelantar, girar a la izquierda o evitar obstáculos), respetando la marca vial y sin invadir el carril contrario sin necesidad. Antes de responder, fíjate en tres cosas: ¿hay línea continua que esté cruzando?, ¿está en el carril que corresponde a su dirección (recto/izquierda/derecha)?, ¿invade el arcén o el carril contrario sin motivo? Si todo eso se cumple, la posición es correcta.","es":"La posición del vehículo en la calzada es:"},{"id":11821,"bg":"При тази ситуация, в крайната лява пътна лента е забранено движението на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65242.png","v":null,"a":[{"t":"леки автомобили с ремаркета над 750 kg","ok":true,"i":null,"es":"turismos con remolque de más de 750 kg"},{"t":"мотоциклети","ok":true,"i":null,"es":"motocicletas"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"всички товарни автомобили","ok":false,"i":null,"es":"todos los camiones"}],"f":7,"es":"En esta situación, en el carril izquierdo está PROHIBIDO circular a: (3 correctas)"},{"id":11870,"bg":"При тази ситуация на кои от посочените ППС е разрешено да се движат в средната пътна лента:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64852.png","v":null,"a":[{"t":"автобуси","ok":true,"i":null,"es":"autobuses"},{"t":"леки автомобили","ok":true,"i":null,"es":"turismos"},{"t":"товарни автомобили с допустима максимална маса над 3,5 t","ok":false,"i":null,"es":"camiones con MMA superior a 3.5 t"},{"t":"товарни автомобили с допустима максимална маса до 3,5 t","ok":false,"i":null,"es":"camiones con MMA hasta 3.5 t"}],"f":7,"es":"En esta situación ¿a qué vehículos está permitido circular por el carril central? (2 correctas)"},{"id":5795,"bg":"Разрешено ли е след този пътен знак движение със скорост по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53771.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido circular a velocidad superior a la indicada después de esta señal?"},{"id":5796,"bg":"Разрешено ли е след този пътен знак движение със скорост по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53889.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато има необходимите условия за безопасност","ok":false,"i":null,"es":"sí, pero solo con condiciones de seguridad"},{"t":"да, но само когато пътят е сух","ok":false,"i":null,"es":"sí, pero solo con carretera seca"}],"f":7,"es":"¿Está permitido circular a velocidad superior a la indicada después de esta señal?"},{"id":5832,"bg":"След този пътен знак движението със скорост, по-висока от означената е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57621.png","v":null,"a":[{"t":"забранено за всички ППС","ok":true,"i":null,"es":"prohibido para todos los vehículos"},{"t":"разрешено за транзитно преминаващите ППС","ok":false,"i":null,"es":"permitido para los que hacen tránsito"},{"t":"разрешено за МПС от категория “В”","ok":false,"i":null,"es":"permitido para categoría B"},{"t":"забранено само за водачите на двуколесни ППС","ok":false,"i":null,"es":"prohibido solo para vehículos de dos ruedas"}],"f":7,"es":"Después de esta señal, circular a velocidad superior a la indicada está:"},{"id":5833,"bg":"При тази ситуация забраната за движение със скорост, по-висока от означената се отнася:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57654.png","v":null,"a":[{"t":"за всички улици в зоната","ok":true,"i":null,"es":"todas las calles de la zona"},{"t":"само за улицата, в чието начало е поставен","ok":false,"i":null,"es":"solo la calle donde está la señal"},{"t":"за водачите на всички ППС","ok":true,"i":null,"es":"todos los conductores"},{"t":"само за водачите на леки автомобили","ok":false,"i":null,"es":"solo los conductores de turismos"}],"f":7,"es":"En esta situación la prohibición de circular a velocidad superior a la indicada se refiere a: (2 correctas)"},{"id":12029,"bg":"При тази ситуация трябва да управлявам с готовност за спиране заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":15,"a":[{"t":"трактора","ok":true,"i":null,"es":"el tractor"},{"t":"ограничението на скоростта","ok":false,"i":null,"es":"la señal de velocidad"},{"t":"мотоциклета","ok":false,"i":null,"es":"la moto"}],"f":7,"es":"En esta situación debo circular listo para frenar por:"},{"id":6230,"bg":"При тази ситуация с предимство е водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71987.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":7,"es":"En esta situación tiene prioridad:"},{"id":6243,"bg":"Разрешено ли е да започнете завиването надясно от най-лявата пътна лента на платното за движение?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, но само когато радиусът на завиване на автомобила е по-голям от радиуса на завоя","ok":true,"i":null,"es":"sí, pero solo cuando el radio de giro del vehículo es mayor que el del cruce"},{"t":"да, винаги когато пътните ленти не са обозначени с пътна маркировка","ok":false,"i":null,"es":"sí, siempre cuando no hay marcas"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"explain":"Sí, pero solo cuando el radio de giro del vehículo es mayor que el del cruce: vehículos largos (camiones, autobuses) que físicamente no pueden girar desde la derecha. Para un turismo normal, girar a la derecha desde el carril izquierdo es infracción.","es":"¿Está permitido iniciar un giro a la derecha desde el carril más a la izquierda?"},{"id":6279,"bg":"При тази ситуация съм задължен да пропусна синия автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/72020.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación estoy obligado a dejar pasar al coche azul. Esto es:"},{"id":6283,"bg":"При тази ситуация съм с предимство за преминаване преди червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70415.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación tengo prioridad sobre el coche rojo. Esto es:"},{"id":6340,"bg":"При тази ситуация с предимство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70846.png","v":null,"a":[{"t":"трамвая","ok":true,"i":null,"es":"el tranvía"},{"t":"лекия автомобил","ok":false,"i":null,"es":"el turismo"}],"f":7,"es":"En esta situación tiene prioridad:"},{"id":6350,"bg":"На кръстовище на равнозначни пътища водачът на нерелсово ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да пропусне релсовите ППС, когато те завиват надясно","ok":true,"i":null,"es":"debe ceder al tranvía cuando gira a la derecha"},{"t":"не е длъжен да пропусне релсовите ППС, когато те завиват наляво","ok":false,"i":null,"es":"no está obligado a ceder al tranvía cuando gira a la izquierda"},{"t":"трябва да пропусне релсовите ППС, когато те продължават направо","ok":true,"i":null,"es":"debe ceder al tranvía cuando continúa recto"}],"f":7,"es":"En intersección de vías equivalentes, el conductor no ferroviario: (2 correctas)","explain":"En cruce de vías equivalentes el tranvía tiene prioridad sobre los vehículos no ferroviarios: debes cederle al girar a la derecha Y al seguir recto (y también al girar a la izquierda, por eso esa opción negativa es falsa)."},{"id":6360,"bg":"Завиването в обратна посока може да започне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от най-лявата пътна лента по посока на движението","ok":true,"i":null,"es":"desde el carril más a la izquierda en el sentido de marcha"},{"t":"от дясната част на платното за движение, когато е с недостатъчна широчина","ok":true,"i":null,"es":"desde la derecha cuando la anchura es insuficiente"},{"t":"от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo para el conductor"}],"f":7,"es":"El cambio de sentido puede iniciarse: (2 correctas)","explain":"El cambio de sentido se inicia desde el carril más a la IZQUIERDA en tu sentido; excepcionalmente desde la derecha cuando la anchura de la calzada es insuficiente para girar desde la izquierda. La comodidad no es criterio."},{"id":6361,"bg":"Завиването в обратна посока от крайната дясна лента е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено при недостатъчна широчина на платното за движение","ok":true,"i":null,"es":"permitido cuando la anchura de la vía es insuficiente"},{"t":"разрешено във всички случаи","ok":false,"i":null,"es":"permitido siempre"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":7,"es":"El cambio de sentido desde el carril derecho está:","explain":"Desde el carril derecho solo está permitido cuando la anchura de la vía es insuficiente para completar el giro desde la izquierda. No es 'siempre' ni está prohibido de forma absoluta."},{"id":6365,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/142934.png","v":null,"a":[{"t":"водачът на товарния автомобил","ok":true,"i":null,"es":"el conductor del camión"},{"t":"водачът на лекия автомобил","ok":false,"i":null,"es":"el conductor del turismo"}],"f":7,"es":"En esta situación tiene prioridad:"},{"id":6369,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на жп прелез","ok":true,"i":null,"es":"en paso a nivel"},{"t":"когато видимостта е намалена под 50 м","ok":true,"i":null,"es":"con visibilidad inferior a 50 m"},{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"на участък от пътя с наклон","ok":false,"i":null,"es":"en tramo de la vía con pendiente"}],"f":7,"es":"El cambio de sentido está PROHIBIDO: (3 correctas)","explain":"Prohibido cambiar de sentido en paso a nivel, en túnel y cuando la visibilidad es inferior a 50 m. Una simple pendiente no lo prohíbe por sí misma (solo si reduce la visibilidad bajo ese umbral)."},{"id":6371,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на жп прелез","ok":true,"i":null,"es":"en paso a nivel"},{"t":"на надлез","ok":true,"i":null,"es":"en paso elevado"},{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"на път с интензивно движение","ok":false,"i":null,"es":"en vía de intenso tráfico"}],"f":7,"es":"El cambio de sentido está PROHIBIDO: (3 correctas)","explain":"Prohibido cambiar de sentido en paso a nivel, en paso elevado y sobre paso de peatones. El 'tráfico intenso' exige esperar el momento, pero no prohíbe la maniobra."},{"id":6403,"bg":"След този пътен знак на водачите на товарни автомобили с допустима максимална маса до 3,5 т е разрешено да изпреварват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"},{"t":"каруци","ok":true,"i":null,"es":"carruajes"},{"t":"леки автомобили","ok":false,"i":null,"es":"turismos"},{"t":"товарни автомобили","ok":false,"i":null,"es":"camiones"}],"f":7,"es":"Después de esta señal, los conductores de camiones con MMA ≤3.5t PUEDEN adelantar a: (2 correctas)"},{"id":6412,"bg":"Разрешено ли е да предприемете изпреварване на колоната от МПС при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71738.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido adelantar toda la columna de vehículos en esta situación?"},{"id":6427,"bg":"Водачът на изпреварваното ППС е длъжен :","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да не увеличава скоростта","ok":true,"i":null,"es":"no aumentar la velocidad"},{"t":"да не пречи на изпреварването","ok":true,"i":null,"es":"no obstaculizar el adelantamiento"},{"t":"да намали скоростта","ok":false,"i":null,"es":"reducir la velocidad"},{"t":"да премине плътно вдясно","ok":false,"i":null,"es":"desplazarse totalmente a la derecha"}],"f":7,"es":"El conductor del vehículo adelantado está obligado a: (2 correctas)","explain":"El conductor adelantado tiene dos obligaciones: NO aumentar la velocidad y NO obstaculizar la maniobra. No está obligado a frenar ni a apartarse del todo a la derecha."},{"id":6428,"bg":"При изпреварване задължението за осигуряване на достатъчно странично разстояние е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на водача на изпреварващото ППС","ok":true,"i":null,"es":"del conductor del vehículo ADELANTANTE"},{"t":"на водача на изпреварваното ППС","ok":false,"i":null,"es":"del conductor del vehículo ADELANTADO"},{"t":"на двамата водачи","ok":false,"i":null,"es":"de ambos conductores"}],"f":7,"es":"La obligación de garantizar distancia lateral suficiente al adelantar es:","explain":"La distancia lateral de seguridad es responsabilidad del que ADELANTA: quien ejecuta la maniobra responde de todos sus riesgos. El adelantado solo debe no acelerar ni obstaculizar."},{"id":6437,"bg":"Разрешено ли е да предприемете изпреварване при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124482.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Está permitido adelantar en esta situación?"},{"id":6439,"bg":"Разрешено ли е да продължите изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124449.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Está permitido continuar el adelantamiento en esta situación?"},{"id":6443,"bg":"Разрешено ли е да предприемете изпреварване при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124548.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido adelantar en esta situación?"},{"id":6702,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70614.png","v":null,"a":[{"t":"да премина преди автомобила и пешеходеца","ok":false,"i":null,"es":"pasar antes que el coche y el peatón"},{"t":"да пропусна автомобила","ok":true,"i":null,"es":"ceder el paso al coche"},{"t":"да пропусна пешеходеца","ok":true,"i":null,"es":"ceder el paso al peatón"}],"f":7,"es":"En esta situación debo: (2 correctas)"},{"id":5938,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48397.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"с правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación de los vehículos"}],"f":7,"es":"El orden de paso de estos vehículos en la intersección lo determinan:"},{"id":6349,"bg":"На водача е забранено да навлиза на железопътния прелез, когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от другата страна на прелеза няма достатъчно място за продължаване на движението","ok":true,"i":null,"es":"al otro lado no hay espacio suficiente para continuar"},{"t":"на прелеза трябва да се размине с друго ППС","ok":false,"i":null,"es":"en el paso debe cruzarse con otro vehículo"},{"t":"на прелеза няма съоръжения за подаване на звуков и светлинен сигнал","ok":false,"i":null,"es":"el paso no tiene señalización"}],"f":7,"es":"Al conductor le está PROHIBIDO entrar al paso a nivel cuando:","explain":"Prohibido entrar si al otro lado no hay espacio para salir: quedarías atrapado sobre las vías. Cruzarse con otro vehículo o la falta de señalización no prohíben la entrada (esta última solo obliga a parar y comprobar)."},{"id":6353,"bg":"Как ще сигнализирате през деня, за да спрете влака, ако автомобилът, който управлявате, поради повреда остане върху релсите?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с кръгово движение на ръката, в която се държи лесно забелязващ се предмет","ok":true,"i":null,"es":"con movimiento CIRCULAR del brazo sosteniendo un objeto llamativo"},{"t":"с насочена встрани ръка","ok":false,"i":null,"es":"con el brazo extendido lateralmente"},{"t":"с вдигната ръка, в която може да се държи привличащ вниманието предмет","ok":false,"i":null,"es":"con el brazo levantado sosteniendo algo llamativo"},{"t":"със стоп-палка","ok":false,"i":null,"es":"con una pala reflectante"}],"f":7,"es":"¿Cómo señalizas de día para detener el tren si tu vehículo está averiado en el paso?","explain":"La señal ferroviaria de 'alto' de día es el movimiento CIRCULAR del brazo sosteniendo un objeto bien visible. Un brazo extendido o levantado no significa parada para el maquinista y no detendrá el tren."},{"id":6364,"bg":"В случай на принудително спиране на превозното средство върху релсите на жп прелез, водачът е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да изведе пътниците извън превозното средство на безопасно разстояние","ok":true,"i":null,"es":"evacuar a los pasajeros a distancia segura"},{"t":"да вземе мерки за извеждането на превозното средство извън обсега на релсовия път","ok":true,"i":null,"es":"tomar medidas para sacar el vehículo de las vías"},{"t":"да вземе мерки за своевременното предупреждаване на машинистите от двете посоки на релсовия път","ok":true,"i":null,"es":"alertar a los maquinistas de ambos sentidos"},{"t":"да остане в автомобила и да уведоми органите за контрол","ok":false,"i":null,"es":"quedarse en el vehículo y avisar a las autoridades"}],"f":7,"es":"Si el vehículo para forzosamente sobre las vías del paso a nivel, el conductor está obligado a: (3 correctas)","explain":"Vehículo atascado sobre las vías: 1) evacúa a los pasajeros a distancia segura, 2) intenta sacar el vehículo, 3) avisa a los trenes de AMBOS sentidos. Quedarse dentro esperando a las autoridades es la opción mortal."},{"id":6499,"bg":"При принудително спиране в тунел водачът е задължен да изключи двигателя, когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"началото на тунела е обозначено с пътен знак","ok":true,"i":null,"es":"el inicio del túnel está señalizado con señal de tráfico"},{"t":"спирането не е кратковременно","ok":true,"i":null,"es":"la parada no es breve"},{"t":"тунелът е осветен","ok":false,"i":null,"es":"el túnel está iluminado"},{"t":"движението в тунела е еднопосочно","ok":false,"i":null,"es":"el tráfico es de un solo sentido"}],"f":7,"es":"Al parar forzosamente en túnel el conductor está obligado a apagar el motor cuando: (2 correctas)","explain":"En parada forzosa en túnel debes apagar el motor cuando el túnel está señalizado con señal de tráfico y cuando la parada no es breve (acumulación de gases). La iluminación o el sentido único no cambian la obligación."},{"id":6502,"bg":"Задължен ли е водачът да изключи двигателя при принудително спиране в тунел, когато началото на тунела е обозначено с пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, когато това спиране не е кратковременно","ok":true,"i":null,"es":"sí, cuando la parada no es breve"},{"t":"да, независимо от продължителността на спирането","ok":false,"i":null,"es":"sí, independientemente de la duración"}],"f":7,"explain":"La clave es la duración: debes apagar el motor cuando la parada NO es breve (los gases se acumulan en el espacio cerrado). Si la detención es momentánea, no existe la obligación: por eso 'independientemente de la duración' es falsa.","es":"¿Está obligado a apagar el motor al parar forzosamente en túnel señalizado?"},{"id":6519,"bg":"При тази ситуация съм с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63188.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación tengo prioridad. Esto es:"},{"id":6532,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57775.png","v":null,"a":[{"t":"мотоциклетиста","ok":true,"i":null,"es":"el motorista"},{"t":"товарния автомобил","ok":true,"i":null,"es":"el camión"},{"t":"лекия автомобил","ok":false,"i":null,"es":"el turismo"}],"f":7,"es":"En esta situación debo ceder el paso a: (2 correctas)"},{"id":6533,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61451.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"dejar pasar al tranvía"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el turismo"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"dejar pasar al turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"f":7,"es":"En esta situación debo: (2 correctas)"},{"id":6535,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61874.png","v":null,"a":[{"t":"само трамвая","ok":true,"i":null,"es":"solo al tranvía"},{"t":"само лекия автомобил","ok":false,"i":null,"es":"solo al turismo"},{"t":"и двете превозни средства","ok":false,"i":null,"es":"a los dos"}],"f":7,"es":"En esta situación debo ceder el paso:"},{"id":6537,"bg":"При тази ситуация водачът на зеления автомобил трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68558.png","v":null,"a":[{"t":"да пропусне синия автомобил","ok":true,"i":null,"es":"dejar pasar al coche azul"},{"t":"да премине преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el rojo"},{"t":"да пропусне червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"},{"t":"да премине преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"}],"f":7,"es":"En esta situación el conductor del coche verde debe: (2 correctas)"},{"id":6538,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58268.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"}],"f":7,"explain":"Mismo patrón que la anterior: pasas antes que un coche, cedes al otro. Antes de responder mentalmente, dibuja en tu cabeza (o en la imagen real) las trayectorias de los 3 vehículos. El vehículo cuya trayectoria cruza la tuya ANTES en el tiempo (porque está más cerca, viene por tu derecha, o va recto mientras tú giras) es al que debes ceder. El que cruzará después, o cuya vía está subordinada a la tuya, es al que tú le tienes prioridad. Practica dibujando flechas mentales de cada coche en cada pregunta de este tipo — es la técnica más rápida para no perder tiempo en el examen real.","es":"En esta situación debo: (2 correctas)"},{"id":6542,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65568.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al azul"},{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"f":7,"es":"En esta situación debo: (2 correctas)"},{"id":6556,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66950.png","v":null,"a":[{"t":"пропускам червения автомобил","ok":true,"i":null,"es":"cedo el paso al coche rojo"},{"t":"преминавам преди червения автомобил","ok":false,"i":null,"es":"paso antes que el coche rojo"}],"f":7,"es":"En esta situación:"},{"id":6564,"bg":"При тази ситуация задължени ли сте да пропуснете синия автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67198.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Está obligado a ceder el paso al coche azul?"},{"id":6565,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68353.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al azul"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"f":7,"es":"En esta situación debo: (2 correctas)"},{"id":6566,"bg":"При тази ситуация съм с предимство защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67328.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación tengo prioridad porque voy recto. Esto es:"},{"id":6568,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67378.png","v":null,"a":[{"t":"синият автомобил, защото се намира отдясно","ok":true,"i":null,"es":"el azul porque está a la derecha"},{"t":"червеният автомобил, защото се движи направо","ok":false,"i":null,"es":"el rojo porque va recto"},{"t":"синият автомобил, защото завива надясно","ok":false,"i":null,"es":"el azul porque gira a la derecha"}],"f":7,"es":"En esta situación tiene prioridad:"},{"id":6591,"bg":"При тази ситуация трябва ли да спрете, преди да преминете през кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56497.png","v":null,"a":[{"t":"да, при наличие на този пътен знак съм задължен да спра","ok":true,"i":null,"es":"sí, la señal presente obliga a parar"},{"t":"не, защото червеният автомобил завива надясно","ok":false,"i":null,"es":"no, porque el rojo gira a la derecha"}],"f":7,"es":"En esta situación ¿debe parar antes de cruzar la intersección?"},{"id":6593,"bg":"При тази ситуация автомобилът, който се движи направо, е с предимство пред автомобила, който завива надясно.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62980.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación, el vehículo que va recto tiene prioridad sobre el que gira a la DERECHA. Esto es:"},{"id":6599,"bg":"При тази ситуация съм с предимство, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56891.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación tengo prioridad porque voy recto. Esto es:"},{"id":6602,"bg":"При приближаване към кръстовище водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"своевременно да заеме пътна лента, която е предназначена за неговата посока на движение","ok":true,"i":null,"es":"ocupar a tiempo el carril correspondiente a su dirección"},{"t":"да управлява с готовност за спиране","ok":true,"i":null,"es":"circular listo para frenar"},{"t":"да подаде звуков или светлинен сигнал, когато е с предимство","ok":false,"i":null,"es":"dar señal acústica/luminosa cuando tiene prioridad"},{"t":"да има готовност да пропусне преминаващи през платното за движение пешеходци","ok":true,"i":null,"es":"estar listo para ceder a peatones que cruzan"}],"f":7,"es":"Al aproximarse a una intersección el conductor debe: (3 correctas)","explain":"Al aproximarte a un cruce: ocupa a tiempo el carril de tu dirección, circula preparado para frenar y listo para ceder a los peatones. Pitar o dar luces para 'reclamar' tu prioridad está prohibido."},{"id":6604,"bg":"Разрешено ли е да навлезете в кръстовище, ако преди да преминете ще се наложи да спрете в кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не, ако по този начин ще възпрепятствам преминаването през него","ok":true,"i":null,"es":"no, si obstaculizarías el paso"},{"t":"не, ако изходът на кръстовището е зает и ще остана с превозното средство в кръстовището","ok":true,"i":null,"es":"no, si la salida está ocupada y quedarías dentro"},{"t":"да, когато се намирам на пътя с предимство","ok":false,"i":null,"es":"sí, si estás en vía preferente"},{"t":"да, винаги","ok":false,"i":null,"es":"sí, siempre"}],"f":7,"explain":"No entres si obstaculizarías el paso ni si la salida del cruce está ocupada y quedarías dentro. Da igual que tu vía sea preferente o el semáforo esté verde: bloquear la intersección es infracción por sí misma.","es":"¿Está permitido entrar en la intersección si tendrías que parar dentro? (2 correctas son PROHIBICIONES) (2 correctas)"},{"id":6607,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48363.png","v":null,"a":[{"t":"с правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación de los vehículos"}],"f":7,"es":"El orden de paso de estos vehículos lo determinan:"},{"id":6673,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53658.png","v":null,"a":[{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":true,"i":null,"es":"paro para esperar señal de paso del agente"},{"t":"спирам, за да пропусна червения автомобил и преминавам след него","ok":false,"i":null,"es":"paro para dejar al rojo y paso después"},{"t":"преминавам преди червения автомобил, защото съм отдясно и се движа по път с предимство","ok":false,"i":null,"es":"paso antes que el rojo porque estoy a la derecha y en vía preferente"}],"f":7,"es":"En esta situación:"},{"id":5365,"bg":"При навлизане на автомагистрала водачът е длъжен да пропусне превозните средства, които се движат по нея:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"във всички случаи","ok":true,"i":null,"es":"en todos los casos"},{"t":"само когато е поставен пътен знак за осигуряване на предимство","ok":false,"i":null,"es":"solo cuando hay señal de tráfico que garantiza la prioridad"},{"t":"само, когато те се движат с висока скорост","ok":false,"i":null,"es":"solo cuando circulan a alta velocidad"}],"f":7,"es":"Al incorporarse a la autopista el conductor debe ceder el paso a los vehículos que circulan por ella:","explain":"En todos los casos: quien se incorpora a la autopista cede a los que ya circulan, con o sin señal. El carril de aceleración sirve para igualar la velocidad y entrar en un hueco, no otorga prioridad."},{"id":5377,"bg":"Кой от автомобилите нарушава правилата за движение по автомагистрала?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41540.png","v":null,"a":[{"t":"и двата автомобила","ok":true,"i":null,"es":"los dos automóviles"},{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"},{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"}],"f":7,"es":"¿Cuál de los automóviles infringe las normas de circulación en autopista?","explain":"AMBOS cometen infraccion. Tipica pregunta trampa - busca si los dos hacen algo incorrecto antes de elegir solo uno."},{"id":5423,"bg":"Теглене с гъвкава връзка по автомобилен път е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено само за изтегляне до най-близкото място за напускане на пътя","ok":true,"i":null,"es":"permitido solo para salir por la salida más cercana"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"забранено само в тъмната част от денонощието","ok":false,"i":null,"es":"prohibido solo de noche"}],"f":7,"es":"El remolque con cable flexible por carretera de automóviles está:","explain":"El cable flexible en vía rápida solo sirve para salir por la salida más próxima: el remolcado con cable no tiene control suficiente a esas velocidades. No está prohibido del todo ni permitido sin límite."},{"id":5426,"bg":"При тази ситуация, ако лекият автомобил се движи бавно, разрешено ли е да използвате за движение лентата за принудително спиране?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41756.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"En esta situación, si el turismo circula lento, ¿está permitido usar el carril de parada de emergencia para circular?","explain":"NO. El carril de emergencia solo se usa para emergencias reales, nunca para adelantar o circular mas rapido."},{"id":8263,"bg":"Автомагистралата е път:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"който не пресича пътища, железопътни и трамвайни линии и пешеходни пътеки на едно ниво","ok":true,"i":null,"es":"que no cruza a nivel otras vías, líneas ferroviarias o de tranvía ni pasos de peatones"},{"t":"на който началото е обозначено със съответния пътен знак","ok":true,"i":null,"es":"cuyo inicio está señalizado con la señal de tráfico correspondiente"},{"t":"на който краят е обозначен със съответния пътен знак","ok":true,"i":null,"es":"cuyo final está señalizado con la señal de tráfico correspondiente"},{"t":"по който движението се извършва без ограничение на скоростта","ok":false,"i":null,"es":"por la que se circula sin límite de velocidad"}],"f":7,"es":"La autopista es una carretera: (3 correctas)","explain":"La autopista se caracteriza por: no cruzar A NIVEL otras vías, ferrocarriles ni pasos de peatones (todo es a distinto nivel), y por tener inicio y final señalizados con su señal. 'Sin límite de velocidad' es falso: 140 km/h para turismos."},{"id":11443,"bg":"При движение по автомагистрала на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да завива в обратна посока","ok":true,"i":null,"es":"girar en sentido contrario"},{"t":"да се движи в платното за насрещно движение","ok":true,"i":null,"es":"circular en el carril contrario"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":7,"es":"Al circular por autopista al conductor le está prohibido: (2 correctas)","explain":"En autopista está prohibido girar en sentido contrario y circular por el carril contrario: son las maniobras suicidas contra el flujo. Remolcar con barra rígida está permitido: la trampa de siempre."},{"id":11620,"bg":"Лентата за принудително спиране на автомагистрала е разрешено да се използва:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при здравословни проблеми на водача или пътниците в превозното средство","ok":true,"i":null,"es":"en caso de problemas de salud del conductor o de los pasajeros del vehículo"},{"t":"при повреда на пътното превозно средство","ok":true,"i":null,"es":"en caso de avería del vehículo"},{"t":"за движение на бавнодвижещи се МПС","ok":false,"i":null,"es":"para la circulación de vehículos lentos"},{"t":"за паркиране","ok":false,"i":null,"es":"para estacionar"}],"f":7,"es":"El carril de parada de emergencia en autopista está permitido usarlo: (2 correctas)","explain":"El carril de emergencia se usa por avería o por problemas de salud de conductor o pasajeros. Ni para que circulen vehículos lentos ni para estacionar: no es un carril más ni un aparcamiento."},{"id":5545,"bg":"Този пътен знак указва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/38358.png","v":null,"a":[{"t":"начало на автобусна спирка","ok":true,"i":null,"es":"INICIO de parada de autobús"},{"t":"край на автобусна спирка","ok":false,"i":null,"es":"FIN de parada de autobús"},{"t":"пресичане на път, по който се движат автобуси","ok":false,"i":null,"es":"cruce de ruta de autobús"}],"f":7,"es":"Esta señal indica:"},{"id":5550,"bg":"С този знак се обозначава:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334687.png","v":null,"a":[{"t":"автобусна спирка","ok":true,"i":null,"es":"parada de autobús"},{"t":"пътна лента за движение само на автобуси","ok":false,"i":null,"es":"carril reservado a autobuses"},{"t":"пътна лента, забранена за движение на автобуси","ok":false,"i":null,"es":"carril prohibido para autobuses"},{"t":"пресичане на път, по който се движат автобуси","ok":false,"i":null,"es":"cruce de ruta de autobús"}],"f":7,"es":"Con esta señal se indica:","explain":""},{"id":5588,"bg":"При тази ситуация:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39220.png","v":null,"a":[{"t":"трябва да спра, ако преча на пешеходците да преминават през платното за движение","ok":true,"i":null,"es":"debo detenerme si impido a los peatones cruzar la calzada"},{"t":"мога да премина без да спирам, защото на платното за движение има очертан остров","ok":true,"i":null,"es":"puedo pasar sin detenerme, porque en la calzada hay una isleta marcada"},{"t":"задължен съм да спра на 1 м зад трамвая","ok":false,"i":null,"es":"estoy obligado a detenerme a 1 m detrás del tranvía"},{"t":"заобикалям трамвая отляво","ok":false,"i":null,"es":"rodear el tranvía por la izquierda"}],"f":7,"es":"En esta situación: (2 correctas)","explain":""},{"id":5601,"bg":"При тази ситуация преминавам, без да спирам покрай спрелия на спирката трамвай, защото той е със затворени врати.","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39534.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación paso sin detenerme junto al tranvía parado en la parada, porque tiene las puertas cerradas. Esto es:","explain":""},{"id":5619,"bg":"Правилата за движение в жилищна зона, обозначена с този пътен знак, са валидни:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39733.png","v":null,"a":[{"t":"до пътен знак „Край на жилищната зона”","ok":true,"i":null,"es":"hasta la señal \"Fin de la zona residencial\""},{"t":"до следващото кръстовище","ok":false,"i":null,"es":"hasta la próxima intersección"},{"t":"до края на населеното място","ok":false,"i":null,"es":"hasta el final del poblado"},{"t":"до пътен знак „Край на забраните въведени с пътни знаци”","ok":false,"i":null,"es":"hasta la señal \"Fin de las prohibiciones impuestas por señales\""}],"f":7,"es":"Las normas de circulación en una zona residencial, señalizada con esta señal, son válidas:","explain":""},{"id":5624,"bg":"В жилищна зона, обозначена със съответния пътен знак, движението на пешеходци върху платното за движение е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено","ok":true,"i":null,"es":"permitido"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"забранено, винаги когато пречат на движението на МПС","ok":false,"i":null,"es":"prohibido, siempre que obstaculicen la circulación de los vehículos"}],"f":7,"es":"En una zona residencial señalizada con la señal correspondiente, la circulación de peatones por la calzada es:","explain":"Permitido: en zona residencial señalizada los peatones pueden usar TODA la calzada (y los niños jugar en ella). Por eso el límite es 20 km/h: el espacio es compartido y el peatón tiene prioridad."},{"id":11621,"bg":"В района на спирка, обозначена с този знак, е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801926.png","v":null,"a":[{"t":"престоя на таксиметрови автомобили с цел очакване на пътници","ok":true,"i":null,"es":"la parada de taxis para esperar pasajeros"},{"t":"спирането за товарно-разтоварни работи","ok":true,"i":null,"es":"la detención para operaciones de carga y descarga"},{"t":"спирането за слизане на пътници","ok":false,"i":null,"es":"la detención para la bajada de pasajeros"}],"f":7,"es":"En la zona de una parada señalizada con esta señal está prohibido: (2 correctas)","explain":""},{"id":5711,"bg":"При теглене на повредено МПС дължината на гъвкавата връзка може да бъде:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"4 м","ok":true,"i":null,"es":"4 m"},{"t":"5 м","ok":true,"i":null,"es":"5 m"},{"t":"6 м","ok":true,"i":null,"es":"6 m"},{"t":"3 м","ok":false,"i":null,"es":"3 m"}],"f":7,"es":"Al remolcar un vehículo averiado, la longitud del enganche flexible puede ser: (3 correctas)","explain":"El enganche flexible mide entre 4 y 6 m: 4, 5 y 6 valen; 3 m es demasiado corto (el remolcado no tendría distancia para frenar sin embestir). El rango existe para que la conexión sea visible y manejable."},{"id":5776,"bg":"При теглене на повреден автомобил разрешено ли е теглещият автомобил да бъде с ремарке?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"Al remolcar un automóvil averiado, ¿está permitido que el automóvil que remolca lleve un remolque?","explain":"No: el vehículo que remolca a un averiado no puede llevar además un remolque. Tres elementos enganchados serían ingobernables en frenada y en curva."},{"id":5783,"bg":"Разрешено ли е теглене на повреден автомобил с гъвкава връзка, когато пътят е хлъзгав?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, без ограничение","ok":false,"i":null,"es":"sí, sin restricciones"},{"t":"да, ако теглещия автомобил е с антиблокираща система на спирачната уредба","ok":false,"i":null,"es":"sí, si el automóvil que remolca tiene sistema antibloqueo de frenos (ABS)"}],"f":7,"es":"¿Está permitido remolcar un automóvil averiado con enganche flexible cuando la vía está deslizante?","explain":"No: con la vía deslizante el remolcado con enganche FLEXIBLE está prohibido: el remolcado no puede mantener el cable tenso al frenar y embestiría al que remolca. El ABS del primero no resuelve la física del segundo."},{"id":5554,"bg":"Разрешено ли е след този знак да спрете върху платното за движение за слизане на пътник от автомобила?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42299.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido, después de esta señal, detenerse en la calzada para que baje un pasajero del automóvil?","explain":""},{"id":5590,"bg":"Кой автомобил е паркиран правилно?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43384.png","v":null,"a":[{"t":"само червеният автомобил","ok":false,"i":null,"es":"solo el rojo"},{"t":"само синият автомобил","ok":false,"i":null,"es":"solo el azul"},{"t":"и двата автомобила","ok":true,"i":null,"es":"ambos automóviles"}],"f":7,"es":"¿Qué automóvil está estacionado correctamente?","explain":""},{"id":5594,"bg":"Къде по пътищата извън населените места е разрешен престоят?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"извън платното за движение","ok":true,"i":null,"es":"fuera de la calzada"},{"t":"допуска се престой най-вдясно на пътното платно, когато пътният банкет е с недостатъчна широчина","ok":true,"i":null,"es":"se permite la parada lo más a la derecha de la plataforma vial cuando el arcén no es suficientemente ancho"},{"t":"само на специално определените за това места","ok":false,"i":null,"es":"solo en los lugares especialmente destinados a ello"}],"f":7,"es":"¿Dónde está permitida la parada en las vías fuera de poblado? (2 correctas)","explain":"Fuera de poblado se para FUERA de la calzada (arcén, apartadero); si el arcén no es bastante ancho, lo más a la derecha de la plataforma vial. No hace falta 'lugar especialmente destinado': eso es en vías rápidas."},{"id":5613,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"в подлез","ok":true,"i":null,"es":"en un paso subterráneo"},{"t":"на участък от пътя, който е в ремонт","ok":false,"i":null,"es":"en un tramo de la vía en obras"},{"t":"на надлез","ok":true,"i":null,"es":"en paso elevado"}],"f":7,"es":"La detención (parada) está prohibida: (3 correctas)","explain":"Parada prohibida en túnel, paso subterráneo y paso elevado: espacios estrechos donde un vehículo detenido bloquea y no se ve a tiempo. El tramo en obras no la prohíbe por sí mismo."},{"id":5618,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на платното за движение, където с пътен знак е забранено изпреварването","ok":true,"i":null,"es":"en calzada donde hay señal que prohíbe el adelantamiento"},{"t":"върху пътна лента, предназначена за движение на бавнодвижещи се ППС, обозначена с пътен знак","ok":true,"i":null,"es":"sobre carril destinado a vehículos lentos señalizado"},{"t":"на място, където ППС закрива от другите участници в движението пътен знак","ok":true,"i":null,"es":"en un lugar donde el vehículo oculta a los demás usuarios una señal de tráfico"},{"t":"на участък от пътя с интензивно движение","ok":false,"i":null,"es":"en tramo de intenso tráfico"}],"f":7,"es":"La detención (parada) está prohibida: (3 correctas)","explain":"Parada prohibida: donde una señal prohíbe adelantar (pararte obligaría a los demás a un adelantamiento prohibido), sobre el carril señalizado de vehículos lentos y donde tapas una señal a los demás. El 'tráfico intenso' no es causa legal de prohibición."},{"id":5632,"bg":"Забранено е паркирането пред пешеходни пътеки, на разстояние по-малко от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 м","ok":true,"i":null,"es":"5 m"},{"t":"10 м","ok":false,"i":null,"es":"10 m"},{"t":"15 м","ok":false,"i":null,"es":"15 m"},{"t":"20 м","ok":false,"i":null,"es":"20 m"}],"f":7,"es":"Está prohibido estacionar delante de los pasos de peatones a una distancia inferior a:","explain":"5 m: misma distancia que para la parada breve. Estacionar más cerca del paso convierte tu coche en una pantalla que oculta al peatón justo donde va a cruzar."},{"id":5646,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на спирките на превозните средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"en las paradas de los vehículos de las líneas regulares de transporte público"},{"t":"в близост до трамвайна линия, което може да затрудни движението на трамвая","ok":true,"i":null,"es":"cerca de una línea de tranvía, si puede dificultar la circulación del tranvía"},{"t":"на улици, по които се движат трамваи","ok":false,"i":null,"es":"en calles por las que circulan tranvías"},{"t":"върху трамвайна линия","ok":true,"i":null,"es":"sobre vía de tranvía"}],"f":7,"es":"El estacionamiento está prohibido: (3 correctas)","explain":"Prohibido estacionar en paradas de transporte público, sobre la vía del tranvía y cerca de ella si dificulta su paso. Pero en calles CON tranvía sí se puede estacionar mientras no estorbes la vía: por eso esa opción general es falsa."},{"id":5665,"bg":"През нощта на осветен участък от пътя движението се извършва:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"с включени къси светлини","ok":true,"i":null,"es":"con luces CORTAS encendidas"},{"t":"с включени дълги светлини","ok":false,"i":null,"es":"con las luces largas encendidas"},{"t":"с включени само габаритни светлини","ok":false,"i":null,"es":"con solo las luces de posición"},{"t":"без включени светлини","ok":false,"i":null,"es":"sin luces encendidas"}],"f":7,"es":"De noche en un tramo iluminado artificialmente, se circula:","explain":"Con luces CORTAS: de noche, aunque el tramo esté iluminado, las cortas te hacen visible sin deslumbrar. Las largas deslumbran, y solo posición o nada te vuelven invisible en cuanto falle la iluminación."},{"id":5692,"bg":"Кое от изброените действия е най-опасно при навлизане в заледен пътен участък?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"навлизането с висока скорост","ok":true,"i":null,"es":"entrar a alta velocidad"},{"t":"задържане натиснат педала на съединителя","ok":false,"i":null,"es":"mantener el pedal del embrague pisado"},{"t":"изключването на скоростния механизъм","ok":false,"i":null,"es":"desacoplar la marcha (dejar en punto muerto)"}],"f":7,"es":"¿Cuál de las acciones indicadas es la más peligrosa al entrar en un tramo de vía helado?","explain":"Lo más peligroso es ENTRAR RÁPIDO en el hielo: sin adherencia, cualquier corrección a alta velocidad es imposible. Pisar el embrague o el punto muerto son menos graves: pierdes freno motor, pero no el control de golpe."},{"id":6684,"bg":"При движение при намалена видимост МПС трябва да бъде:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"с включени къси или дълги светлини","ok":true,"i":null,"es":"con las luces de cruce o de carretera encendidas"},{"t":"с включени габаритни светлини","ok":true,"i":null,"es":"con las luces de posición encendidas"},{"t":"с включена светлина за осветяване на задната табела с регистрационния номер","ok":true,"i":null,"es":"con la luz de la placa de matrícula trasera encendida"},{"t":"с включен авариен сигнал","ok":false,"i":null,"es":"con la señal de avería activada (luces de emergencia)"}],"f":7,"es":"Al circular con visibilidad reducida, el vehículo debe ir: (3 correctas)","explain":"Con visibilidad reducida el vehículo circula con: luces de cruce o carretera, luces de posición y la luz de la placa trasera: todo el alumbrado de marcha. Las luces de emergencia NO son para circular: señalizan un vehículo averiado o peligro."},{"id":5715,"bg":"Неправилното положение на тялото на водача по време на управление води до по-бърза умора.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":7,"es":"La postura incorrecta del cuerpo del conductor durante la conducción provoca una fatiga más rápida.","explain":"Correcto: la mala postura fatiga antes: tensión muscular constante, apoyo incorrecto de la espalda y peor circulación. Es la misma regla que su gemela sobre el asiento mal regulado."},{"id":5724,"bg":"При движение на превозното средство разходът на гориво:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"се увеличава при превозване на предмети върху покрива на автомобила","ok":true,"i":null,"es":"aumenta al transportar objetos sobre el techo del automóvil"},{"t":"се увеличава при понижено налягане на въздуха в автомобилните гуми","ok":true,"i":null,"es":"aumenta con la presión de los neumáticos baja"},{"t":"намалява при често използване на спирачките","ok":false,"i":null,"es":"disminuye con el uso frecuente de los frenos"},{"t":"намялява при рязко увеличаване на скоростта","ok":false,"i":null,"es":"disminuye al aumentar bruscamente la velocidad"}],"f":7,"es":"Durante la marcha del vehículo, el consumo de combustible: (2 correctas)","explain":"El consumo aumenta con carga en el techo (aerodinámica) y con presión de neumáticos baja (resistencia a la rodadura). Frenar a menudo y acelerar bruscamente también lo AUMENTAN, no lo reducen: por eso esas opciones son falsas."},{"id":5727,"bg":"При зареждане на автомобила с гориво пушенето е:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено само извън автомобила","ok":false,"i":null,"es":"permitido solo fuera del automóvil"},{"t":"разрешено само в автомобила","ok":false,"i":null,"es":"permitido solo dentro del automóvil"}],"f":7,"es":"Al repostar combustible, fumar está:","explain":"Prohibido fumar al repostar, dentro o fuera del coche: los vapores de gasolina se inflaman con cualquier brasa. No hay versión 'segura' de fumar en la gasolinera."},{"id":5744,"bg":"Трябва ли да се управлява МПС при влошено здравословно състояние?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"не трябва да се управлява","ok":true,"i":null,"es":"no se debe conducir"},{"t":"да, но след това трябва да се отдели повече време за почивка","ok":false,"i":null,"es":"sí, pero después hay que dedicar más tiempo al descanso"},{"t":"да, но трябва да се вземе подходящо лекарство преди управлението","ok":false,"i":null,"es":"sí, pero hay que tomar un medicamento adecuado antes de conducir"}],"f":7,"es":"¿Se debe conducir un vehículo con el estado de salud deteriorado?","explain":"No se debe conducir con la salud deteriorada: los reflejos, la atención y el juicio están mermados. Ni el descanso posterior ni un medicamento lo compensan (muchos fármacos además reducen la capacidad de conducir)."},{"id":6133,"bg":"Възможни причини за отклоняване на вниманието на водача по време на управление са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"четенето на крайпътни надписи","ok":true,"i":null,"es":"leer los carteles junto a la vía"},{"t":"извършването на действия, които не са във връзка с управлението","ok":true,"i":null,"es":"realizar acciones que no tienen relación con la conducción"},{"t":"говоренето по мобилен телефон","ok":true,"i":null,"es":"hablar por el teléfono móvil"},{"t":"бързо преминаващите автомобили","ok":false,"i":null,"es":"los automóviles que pasan a gran velocidad"}],"f":7,"es":"Posibles causas de distracción del conductor durante la conducción son: (3 correctas)","explain":"Distraen: leer carteles, hacer cosas ajenas a la conducción y hablar por el móvil: todas apartan la vista o la mente de la vía. Los coches que pasan rápido son parte del tráfico que precisamente hay que vigilar."},{"id":6136,"bg":"В коя част от денонощието остротата на зрението на човека намалява значително?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"в светлата част","ok":false,"i":null,"es":"en la parte luminosa (día)"},{"t":"в тъмната част","ok":true,"i":null,"es":"en la parte oscura (noche)"},{"t":"остротата на зрението не се променя през денонощието","ok":false,"i":null,"es":"la agudeza visual no varía"}],"f":7,"es":"¿En qué parte del día la agudeza visual del ser humano disminuye significativamente?","explain":"De NOCHE (la parte oscura): la agudeza visual humana cae drásticamente sin luz: se pierde detalle, color y percepción de distancias. Por eso de noche se reduce la velocidad aunque la vía parezca despejada."},{"id":6145,"bg":"Предупреждаващите признаци за умора у водача са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"разсейването","ok":true,"i":null,"es":"la distracción"},{"t":"намаляването на обема на възприеманите обекти от пътната обстановка","ok":true,"i":null,"es":"la reducción de la cantidad de objetos percibidos de la situación vial"},{"t":"намаляването на точността на възприеманите обекти от пътната обстановка","ok":true,"i":null,"es":"la reducción de la precisión con que se perciben los objetos de la situación vial"},{"t":"точните реакции","ok":false,"i":null,"es":"las reacciones precisas"}],"f":7,"es":"Los signos de advertencia de fatiga en el conductor son: (3 correctas)","explain":"La fatiga avisa con: distracción, percepción de MENOS objetos de la situación vial y MENOS precisión al percibirlos. Las 'reacciones precisas' son lo contrario: señal de conductor descansado."},{"id":5506,"bg":"При спиране за проверка от контролен орган, ако няма други указания, водачът трябва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да спре плавно","ok":true,"i":null,"es":"detenerse suavemente"},{"t":"да спре в най-дясната част на платното за движение","ok":true,"i":null,"es":"detenerse en la parte más a la derecha de la calzada"},{"t":"да спре незабавно пред контролния орган","ok":false,"i":null,"es":"detenerse inmediatamente ante el agente de control"},{"t":"да спре в средата на заеманата лента","ok":false,"i":null,"es":"detenerse en el centro del carril que ocupa"}],"f":7,"es":"Al detenerse para un control de un agente, si no hay otras indicaciones, el conductor debe: (2 correctas)","explain":"Ante la señal de stop del agente: detente con suavidad y en la parte más a la derecha de la calzada. Ni frenazo justo ante el agente ni parado en medio del carril: la detención tampoco debe crear peligro."},{"id":11362,"bg":"Намаляване на прозрачността на стъклата на задните странични врати на леките автомобили е:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"забранено във всичси случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено без ограничение","ok":false,"i":null,"es":"permitido sin restricción"},{"t":"се допуска само при наличие на огледала за виждане назад от двете страни на автомобила","ok":true,"i":null,"es":"se permite solo si hay espejos retrovisores a ambos lados del automóvil"}],"f":7,"es":"Reducir la transparencia de los cristales de las puertas laterales traseras de los turismos está:","explain":"Los cristales traseros laterales pueden oscurecerse SOLO si el coche tiene retrovisores exteriores a ambos lados: la visión trasera queda garantizada por los espejos. Ni prohibición total ni barra libre."},{"id":11367,"bg":"Разрешено ли е водачът на МПС да oрганизира или участва в нерегламентирани състезания по пътищата, отворени за обществено ползване?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не, забранено е във всички случаи","ok":true,"i":null,"es":"no, está prohibido en todos los casos"},{"t":"не, освен по пътища извън населените места","ok":false,"i":null,"es":"no, salvo en vías fuera de poblado"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":7,"es":"¿Está permitido que el conductor organice o participe en carreras ilegales en vías abiertas al uso público?","explain":"Prohibido en todos los casos: organizar o participar en carreras ilegales en vías públicas es una de las infracciones más graves del código, dentro o fuera de poblado."},{"id":5455,"bg":"Извършва ли нарушение водач, който управлява МПС без табели с регистрационен номер?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"¿Comete infracción el conductor que conduce un vehículo sin placas de matrícula?","explain":"Sí: circular sin placas de matrícula es infracción: el vehículo debe estar identificado en todo momento. No hay supuesto que lo excuse."},{"id":5497,"bg":"Контролните органи преместват паркирано пътно превозно средство без знанието на неговия собственик, когато превозното средство:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"е паркирано правилно, но обстоятелствата налагат неговото преместване","ok":true,"i":null,"es":"está estacionado correctamente, pero las circunstancias exigen su traslado"},{"t":"е паркирано в нарушение на места, обозначени с неподвижен пътен знак, предупреждаващ за принудително преместване","ok":true,"i":null,"es":"está estacionado infringiendo en lugares señalizados con una señal fija que advierte de la retirada forzosa"},{"t":"създава опасност за другите участници в движението","ok":true,"i":null,"es":"crea peligro para los demás usuarios de la vía"},{"t":"винаги, когато е паркирано в нарушение на правилата за движение","ok":false,"i":null,"es":"siempre que esté estacionado infringiendo las normas de circulación"}],"f":7,"es":"Las autoridades de control retiran un vehículo estacionado sin conocimiento de su propietario cuando el vehículo: (3 correctas)","explain":"Retiran el vehículo: cuando aun bien estacionado las circunstancias exigen moverlo (obras, evento), cuando infringe en zona con señal fija que advierte de retirada, y cuando crea peligro. No 'siempre que infrinja': sin esas condiciones se sanciona pero no se retira."},{"id":11409,"bg":"При служебно прекратяване на регистрацията на ППС със съставянето на акта за установяване на административното нарушение се отнемат:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"табелите с регистрационен номер","ok":true,"i":null,"es":"las placas de matrícula"},{"t":"част 2 на свидетелството за регистрация на ППС","ok":true,"i":null,"es":"la parte 2 del permiso de circulación"},{"t":"част 1 на свидетелството за регистрация ППС","ok":false,"i":null,"es":"la parte 1 del permiso de circulación"}],"f":7,"es":"Al cancelar de oficio el registro de un vehículo, se retiran: (2 correctas)","explain":"Al cancelar de oficio el registro se retiran las placas de matrícula y la parte 2 del permiso de circulación (el documento pequeño que se lleva a bordo). La parte 1 queda con el propietario."},{"id":5340,"bg":"В кой от случаите при ПТП водачът е длъжен да вземе мерки за безопасността на движението?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"винаги, независимо дали е участник в произшествието или не","ok":true,"i":null,"es":"siempre, esté o no implicado en el accidente"},{"t":"само когато е участник в произшествието","ok":false,"i":null,"es":"solo cuando está implicado en el accidente"}],"f":7,"es":"¿En qué caso, en un accidente, el conductor está obligado a tomar medidas para la seguridad del tráfico?","explain":"Siempre: todo conductor que llega a un accidente debe tomar medidas de seguridad del tráfico (señalizar, proteger), esté o no implicado. Es un deber general de auxilio y prevención."},{"id":5349,"bg":"В кой от изброените случаи водачът е длъжен да се върне на мястото на ПТП, след като е превозил пострадал до болнично заведение?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"когато е участник в произшествието","ok":true,"i":null,"es":"cuando es parte implicada en el accidente"},{"t":"винаги, независимо от това дали е участник в произшествието","ok":false,"i":null,"es":"siempre, independientemente de si está implicado en el accidente"},{"t":"когато превозването е било разпоредено от органите за контрол","ok":false,"i":null,"es":"cuando el transporte haya sido ordenado por las autoridades de control"}],"f":7,"es":"¿En cuál de los casos indicados el conductor está obligado a volver al lugar del accidente después de trasladar a un herido a un hospital?","explain":"Debe volver al lugar cuando es PARTE IMPLICADA en el accidente: su presencia es necesaria para el atestado. Quien solo ayudó trasladando a un herido sin estar implicado no tiene esa obligación."},{"id":11431,"bg":"Водач, участник в ПТП, при което няма пострадали хора, длъжен ли е да уведоми контролните органи на МВР за произшествието?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да, ако между участниците в произшествието няма съгласие относно обстоятелствата, свързани с него","ok":true,"i":null,"es":"sí, si los implicados en el accidente no están de acuerdo sobre sus circunstancias"},{"t":"да, но само ако по превозното средство има значителни повреди","ok":false,"i":null,"es":"sí, pero solo si el vehículo tiene daños significativos"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"Un conductor implicado en un accidente sin heridos, ¿está obligado a avisar del accidente a las autoridades del MVR?","explain":"Debe avisarse al MVR cuando los implicados NO están de acuerdo sobre las circunstancias: sin acuerdo no cabe parte amistoso y hace falta atestado. Con acuerdo y solo daños materiales, basta el parte bilateral."},{"id":11650,"bg":"Кога водачът на МПС е задължен да окаже помощ на пострадали при пътнотранспортни произшествия, ако това не представлява опасност за него?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"когато е участник в произшествието","ok":true,"i":null,"es":"cuando es parte implicada en el accidente"},{"t":"когато не е участник в произшествието, но има хора, които се нуждаят от помощ","ok":true,"i":null,"es":"cuando no está implicado en el accidente, pero hay personas que necesitan ayuda"},{"t":"само, когато за това се разпореди контролен орган","ok":false,"i":null,"es":"solo cuando lo ordene un agente de control"}],"f":7,"es":"¿Cuándo está obligado el conductor a prestar ayuda a los heridos en accidentes de tráfico, si no supone un peligro para él? (2 correctas)","explain":"Debe prestar ayuda: cuando está implicado en el accidente y también cuando NO está implicado pero hay personas que la necesitan (deber general de auxilio, si no supone peligro para él). No hace falta orden de ningún agente."},{"id":6587,"bg":"След кой от тези знаци, при преминаване през кръстовището, превозното средство от другия път трябва да ви пропусне?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55265.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55266.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334693.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55247.png","es":""}],"f":7,"es":"¿Después de cuál de estas señales, al cruzar la intersección, el vehículo del otro camino debe cederte el paso? (2 correctas)","explain":"La senal de via con prioridad (rombo amarillo) te da preferencia de paso en la interseccion."},{"id":5260,"bg":"Кой от пътните знаци предупреждава за кръстовище с път без предимство?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23809.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23810.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23811.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334675.png","es":""}],"f":7,"es":"¿Cuál de las señales advierte de una intersección con vía sin prioridad? (3 correctas)","explain":"Las senales de advertencia de interseccion son triangulos rojos. Hay variantes segun si el camino secundario viene de la derecha, izquierda o en T."},{"id":6046,"bg":"Когато подава сигнал с ръка, при потегляне и включване в движението от дясната част на пътя, водачът на двуколесното ППС сигнализира чрез:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27812.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27813.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27814.png","es":""}],"f":7,"es":"Cuando da señal con el brazo al arrancar e incorporarse desde la parte derecha de la carretera, el conductor de un vehículo de dos ruedas señaliza con:","explain":"El conductor de bicicleta o moto senaliza girando el brazo derecho hacia arriba cuando se incorpora desde la derecha."},{"id":5253,"bg":"Кой от пътните знаци предупреждава за стеснение на платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"es":"","i":"334669"},{"t":"","ok":true,"es":"","i":"334668"},{"t":"","ok":false,"es":"","i":"21263"},{"t":"","ok":false,"es":"","i":"334749"}],"f":7,"es":"¿Cuál de las señales advierte de estrechamiento de la calzada? (2 correctas)","explain":"Hay 3 tipos: estrechamiento por izquierda, por derecha, o por ambos lados. Fijate en que lado desaparece la flecha."},{"id":5261,"bg":"Кой от пътните знаци предупреждава за кръстовище с път без предимство?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"334675"},{"t":"","ok":true,"es":"","i":"23811"},{"t":"","ok":true,"es":"","i":"23810"},{"t":"","ok":false,"es":"","i":"24605"}],"f":7,"es":"¿Cuál de las señales advierte de intersección con vía sin prioridad? (2 correctas)","explain":"El triangulo con lineas que se cruzan indica interseccion con via sin prioridad. La variante con T indica interseccion en T."},{"id":5381,"bg":"Този знак:","p":2,"s":"Раздел 4","i":"22272","v":null,"a":[{"t":"обозначава автомобил, който превозва организирана група деца","ok":true,"es":"identifica un automóvil que transporta un grupo organizado de niños"},{"t":"указва на децата място за преминаване през платното за движение","ok":false,"es":"indica a los niños un lugar para cruzar la calzada"},{"t":"предупреждава за деца на пътя","ok":false,"es":"advierte de niños en la vía"},{"t":"сигнализира място за спиране на училищен автобус","ok":false,"es":"señaliza un lugar de parada de autobús escolar"}],"f":7,"es":"Esta señal:","explain":"Identifica un automóvil que TRANSPORTA UN GRUPO ORGANIZADO DE NIÑOS.\n\nQUÉ ES. Un cuadrado NARANJA con borde blanco y dos niños con mochila caminando. No es una señal de tráfico: es un «опознавателен знак», un distintivo que se coloca en el vehículo, igual que la placa naranja de mercancías peligrosas o las bandas reflectantes de los remolques.\n\nDÓNDE VA. En el propio autobús o furgoneta, delante y detrás, mientras lleve el grupo de niños a bordo.\n\nQUÉ TE PIDE A TI. Extremar la precaución alrededor de ese vehículo, sobre todo cuando está parado: los niños bajan sin mirar y cruzan por delante o por detrás. Hay que contar con que aparezca uno.\n\n«ADVIERTE DE NIÑOS EN LA VÍA» es el distractor principal, y describe OTRA señal: el triángulo rojo con dos niños, que sí es señal de tráfico y se coloca junto a colegios y parques. Mismo dibujo, distinta función.\n\n«INDICA A LOS NIÑOS UN LUGAR PARA CRUZAR» y «SEÑALIZA UNA PARADA DE AUTOBÚS ESCOLAR» describen elementos de la vía, no del vehículo.\n\nCLAVE: fondo naranja = va pegado a un vehículo. Triángulo rojo = está clavado en el suelo. Esa distinción resuelve la pregunta sin saberse el dibujo.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información. Rombo amarillo = prioridad. Fondo naranja o amarillo = distintivo del vehículo o señalización temporal. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5222,"bg":"Кой от пътните знаци предупреждава за стръмен наклон при изкачване?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21389.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21390.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334664.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21392.png","es":""}],"f":7,"es":"¿Cuál de las señales advierte de pendiente pronunciada en subida?","explain":"La pendiente en subida se indica con un triangulo con flecha hacia arriba y el porcentaje. Diferente de la bajada (flecha hacia abajo)."},{"id":11816,"bg":"С кой от опознавателните знаци се обозначават товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23016.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23017.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334747.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334746.png","es":""}],"f":7,"es":"¿Con cuál de los signos distintivos se identifican los camiones con masa máxima admisible superior a 3500 kg y longitud superior a 7 metros? (2 correctas)","explain":"Los camiones largos y pesados llevan placas reflectantes traseras especificas para identificarlos en carretera."},{"id":5433,"bg":"Разликата между късите и дългите светлини на МПС е:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"в дължината на осветявания участък от пътя","ok":true,"i":null,"es":"en la longitud del tramo de vía iluminado"},{"t":"в разположението на източника на светлината","ok":false,"i":null,"es":"en la posición de la fuente de luz"},{"t":"в цвета на светлината","ok":false,"i":null,"es":"en el color de la luz"},{"t":"в големината на светлинния източник","ok":false,"i":null,"es":"en el tamaño de la fuente de luz"}],"f":6,"es":"La diferencia entre las luces cortas y largas del vehículo está:","explain":"Cortas y largas se diferencian en la LONGITUD del tramo iluminado (unos 40-50 m frente a 100+ m). No cambia el color ni la posición de la fuente: cambia el alcance y la geometría del haz."},{"id":11881,"bg":"Минималната дълбочина на протектора на гумите (които не са за зимни условия) на автомобилите през периода от 15 ноември до 1 март е:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"4,0 mm","ok":true,"i":null,"es":"4,0 mm"},{"t":"0,5 mm","ok":false,"i":null,"es":"0,5 mm"},{"t":"1,0 mm","ok":false,"i":null,"es":"1,0 mm"},{"t":"3,0 mm","ok":false,"i":null,"es":"3,0 mm"}],"f":6,"es":"La profundidad mínima de la banda de rodadura de los neumáticos (que no son de invierno) de los automóviles en el período del 15 de noviembre al 1 de marzo es:","explain":"4,0 mm: profundidad mínima del dibujo entre el 15 de noviembre y el 1 de marzo para neumáticos que no son de invierno. El resto del año el mínimo general es menor: la exigencia invernal es específica."},{"id":5440,"bg":"Количеството на течността в охладителната уредба е отчетено правилно, когато проверката на нивото на течността е извършена:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"при студен двигател","ok":true,"i":null,"es":"con el motor FRÍO"},{"t":"без съобразяване с температурата на двигателя","ok":false,"i":null,"es":"sin importar la temperatura"},{"t":"при подгрят двигател","ok":false,"i":null,"es":"con el motor caliente"}],"f":6,"es":"El nivel de líquido refrigerante se mide correctamente cuando:","explain":"Con el motor FRÍO: en caliente el líquido está expandido y presurizado (riesgo de quemadura al abrir y lectura falsa). Las marcas MIN/MAX del depósito de expansión están calibradas en frío."},{"id":5479,"bg":"Светването на този символ върху арматурното табло означава, че:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334685.png","v":null,"a":[{"t":"е задействана спирачката за паркиране","ok":true,"i":null,"es":"está accionado el freno de estacionamiento"},{"t":"са включени светлините за паркиране","ok":false,"i":null,"es":"están encendidas las luces de estacionamiento"},{"t":"налягането на маслото в двигателя е ниско","ok":false,"i":null,"es":"la presión del aceite del motor es baja"},{"t":"има повреда в спирачната система","ok":false,"i":null,"es":"hay una avería en el sistema de frenos"}],"f":6,"es":"El encendido de este símbolo en el cuadro de instrumentos significa que:","explain":""},{"id":11655,"bg":"Светването по време на движение на този символ върху арматурното табло на автомобила означава, че:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801958.png","v":null,"a":[{"t":"има неизправност в антиблокиращата система","ok":true,"i":null,"es":"hay un fallo en el sistema antibloqueo (ABS)"},{"t":"задействана е антиблокиращата система на спирачната уредба","ok":false,"i":null,"es":"se ha activado el sistema antibloqueo (ABS) de los frenos"},{"t":"спирачните накладки са износени","ok":false,"i":null,"es":"las pastillas de freno están desgastadas"},{"t":"системата е готова за използване","ok":false,"i":null,"es":"el sistema está listo para su uso"}],"f":6,"es":"El encendido durante la marcha de este símbolo en el cuadro de instrumentos del automóvil significa que:","explain":""},{"id":5450,"bg":"Пониженото ниво на коя от изброените течности може да причини пътнотранспортно произшествие?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"на течността в спирачната система","ok":true,"i":null,"es":"el líquido del sistema de FRENOS"},{"t":"на течността в охладителната система","ok":false,"i":null,"es":"el líquido del sistema de refrigeración"},{"t":"на маслото в трансмисията","ok":false,"i":null,"es":"el aceite de la transmisión"}],"f":6,"es":"¿El nivel bajo de qué líquido puede causar un accidente?","explain":"El nivel bajo del líquido de FRENOS puede causar directamente un accidente: sin presión hidráulica no hay frenada. El refrigerante o el aceite de transmisión bajos dañan el vehículo, pero no te dejan sin frenos de golpe."},{"id":5199,"bg":"Състав от пътни превозни средства са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"механично свързани ППС, които участват в движението като едно цяло","ok":true,"i":null,"es":"vehículos unidos mecánicamente que participan en el tráfico como un conjunto"},{"t":"МПС с полуремарке","ok":true,"i":null,"es":"vehículo de motor con semirremolque"},{"t":"МПС теглещо ремарке","ok":true,"i":null,"es":"vehículo de motor que remolca un remolque"},{"t":"автомобилите с допълнително монтирани съоръжения","ok":false,"i":null,"es":"los automóviles con equipos adicionales instalados"}],"f":6,"es":"Un tren de vehículos de carretera está formado por: (3 correctas)","explain":"Un tren de carretera son vehículos unidos MECÁNICAMENTE circulando como conjunto: motor + remolque o motor + semirremolque. Un automóvil con equipos adicionales instalados sigue siendo un solo vehículo, no un tren."},{"id":5223,"bg":"Кои от изброените правила се прилагат при движение в населено място?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"допуска се паркиране на платното за движение","ok":true,"i":null,"es":"se permite estacionar en la calzada"},{"t":"може да се паркира на обозначени места върху тротоарите","ok":true,"i":null,"es":"se puede estacionar en lugares señalizados sobre las aceras"},{"t":"забранено е паркирането на платното за движение","ok":false,"i":null,"es":"está prohibido estacionar en la calzada"},{"t":"няма ограничение за паркиране върху тротоарите","ok":false,"i":null,"es":"no hay restricción para estacionar sobre las aceras"}],"f":6,"es":"¿Cuáles de las normas se aplican al circular en población? (2 correctas)","explain":"En población se permite estacionar en la calzada y sobre las aceras en los lugares señalizados para ello. Las opciones que lo prohíben todo o lo permiten sin restricción alguna deforman la norma en ambos extremos."},{"id":5314,"bg":"Видимостта е ограничена при:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"стръмни наклони","ok":true,"i":null,"es":"pendientes pronunciadas"},{"t":"завои","ok":true,"i":null,"es":"curvas"},{"t":"здрач","ok":false,"i":null,"es":"el crepúsculo"},{"t":"мъгла","ok":false,"i":null,"es":"niebla"}],"f":6,"es":"La visibilidad esta limitada en: (2 correctas)","explain":"Visibilidad LIMITADA es la restringida por la geometría de la vía: curvas y cambios de rasante (pendientes). El crepúsculo y la niebla producen visibilidad REDUCIDA (condiciones atmosféricas/luz). El examen explota esta distinción constantemente."},{"id":5167,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/20360.png","v":null,"a":[{"t":"опасeн завой наляво","ok":true,"i":null,"es":"curva peligrosa a la izquierda"},{"t":"опасност ППС да излезе от пътя наляво","ok":false,"i":null,"es":"peligro de que el vehículo se salga de la vía por la izquierda"},{"t":"кръстовище, на което задължително трябва да се завие наляво","ok":false,"i":null,"es":"intersección donde es obligatorio girar a la izquierda"},{"t":"опасен наклон на пътя","ok":false,"i":null,"es":"pendiente peligrosa de la vía"}],"f":6,"es":"Esta señal advierte de:","explain":"Advierte de una CURVA PELIGROSA A LA IZQUIERDA — «опасен завой наляво».\n\nLA SEÑAL. Triángulo rojo con una flecha ancha que se dobla hacia la izquierda. Grupo А, señales de peligro: avisan, no ordenan.\n\nQUÉ TE PIDE. Reducir la velocidad antes de entrar, no durante. Frenar dentro de una curva desestabiliza el coche; la velocidad se ajusta en la recta previa, que es justo para lo que sirve el aviso.\n\n«PELIGRO DE SALIRSE DE LA VÍA POR LA IZQUIERDA» no existe como señal.\n\n«INTERSECCIÓN DONDE ES OBLIGATORIO GIRAR A LA IZQUIERDA» sería un círculo AZUL: obligación, no peligro. Es el distractor que confunde forma con contenido — la flecha se parece, la forma no.\n\n«PENDIENTE PELIGROSA» tiene su propio triángulo, con una rampa y el porcentaje.\n\nCLAVE: el trazo grueso y curvo dentro de un triángulo es siempre una curva. Si el mismo dibujo estuviera dentro de un círculo azul, sería una orden de girar. Forma primero, dibujo después.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5197,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334668.png","v":null,"a":[{"t":"стесняване на платното за движение отляво","ok":true,"i":null,"es":"estrechamiento de la calzada por la izquierda"},{"t":"промяна в наклона на пътя","ok":false,"i":null,"es":"cambio de la pendiente de la vía"},{"t":"вливане на пътна лента отляво","ok":false,"i":null,"es":"incorporación de un carril por la izquierda"},{"t":"опасен пътен банкет отляво","ok":false,"i":null,"es":"arcén peligroso a la izquierda"}],"f":6,"es":"Esta señal advierte de:","explain":"Advierte de un ESTRECHAMIENTO DE LA CALZADA POR LA IZQUIERDA — «стесняване на платното за движение отляво».\n\nLA SEÑAL. Triángulo rojo con dos trazos verticales: el de la IZQUIERDA se dobla hacia dentro, el de la derecha sigue recto. El lado que se dobla es el lado que se estrecha.\n\nFORMA TRÍO CON OTRAS DOS, y conviene aprenderlas juntas porque solo se distinguen por cuál trazo se dobla: por la izquierda (esta), por la derecha, y por ambos lados. Son tres señales distintas con tres dibujos casi idénticos.\n\nQUÉ IMPLICA. La calzada pierde anchura por ese lado. Hay que moderar y prever que los vehículos de ese lado se desplacen hacia el centro.\n\n«INCORPORACIÓN DE UN CARRIL POR LA IZQUIERDA» es lo contrario: ahí la calzada gana un carril, y su dibujo muestra una línea que se une, no que se cierra.\n\n«ARCÉN PELIGROSO» y «CAMBIO DE PENDIENTE» tienen sus propios pictogramas.\n\nCLAVE: mira qué trazo se dobla. Si se doblan los dos, es estrechamiento por ambos lados; si solo uno, ese es el lado que se cierra.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5217,"bg":"След този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334749.png","v":null,"a":[{"t":"на платното за движение може да има работещи хора","ok":true,"i":null,"es":"en la calzada puede haber personas trabajando"},{"t":"може да има препятствия по платното за движение","ok":true,"i":null,"es":"puede haber obstáculos en la calzada"},{"t":"пътят е затворен за движение","ok":false,"i":null,"es":"la vía está cerrada al tráfico"},{"t":"паркирането е забранено","ok":false,"i":null,"es":"el estacionamiento está prohibido"}],"f":6,"es":"Después de esta señal: (2 correctas)","explain":"Obras en la carretera = puede haber trabajadores Y puede haber obstaculos en la calzada. Doble peligro."},{"id":5266,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334676.png","v":null,"a":[{"t":"кръстовище с кръгово движение","ok":true,"i":null,"es":"intersección con circulación giratoria (glorieta)"},{"t":"място, на което задължително се завива в обратна посока","ok":false,"i":null,"es":"lugar donde es obligatorio dar la vuelta (cambio de sentido)"},{"t":"участък от пътя, по който е забранено да се завива в обратна посока","ok":false,"i":null,"es":"tramo de vía donde está prohibido el cambio de sentido"},{"t":"остров на платното за движение","ok":false,"i":null,"es":"isleta en la calzada"}],"f":6,"es":"Esta señal advierte de:","explain":"Glorieta proxima = intersection con trafico circular. Los que ya estan dentro tienen prioridad."},{"id":5283,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334678.png","v":null,"a":[{"t":"обозначава точното място на пешеходна пътека","ok":true,"i":null,"es":"indica el lugar exacto de un paso de peatones"},{"t":"предупреждава водачите, че приближават пешеходна пътека","ok":false,"i":null,"es":"advierte a los conductores de que se acercan a un paso de peatones"},{"t":"сигнализира началото на задължителен път само за пешеходци","ok":false,"i":null,"es":"señaliza el inicio de una vía obligatoria solo para peatones"},{"t":"указва начало на пешеходен маршрут","ok":false,"i":null,"es":"indica el inicio de una ruta peatonal"}],"f":6,"es":"Esta señal:","explain":"Indica el LUGAR EXACTO de un paso de peatones.\n\nLA SEÑAL. Cuadrado AZUL con un triángulo blanco dentro y un peatón sobre la cebra. Azul cuadrado es información o indicación, no peligro ni prohibición.\n\nLA DIFERENCIA QUE DECIDE LA PREGUNTA. Existen dos señales de paso de peatones y hacen cosas distintas: el TRIÁNGULO ROJO advierte de que te acercas a uno, con antelación; este CUADRADO AZUL marca dónde está exactamente. Una prepara, la otra localiza.\n\n«ADVIERTE DE QUE SE ACERCAN A UN PASO» es por tanto el distractor central: describe la otra señal, la triangular.\n\n«INICIO DE VÍA OBLIGATORIA SOLO PARA PEATONES» sería un círculo azul con el peatón, que es una obligación distinta.\n\n«INICIO DE UNA RUTA PEATONAL» no corresponde a este diseño.\n\nQUÉ TE OBLIGA. Ceder el paso a los peatones que cruzan o van a cruzar, y no adelantar ni estacionar en sus proximidades.\n\nCLAVE: triángulo rojo = «viene un paso». Cuadrado azul = «el paso es aquí». Mismo dibujo, distinta forma, distinta función.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":11601,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123565575.png","v":null,"a":[{"t":"за използването на пътя се изисква платена винетна или ТОЛ такса","ok":true,"i":null,"es":"para usar la vía se exige el pago de viñeta o peaje (TOL)"},{"t":"двупосочно движение след знака","ok":false,"i":null,"es":"circulación en ambos sentidos después de la señal"},{"t":"автомобилен път","ok":false,"i":null,"es":"vía rápida"},{"t":"броя на пътните ленти за движение в една посока","ok":false,"i":null,"es":"el número de carriles de circulación en un sentido"}],"f":6,"es":"Esta señal señaliza:","explain":"Via de peaje (vineta o TOL). En Bulgaria se paga vineta para autopistas y vias rapidas."},{"id":5539,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височината му, включително товара, е 4,5 м","ok":true,"i":null,"es":"4.5 m"},{"t":"височината му, включително товара, е 4,8 м","ok":true,"i":null,"es":"4.8 m"},{"t":"височината му, включително товара, е 2,5 м","ok":false,"i":null,"es":"2.5 m"},{"t":"височината му, включително товара, е 3,5 м","ok":false,"i":null,"es":"3.5 m"}],"f":6,"es":"Un vehículo es 'fuera de gálibo' cuando su altura, incluyendo carga, es: (2 correctas)","explain":"El límite de altura es 4 m: cualquier altura superior es fuera de gálibo, por eso tanto 4,5 m como 4,8 m son correctas. 2,5 m y 3,5 m quedan por debajo del límite."},{"id":5552,"bg":"При тази ситуация:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23978.png","v":null,"a":[{"t":"трябва да бъда внимателен и предпазлив","ok":true,"i":null,"es":"debo ser atento y prudente"},{"t":"няма опасност защото велосипедистите са в съседната пътна лента и ме виждат","ok":false,"i":null,"es":"no hay peligro porque los ciclistas están en el carril contiguo y me ven"}],"f":6,"es":"En esta situación:","explain":"Siempre debes ser precavido con ciclistas aunque esten en otro carril. Pueden cambiar de direccion inesperadamente."},{"id":6027,"bg":"При тази ситуация няма опасност, защото детето се качва на тротоара и освобождава платното за движение.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25918.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"es":"En esta situación no hay peligro porque el niño sube a la acera y libera la calzada. Esto es:","explain":"INCORRECTO. Los ninos son impredecibles incluso cuando suben a la acera - pueden volver a bajar en cualquier momento."},{"id":6052,"bg":"Как водачът трябва сигнализира за намерението си да се включи в движението, когато автомобилът е с повреден пътепоказател?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"подава сигнал с ръка","ok":true,"i":null,"es":"hace una señal con la mano"},{"t":"подава звуков сигнал","ok":false,"i":null,"es":"da una señal acústica"},{"t":"не е задължен да сигнализира","ok":false,"i":null,"es":"no está obligado a señalizar"},{"t":"достатъчно е превключването на светлините","ok":false,"i":null,"es":"basta con cambiar las luces"}],"f":6,"es":"¿Cómo debe señalizar el conductor su intención de incorporarse al tráfico cuando el intermitente esta averiado?","explain":"Con el intermitente averiado, la intención se señaliza CON LA MANO (brazo extendido): es el sustituto legal. El claxon no indica dirección, no señalizar es infracción y el juego de luces no es señal de incorporación."},{"id":6064,"bg":"Водачът на МПС може да подава сигнал към другите участници в движението, чрез кратковременно включване на дългите светлини (светлинния клаксон):","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"за да ги предупреди за евентуална опасност при извършване на маневра","ok":true,"i":null,"es":"para advertirles de un posible peligro al realizar una maniobra"},{"t":"за да привлече тяхното внимание при извършване на маневра","ok":true,"i":null,"es":"para llamar su atención al realizar una maniobra"},{"t":"за да укаже, че ще завива в обратна посока","ok":false,"i":null,"es":"para indicar que va a hacer un cambio de sentido"},{"t":"за да им покаже, че е с предимство","ok":false,"i":null,"es":"para mostrarles que tiene prioridad"}],"f":6,"es":"El conductor de un vehículo puede dar señal a otros participantes mediante el encendido breve de las luces largas: (2 correctas)","explain":"El destello breve de largas sirve para advertir de un peligro o llamar la atención al maniobrar (típico aviso de adelantamiento). No indica cambio de sentido ni sirve para 'reclamar' prioridad: la prioridad no se exige con luces."},{"id":6691,"bg":"При коя от изброените широчини, автомобилът е извънгабаритен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"широчина 2,9 м","ok":true,"i":null,"es":"2.9 m"},{"t":"широчина 2,7 м","ok":true,"i":null,"es":"2.7 m"},{"t":"широчина 2,5 м","ok":false,"i":null,"es":"2.5 m"},{"t":"широчина 2,3 м","ok":false,"i":null,"es":"2.3 m"}],"f":6,"es":"¿A qué anchura es un vehículo fuera de gálibo? (2 correctas)","explain":"El límite de anchura es 2,55 m: cualquier valor superior es fuera de gálibo, por eso 2,7 m y 2,9 m son correctas. 2,3 m y 2,5 m quedan dentro del límite."},{"id":9854,"bg":"В кои от посочените случаи водачът на нерелсово ППС е длъжен да пропусне преминаващите по пешеходна пътека пешеходци:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044468.png","v":null,"a":[{"t":"когато пътеката е очертана с прекъснати линии","ok":true,"i":null,"es":"cuando el paso está marcado con líneas discontinuas"},{"t":"само когато пътеката е тип „Зебра”","ok":false,"i":null,"es":"solo cuando el paso es de tipo \"cebra\""},{"t":"когато пътеката не е очертана с пътна маркировка","ok":true,"i":null,"es":"cuando el paso no está marcado con marcas viales"},{"t":"само когато пътеката е обозначена с пътен знак","ok":false,"i":null,"es":"solo cuando el paso está indicado con una señal de tráfico"}],"f":6,"es":"¿En cuáles de los casos el conductor de un vehículo no ferroviario está obligado a ceder el paso a los peatones que cruzan por el paso de peatones? (2 correctas)","explain":"Dos casos: cuando el paso está marcado con líneas DISCONTINUAS, y cuando NO está marcado con ninguna marca vial.\n\nLA IDEA DE FONDO. La obligación de ceder no nace del dibujo del suelo, nace de que ahí hay un paso de peatones. Si existe como paso, el peatón está protegido, esté pintado como esté.\n\n«CUANDO ESTÁ MARCADO CON LÍNEAS DISCONTINUAS» es correcto: es una de las formas válidas de marcar un paso.\n\n«CUANDO NO ESTÁ MARCADO CON MARCA VIAL» también: un paso puede existir señalizado solo con la señal vertical, o por la propia configuración del lugar, y sigue siendo un paso.\n\n«SOLO CUANDO ES DE TIPO CEBRA» es falso, y es el distractor principal. La cebra es la marca más visible, no la única.\n\n«SOLO CUANDO ESTÁ INDICADO CON SEÑAL» es falso por lo mismo, en la otra dirección.\n\nFÍJATE EN LA PALABRA «SOLO». Las dos opciones falsas la llevan y las dos correctas no. En este banco, «solo» y «siempre» son señales de alarma: suelen convertir una verdad parcial en una falsedad.\n\nCLAVE: pintado o sin pintar, con señal o sin ella, si es un paso el peatón pasa. Lo que la ley protege es al peatón, no a la pintura.\n\nMÉTODO CON PEATONES: la protección no depende de que el paso esté pintado ni de que haya señal. Depende de que el peatón esté cruzando donde tiene derecho. Desarrollado en Leyes → «Peatones: cuándo hay que cederles el paso»."},{"id":11813,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123823629.png","v":null,"a":[{"t":"товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра","ok":true,"i":null,"es":"camiones con masa máxima autorizada superior a 3500 kg y longitud superior a 7 metros"},{"t":"всички товарни автомобили","ok":false,"i":null,"es":"todos los camiones"},{"t":"товарните автомобили с допустима максимална маса над 3500 kg, като дължината на МПС е без значение","ok":false,"i":null,"es":"los camiones de masa máxima autorizada superior a 3500 kg, sin importar la longitud del vehículo"}],"f":6,"es":"Con este signo distintivo se identifican:","explain":"La placa trasera reflectante identifica camiones con masa >3500kg y longitud >7m. Obligatorio para mejorar visibilidad de noche."},{"id":11814,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123828334.png","v":null,"a":[{"t":"товарните автомобили с допустима максимална маса над 3500 kg и дължина над 7 метра","ok":true,"i":null,"es":"camiones con masa máxima autorizada superior a 3500 kg y longitud superior a 7 metros"},{"t":"товарните автомобили с допустима максимална маса над 2500 kg и дължина над 5 метра","ok":false,"i":null,"es":"camiones con masa superior a 2500 kg y longitud superior a 5 metros"},{"t":"всички товарни автомобили","ok":false,"i":null,"es":"todos los camiones"}],"f":6,"es":"Con esta señal de identificación se marcan:"},{"id":12075,"bg":"С жълта мигаща или проблясваща светлина се обозначава:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"МПС, което е препятствие за другите превозни средства","ok":true,"i":null,"es":"un vehículo de motor que es un obstáculo para los demás vehículos"},{"t":"МПС, което създава опасност за движението","ok":true,"i":null,"es":"un vehículo de motor que crea peligro para el tráfico"},{"t":"МПС със специален режим на движение","ok":false,"i":null,"es":"un vehículo de motor con régimen especial de circulación"},{"t":"всички автомобили със специално предназначение","ok":false,"i":null,"es":"todos los automóviles de uso especial"}],"f":6,"es":"Con luz amarilla intermitente o destellante se identifica: (2 correctas)","explain":"La luz amarilla intermitente identifica al vehículo que es un OBSTÁCULO o crea peligro para el tráfico (grúas, quitanieves, transportes especiales). El régimen especial de circulación usa luces azules/rojas: esa es la diferencia clave."},{"id":5984,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51835.png","v":null,"a":[{"t":"забранява влизането на МПС с ремаркета с две и повече оси","ok":true,"i":null,"es":"prohíbe la entrada de vehículos con remolques de dos o más ejes"},{"t":"не забранява влизането на МПС с полуремаркета","ok":false,"i":null,"es":"NO prohíbe la entrada de vehículos con semirremolques"},{"t":"забранява влизането на МПС с единични едноосни ремаркета","ok":true,"i":null,"es":"prohíbe la entrada de vehículos con remolques simples de un eje"}],"f":6,"es":"Esta señal: (2 correctas)"},{"id":6192,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334696.png","v":null,"a":[{"t":"задължава водачите да се движат само наляво пред знака","ok":true,"i":null,"es":"obliga a circular solo a la izquierda ANTES de la señal"},{"t":"задължава водачите да се движат само наляво след знака","ok":false,"i":null,"es":"obliga a circular solo a la izquierda DESPUÉS de la señal"},{"t":"задължава водачите да преминат отляво на знака","ok":false,"i":null,"es":"obliga a pasar por la izquierda de la señal"}],"f":6,"es":"Esta señal:"},{"id":6239,"bg":"Допълнителната табела указва, че в посоченото време паркирането е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54088.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":6,"es":"La tablilla adicional indica que en el horario señalado el aparcamiento está:","explain":"PROHIBIDO en el horario indicado.\n\nQUÉ VES. La señal de prohibido estacionar con una tablilla adicional debajo que marca un intervalo de horas.\n\nQUÉ HACE LA TABLILLA. No invierte la señal: la ACOTA. La prohibición existe, y la tablilla dice cuándo se aplica. Dentro de ese horario, prohibido; fuera de él, la señal no rige.\n\nEL ERROR QUE CASTIGA LA PREGUNTA es leer el horario como un permiso — «de 6 a 17 sí puedo». La tablilla nunca autoriza nada: solo delimita el alcance de la señal que tiene encima.\n\nTRES FORMAS DE ACOTAR que verás en el examen: por HORARIO, como aquí; por TIPO de vehículo, como la de camiones; y por CONDICIONES, como el copo de nieve de la pregunta 6280.\n\nCLAVE: la tablilla responde a «cuándo» o «a quién», nunca a «qué». El «qué» lo dice siempre la señal principal, y no cambia.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":11869,"bg":"При тази ситуация, движението на товарни автомобили по лентата, над която е поставен пътният знак, е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57279.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"разрешено, но само със скорост не по-висока от означената","ok":false,"i":null,"es":"permitido, pero solo a una velocidad no superior a la indicada"},{"t":"разрешено, ако масата им с товар е не по-голяма от 3.5 t","ok":false,"i":null,"es":"permitido, si su masa con carga no supera las 3,5 t"}],"f":6,"es":"En esta situación, la circulación de camiones por el carril sobre el que está colocada la señal está:","explain":"PROHIBIDA.\n\nQUÉ VES. Un pórtico sobre la calzada con la señal circular de prohibido el paso a camiones colocada encima de un carril concreto, con una tablilla que la asigna a ese carril.\n\nUNA SEÑAL SOBRE UN CARRIL SOLO AFECTA A ESE CARRIL. Es la misma lógica de los semáforos de carril: lo que cuelga sobre tu carril te habla a ti. Para los camiones, ese carril está cerrado; los demás siguen abiertos.\n\n«PERMITIDO PERO A VELOCIDAD NO SUPERIOR A LA INDICADA» es el distractor principal, y nace de mezclar dos señales de la escena: la de camiones y la de límite de velocidad. La de velocidad limita a quien SÍ puede pasar; no convierte una prohibición en un permiso condicionado.\n\n«PERMITIDO SI SU MASA CON CARGA NO SUPERA 3,5 t» inventa un umbral que la señal no lleva. Cuando el círculo rojo con el camión incorpora una cifra de toneladas, la lleva escrita dentro; si no la lleva, alcanza a todos los camiones.\n\nCLAVE: dos señales en la misma escena no se combinan. Cada una dice lo suyo y la más restrictiva manda para quien esté afectado por ella.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":11889,"bg":"По този път извън населено място, участъкът с опасни завои започва на разстояние:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56122.png","v":null,"a":[{"t":"от 100 до 150 метра след знака","ok":true,"i":null,"es":"entre 100 y 150 metros después de la señal"},{"t":"от 50 до 100 метра след знака","ok":false,"i":null,"es":"entre 50 y 100 metros después"},{"t":"на 250 метра след знака","ok":false,"i":null,"es":"a 250 metros"},{"t":"не повече от 250 метра","ok":false,"i":null,"es":"no más de 250 metros"}],"f":6,"es":"Por esta carretera fuera de población, el tramo con curvas peligrosas empieza a:"},{"id":5915,"bg":"Жълтата мигаща светлина:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43915.png","v":null,"a":[{"t":"означава „Внимание”","ok":true,"i":null,"es":"significa '¡Atención!'"},{"t":"предупреждава водачите да бъдат внимателни и предпазливи","ok":true,"i":null,"es":"advierte a los conductores que sean atentos y precavidos"},{"t":"означава, че преминаването без спиране е забранено","ok":false,"i":null,"es":"significa que pasar sin detenerse está prohibido"},{"t":"указва, че движението се регулира от регулировчик","ok":false,"i":null,"es":"indica que el tráfico lo regula un agente"}],"f":6,"es":"La luz amarilla parpadeante: (2 correctas)"},{"id":6072,"bg":"На двупосочен път, с по една пътна лента за движение във всяка посока, превозните средства трябва да се движат:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/123692.png","v":null,"a":[{"t":"в дясната пътна лента","ok":true,"i":null,"es":"en el carril derecho"},{"t":"в средната част на пътя","ok":false,"i":null,"es":"por el centro del camino"},{"t":"в лявата пътна лента","ok":false,"i":null,"es":"en el carril izquierdo"}],"f":6,"es":"En vía de doble sentido con un carril por sentido, los vehículos deben circular:"},{"id":6098,"bg":"Кой от автомобилите се движи прaвилно по този път в населено място?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63723.png","v":null,"a":[{"t":"само синият автомобил","ok":false,"i":null,"es":"solo el azul"},{"t":"само червеният автомобил","ok":false,"i":null,"es":"solo el rojo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"ambos coches"}],"f":6,"explain":"Cuando la pregunta presenta dos vehículos en colores distintos circulando en una vía urbana y pregunta cuál circula 'correctamente', normalmente la respuesta correcta es 'ambos' cuando cada uno respeta su carril, su sentido de circulación y las normas de posición en la calzada de forma independiente — no hay conflicto de prioridad entre ellos porque no se cruzan ni invaden el carril del otro. Antes de buscar un error, verifica: ¿ambos están en sentido permitido?, ¿ambos respetan el carril que les corresponde?, ¿hay algo (línea continua, sentido único) que uno de los dos esté violando? Si no encuentras ninguna infracción clara en ninguno de los dos, la respuesta de que ambos circulan bien es la más probable.","es":"¿Qué vehículo circula correctamente por esta vía en zona urbana?"},{"id":11686,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62875.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"пътното платно да е с не по-малко от три пътни ленти за движение в една посока","ok":false,"i":null,"es":"la calzada tiene no menos de tres carriles en una dirección"},{"t":"разрешената скорост за движение да е не по-голяма от 50 km/h","ok":false,"i":null,"es":"la velocidad máxima es no superior a 50 km/h"}],"f":6,"es":"¿Qué condiciones deben cumplirse para que, circulando en poblado, el conductor pueda usar el carril más cómodo para él? (2 correctas)"},{"id":5808,"bg":"При тази ситуация водачът на червения автомобил може да се движи с разрешената максимална скорост:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54069.png","v":null,"a":[{"t":"само при наличието на необходимите условия за безопасност","ok":true,"i":null,"es":"solo si hay condiciones de seguridad suficientes"},{"t":"във всички случаи","ok":false,"i":null,"es":"en todos los casos"},{"t":"само, ако има стаж като водач над 2 години","ok":false,"i":null,"es":"solo si lleva más de 2 años de permiso"}],"f":6,"es":"En esta situación el conductor del coche rojo puede circular a la velocidad máxima permitida:"},{"id":5836,"bg":"Коефициентът на сцепление на автомобилните гуми с пътя е показател за:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"взаимодействието между автомобилната гума и пътната настилка","ok":true,"i":null,"es":"la interacción entre el neumático y el pavimento"},{"t":"аеродинамичните качества на автомобила","ok":false,"i":null,"es":"las cualidades aerodinámicas del vehículo"},{"t":"ефективността на спирачната система на автомобила","ok":false,"i":null,"es":"la eficacia del sistema de frenos"}],"f":6,"es":"El coeficiente de rozamiento entre neumáticos y calzada es un indicador de:","explain":"El coeficiente de rozamiento mide la interacción neumático-pavimento (la adherencia disponible). No dice nada de la aerodinámica ni de la eficacia del sistema de frenos: unos frenos perfectos no frenan sin adherencia."},{"id":5846,"bg":"Как се изменя сцеплението на автомобилните гуми с пътя при мокра настилка в сравнение със суха?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"намалява","ok":true,"i":null,"es":"disminuye"},{"t":"увеличава се","ok":false,"i":null,"es":"aumenta"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"},{"t":"зависи от вида на автомобилната гума","ok":false,"i":null,"es":"depende del tipo de neumático"}],"f":6,"es":"¿Cómo varía el rozamiento de los neumáticos en pavimento mojado respecto al seco?","explain":"En mojado el rozamiento DISMINUYE siempre: el agua actúa como lubricante entre neumático y asfalto. Ocurre con cualquier tipo de neumático; por eso la distancia de frenado crece con lluvia."},{"id":5860,"bg":"Преди да намали значително скоростта на движение, водачът на МПС е задължен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се убеди, че няма да застраши останалите участници в движението","ok":true,"i":null,"es":"asegurarse de no poner en peligro a los demás participantes"},{"t":"да сигнализира с десен пътепоказател","ok":false,"i":null,"es":"señalizar con el intermitente derecho"},{"t":"да премине в най-дясната пътна лента","ok":false,"i":null,"es":"pasar al carril más a la derecha"},{"t":"да напусне платното за движение","ok":false,"i":null,"es":"abandonar la calzada"}],"f":6,"es":"Antes de reducir significativamente la velocidad, el conductor está obligado a:","explain":"Antes de reducir bruscamente la velocidad debes asegurarte de no crear peligro, sobre todo para el que te sigue. El intermitente derecho indica giro (no frenada) y no hay obligación de cambiar de carril ni salir de la calzada."},{"id":5886,"bg":"При тази ситуация няма ограничения и мога да увелича скоростта на движение.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57858.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"es":"En esta situación no hay restricciones y puedo aumentar la velocidad. Esto es:"},{"id":5901,"bg":"Кое от изброените действия трябва да предприемете при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58182.png","v":null,"a":[{"t":"да осигуря достатъчна странична дистанция","ok":true,"i":null,"es":"garantizar distancia lateral suficiente"},{"t":"да бъда внимателен и предпазлив","ok":true,"i":null,"es":"ser atento y precavido"},{"t":"да подам звуков сигнал","ok":false,"i":null,"es":"tocar el claxon"},{"t":"незабавно да спра","ok":false,"i":null,"es":"frenar de inmediato"}],"f":6,"es":"¿Qué acciones debes tomar en esta situación? (2 correctas)"},{"id":6700,"bg":"Когато поради вида на превозвания товар, центърът на тежестта на автомобила е по-висок от конструктивния, водачът трябва да намали скоростта:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"преди навлизане в завой","ok":true,"i":null,"es":"antes de entrar en una curva"},{"t":"при неравности на платното за движение","ok":true,"i":null,"es":"con irregularidades en el pavimento"},{"t":"при силен страничен вятър","ok":true,"i":null,"es":"con viento lateral fuerte"},{"t":"при движение по стръмен наклон при изкачване","ok":false,"i":null,"es":"en subida pronunciada"}],"f":6,"es":"Con el centro de gravedad más alto de lo normal, mayor riesgo de vuelco hay: (3 correctas)","explain":"Con el centro de gravedad alto, el vuelco amenaza donde hay fuerzas LATERALES: al entrar en curva, sobre irregularidades del pavimento y con viento lateral fuerte. Una subida pronunciada recta no genera fuerza lateral."},{"id":11701,"bg":"Когато няма други ограничения, водачът на състав от ППС от категория ВЕ при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":6,"es":"Sin otras restricciones, el conductor de convoy categoría BE en zona urbana no debe superar:","explain":"50 km/h: el límite urbano general no cambia por llevar remolque. Para un conjunto categoría BE en población rige el mismo máximo que para el resto de vehículos de motor."},{"id":11704,"bg":"Когато няма други ограничения, водачът на товарен автомобил с допустима максимална маса 3 t., при движение в населено място, не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"}],"f":6,"es":"Sin otras restricciones, el conductor de camión de 3 t en zona urbana no debe superar:","explain":"50 km/h: en población el límite general es 50 km/h para todos los vehículos de motor, incluido un camión de 3 t, salvo señalización distinta."},{"id":12026,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":11,"a":[{"t":"да увелича скоростта","ok":false,"i":null,"es":"acelerar"},{"t":"да спра аварийно/рязко","ok":true,"i":null,"es":"freno de emergencia"},{"t":"да продължа движението си, като подам звуков сигнал","ok":false,"i":null,"es":"continúo tocando el claxon"}],"f":6,"es":"¿Qué debes hacer en esta situación?"},{"id":6227,"bg":"Преди да се включи в движението, водачът на ППС е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да се убеди, че няма да създаде опасност за другите участници в движението","ok":true,"i":null,"es":"asegurarse de no crear peligro para los demás"},{"t":"да подаде сигнал със съответния пътепоказател","ok":true,"i":null,"es":"activar el intermitente"},{"t":"да подаде звуков или светлинен сигнал с фаровете, с което да си осигури предимство","ok":false,"i":null,"es":"dar señal acústica o de luces para asegurarse prioridad"},{"t":"да изчака сигнал от другите водачи, че може да потегли","ok":false,"i":null,"es":"esperar señal de los demás conductores"}],"f":6,"es":"Antes de incorporarse al tráfico, el conductor está obligado a: (2 correctas)","explain":"Para incorporarte al tráfico: comprueba que no creas peligro para nadie y señaliza con el intermitente. La prioridad no se pide con el claxon o las luces: los que circulan no están obligados a cederte el paso."},{"id":6236,"bg":"Кой от водачите е с предимство при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69768.png","v":null,"a":[{"t":"водачът на товарния автомобил","ok":true,"i":null,"es":"el conductor del camión"},{"t":"водачът на лекия автомобил","ok":false,"i":null,"es":"el conductor del turismo"},{"t":"водачът на автомобила, който пръв достигне до препятствието","ok":false,"i":null,"es":"el conductor que llegue primero al obstáculo"}],"f":6,"es":"¿Qué conductor tiene prioridad en esta situación?"},{"id":6240,"bg":"Когато на кръстовище пътните ленти не са обозначени с пътна маркировка за движение в съответна посока, завиването надясно е разрешено да се извършва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от най-дясната част на платното за движение","ok":true,"i":null,"es":"desde la parte más a la derecha de la calzada"},{"t":"от която и да е част на платното за движение, ако радиусът на завиване на автомобила е по-голям от радиуса на завоя","ok":true,"i":null,"es":"desde cualquier posición si el radio de giro lo requiere"},{"t":"във всички случаи от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo en todos los casos"}],"f":6,"es":"Cuando no hay marcas de carril en intersección, girar a la derecha se hace: (2 correctas)","explain":"Sin marcas viales, el giro a la derecha se hace desde la parte más a la derecha de la calzada; se admite otra posición solo cuando el radio de giro del vehículo lo exige (vehículos largos). Nunca 'desde donde sea cómodo'."},{"id":6242,"bg":"Когато на кръстовище пътните ленти са обозначени за движение в съответна посока, завиването надясно може да се извърши:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от пътна лента обозначена за завиване надясно","ok":true,"i":null,"es":"desde carril marcado para girar a la derecha"},{"t":"от която и да е пътна лента, ако радиусът на завиване на автомобила е по-голям от радиуса на завоя","ok":true,"i":null,"es":"desde cualquier carril si el radio de giro lo requiere"},{"t":"от най-дясната пътна лента по посока на движението","ok":true,"i":null,"es":"desde el carril más a la derecha en el sentido de marcha"},{"t":"във всички случаи от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo en todos los casos"}],"f":6,"es":"Cuando los carriles están marcados, girar a la derecha puede hacerse: (3 correctas)","explain":"Con carriles marcados puedes girar a la derecha desde: el carril con flecha a la derecha, el carril más a la derecha, u otro carril si el radio de giro del vehículo lo exige. La comodidad del conductor no es criterio legal."},{"id":6259,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69985.png","v":null,"a":[{"t":"трябва да пропусна пешеходеца","ok":true,"i":null,"es":"debo dejar pasar al peatón"},{"t":"мога да премина преди пешеходеца, ако той се движи бавно","ok":false,"i":null,"es":"puedo pasar antes si camina despacio"},{"t":"не съм задължен да пропусна пешеходеца, защото пешеходната пътека не е маркирана","ok":false,"i":null,"es":"no estoy obligado porque el paso no está marcado"}],"f":6,"es":"En esta situación:"},{"id":6348,"bg":"Когато е разрешено едновременното им преминаване, водачът на нерелсово ППС е длъжен да пропусне релсовото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"винаги, независимо от местоположението му","ok":true,"i":null,"es":"siempre, independientemente de su posición"},{"t":"винаги, независимо от посоката му на движение","ok":true,"i":null,"es":"siempre, independientemente de su dirección"},{"t":"само когато релсовото ППС се намира от дясната му страна","ok":false,"i":null,"es":"solo cuando está a su derecha"},{"t":"само в случаите, когато релсовото превозно средство не завива","ok":false,"i":null,"es":"solo cuando no gira"}],"f":6,"es":"Cuando está permitido el paso simultáneo, el conductor no ferroviario debe ceder al ferroviario: (2 correctas)","explain":"Cuando el paso simultáneo está permitido, el vehículo no ferroviario cede SIEMPRE al ferroviario: da igual su posición (derecha/izquierda) y da igual su dirección. El tren y el tranvía no pueden esquivar."},{"id":6368,"bg":"Завиването в обратна посока е забранено, когато видимостта е намалена под:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 м","ok":true,"i":null,"es":"50 m"},{"t":"250 м","ok":false,"i":null,"es":"250 m"},{"t":"150 м","ok":false,"i":null,"es":"150 m"},{"t":"100 м","ok":false,"i":null,"es":"100 m"}],"f":6,"es":"El cambio de sentido está prohibido cuando la visibilidad es inferior a:","explain":"50 m: es el umbral legal. Con visibilidad inferior a 50 metros el cambio de sentido está prohibido, porque el tráfico que aparezca no tendría distancia para reaccionar."},{"id":6375,"bg":"При тази ситуация разрешено ли е да завиете в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71210.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"¿Está permitido dar la vuelta en esta situación?"},{"id":6376,"bg":"При тази ситуация разрешено ли е да завиете в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71243.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"¿Está permitido dar la vuelta en esta situación?"},{"id":6386,"bg":"При тази ситуация червеният автомобил е с предимство за преминаване през стеснения участък от пътя.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71375.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":6,"es":"En esta situación el coche rojo tiene prioridad para pasar por el tramo estrecho. Esto es:"},{"id":6401,"bg":"След този пътен знак на водачите на товарни автомобили с допустима максимална маса над 3,5 т е разрешено да изпреварват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67956.png","v":null,"a":[{"t":"мотоциклети без кош","ok":true,"i":null,"es":"motos sin sidecar"},{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"леки автомобили","ok":false,"i":null,"es":"turismos"},{"t":"автобуси","ok":false,"i":null,"es":"autobuses"}],"f":6,"es":"Después de esta señal, los conductores de camiones con MMA >3.5t PUEDEN adelantar a: (2 correctas)"},{"id":6405,"bg":"След този пътен знак разрешено ли е на водачите на товарни автомобили да изпреварват други автомобили?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68072.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está permitido a los conductores de camiones adelantar otros vehículos después de esta señal?"},{"id":6416,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при намалена видимост, когато разстоянието е по-малко от необходимото за изпреварване","ok":true,"i":null,"es":"con visibilidad reducida y distancia insuficiente"},{"t":"пред и върху сигнализирана пешеходна пътека","ok":true,"i":null,"es":"la visibilidad es limitada"},{"t":"на надлез","ok":false,"i":null,"es":"en paso elevado"},{"t":"при движение през нощта","ok":false,"i":null,"es":"de noche"}],"f":6,"es":"El adelantamiento está PROHIBIDO: (2 correctas)","explain":"Prohibido adelantar cuando la visibilidad es reducida (niebla, lluvia) o limitada (curva, cambio de rasante) y la distancia visible no basta para completar la maniobra. Ni el paso elevado ni la noche lo prohíben por sí mismos."},{"id":6420,"bg":"Разрешено ли е при изпреварване да използвате превключването на светлините като допълнителен сигнал?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está permitido usar el parpadeo de luces como señal adicional al adelantar?","explain":"Sí: el parpadeo de las luces de carretera es una señal adicional válida para avisar del adelantamiento (especialmente útil de día y fuera de población), junto con el intermitente."},{"id":6425,"bg":"При изпреварване се преминава от лявата страна на изпреварваното ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":6,"es":"Al adelantar se pasa por el lado IZQUIERDO del vehículo adelantado. Esto es:","explain":"Correcto: la regla general es adelantar por el lado IZQUIERDO del vehículo adelantado. Por la derecha solo se rebasa a quien ha señalizado y se ha posicionado para girar a la izquierda."},{"id":6447,"bg":"При тази ситуация разрешено ли е да преминете по трамвайните линии, за да изпреварите товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128523.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"En esta situación ¿está permitido circular por las vías del tranvía para adelantar al camión?"},{"id":9829,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270041864.png","v":null,"a":[{"t":"да пропусна пешеходеца","ok":true,"i":null,"es":"ceder el paso al peatón"},{"t":"да премина преди пешеходеца","ok":false,"i":null,"es":"pasar antes que el peatón"}],"f":6,"es":"En esta situación debo:"},{"id":12038,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":27,"a":[{"t":"да остана в средата на заеманата лента","ok":false,"i":null,"es":"me quedo en el centro del carril"},{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"да премина възможно най-вдясно","ok":true,"i":null,"es":"me desplazo todo lo posible a la derecha"}],"f":6,"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)"},{"id":12041,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":33,"a":[{"t":"да увелича скоростта","ok":false,"i":null,"es":"acelerar"},{"t":"да се движа възможно най-вдясно","ok":true,"i":null,"es":"circulo todo lo posible a la derecha"},{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"}],"f":6,"es":"¿Qué debes hacer en esta situación? (2 correctas)"},{"id":5916,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48258.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"En esta situación ¿está permitido girar a la derecha?"},{"id":6342,"bg":"На водача е забранено да навлиза на железопътния прелез:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато бариерите са спуснати и започват да се вдигат","ok":true,"i":null,"es":"cuando las barreras están bajadas y empiezan a subir"},{"t":"когато е включена звуковата сигнализация","ok":true,"i":null,"es":"cuando está activa la señal acústica"},{"t":"при мигаща червена светлина на светофара","ok":true,"i":null,"es":"con luz roja parpadeante del semáforo"},{"t":"когато светофарната уредба подава сигнал от бавно мигащата светлина с луннобял цвят","ok":false,"i":null,"es":"cuando el semáforo emite luz blanca lenta parpadeante"}],"f":6,"explain":"Prohibido entrar: con las barreras bajadas incluso cuando ya empiezan a SUBIR (espera a que estén arriba del todo), con la señal acústica activa y con luz roja parpadeante. La luz BLANCA lenta parpadeante significa lo contrario: paso permitido.","es":"Al conductor le está PROHIBIDO entrar al paso a nivel: (3 correctas)"},{"id":6347,"bg":"На водача е забранено да навлиза на железопътния прелез:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"преди да се е убедил, че към прелеза не се приближава влак","ok":true,"i":null,"es":"antes de asegurarse de que no se aproxima ningún tren"},{"t":"когато е включена звуковата сигнализация","ok":true,"i":null,"es":"cuando está activa la señal acústica"},{"t":"когато светофарната уредба подава сигнал от бавно мигащата светлина с луннобял цвят","ok":false,"i":null,"es":"cuando el semáforo emite luz blanca lenta parpadeante"},{"t":"когато от другата страна на прелеза няма достатъчно място за продължаване на движението","ok":true,"i":null,"es":"cuando al otro lado no hay espacio suficiente para continuar"}],"f":6,"es":"Al conductor le está PROHIBIDO entrar al paso a nivel: (3 correctas)","explain":"Prohibido entrar: sin haber comprobado que no viene tren, con la señal acústica activa, y sin espacio libre al otro lado. La luz BLANCA lenta intermitente del semáforo ferroviario significa paso PERMITIDO, por eso esa opción es falsa."},{"id":6467,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на червения автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53360.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да се движа с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"f":6,"es":"¿Cómo debes actuar en esta situación si el conductor del coche rojo, que debe cederte el paso, no muestra con sus acciones que vaya a parar? (2 correctas)"},{"id":6478,"bg":"В тунел този знак с допълнителна табела сигнализира:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/84174.png","v":null,"a":[{"t":"място за принудително спиране","ok":true,"i":null,"es":"lugar de parada forzosa"},{"t":"място за паркиране с телефон и пожарогасител","ok":false,"i":null,"es":"lugar de aparcamiento con teléfono y extintor"}],"f":6,"es":"En un túnel esta señal con tablilla indica:"},{"id":6481,"bg":"В тунел този знак сигнализира:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/84141.png","v":null,"a":[{"t":"уширение на пътното платно с аварийна станция","ok":true,"i":null,"es":"ensanchamiento de la calzada con estación de emergencia"},{"t":"допълнителна пътна лента за принудително спиране","ok":false,"i":null,"es":"carril adicional de parada forzosa"},{"t":"място за паркиране","ok":false,"i":null,"es":"zona de aparcamiento"}],"f":6,"es":"En un túnel esta señal indica:"},{"id":6485,"bg":"При тази ситуация трябва задължително да завия наляво.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54487.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"explain":"Esta pregunta tipo 'verdadero/falso' evalúa si entiendes que las flechas de dirección obligatoria pintadas en el suelo o las señales de carril NO siempre obligan a un giro específico — depende de qué carril específico estés ocupando. Si la pregunta dice 'debo obligatoriamente girar a la izquierda' sin especificar en qué carril te encuentras, generalmente es FALSO como afirmación absoluta, porque la obligación de giro depende del carril: solo el carril marcado con flecha de giro a la izquierda te obliga a girar; si estás en otro carril, no tienes esa obligación. Lee siempre la pregunta buscando si dice 'siempre', 'obligatoriamente' sin matices — esas palabras absolutas suelen ser la pista de que la respuesta correcta es que NO es así en todos los casos.","es":"En esta situación estoy obligado a girar a la izquierda. Esto es:"},{"id":6498,"bg":"Извършването на коя от изброените маневри е забранено в тунел?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"движение назад","ok":true,"i":null,"es":"marcha atrás"},{"t":"завиване в обратна посока","ok":true,"i":null,"es":"cambio de sentido"},{"t":"заобикаляне","ok":false,"i":null,"es":"rodear un obstáculo"},{"t":"изпреварване","ok":false,"i":null,"es":"adelantar"}],"f":6,"es":"¿Qué maniobras están PROHIBIDAS en un túnel? (2 correctas)","explain":"En túnel están prohibidas la marcha atrás y el cambio de sentido (maniobras contra el flujo en espacio cerrado). Adelantar o rodear un obstáculo no están prohibidos con carácter general en túneles."},{"id":6530,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57673.png","v":null,"a":[{"t":"да пропусна червения автомобил","ok":true,"i":null,"es":"dejar pasar al rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"}],"f":6,"es":"En esta situación debo: (2 correctas)"},{"id":6534,"bg":"Задължени ли сте при тази ситуация да пропуснете синия автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57946.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está obligado a ceder el paso al coche azul?"},{"id":6541,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66300.png","v":null,"a":[{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al coche azul"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al coche rojo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"a los dos coches"}],"f":6,"es":"En esta situación debo ceder el paso:"},{"id":6575,"bg":"При тази ситуация преминавам с предимство, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68039.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"explain":"INCORRECTO.\n\nLA RAZÓN ES FALSA, y con eso basta. «Ir recto» no otorga prioridad en ninguna situación del código búlgaro. La prioridad sale de las señales, del semáforo, del agente o de la posición relativa — nunca de la maniobra que tú hayas elegido.\n\nQUÉ PASA REALMENTE EN LA ESCENA. Tienes un camión a la derecha y un coche de frente. El camión llega por tu derecha en un cruce que no te da preferencia, así que es a él a quien cedes: no solo la razón es falsa, la conclusión también.\n\nPOR QUÉ ESTE ENUNCIADO ENGAÑA. Seguir recto se siente como «no estoy haciendo nada raro, no molesto a nadie», y de ahí se salta a «luego tengo derecho». Son dos cosas distintas: no maniobrar te ahorra obligaciones añadidas, pero no te da ninguna.\n\nFAMILIA DE ENUNCIADOS CON «PORQUE». Cuando la justificación es «porque va recto», «porque señalicé antes», «porque estoy más adelantado» o «porque es más grande», la respuesta es неправилно casi sin excepción.\n\nCLAVE: evalúa por separado la conclusión y la razón. Si la razón falla, ya es incorrecto aunque la conclusión acertara por casualidad.\n\nMÉTODO DE PRIORIDAD: 1) ¿hay agente? manda él. 2) ¿hay semáforo? manda sobre las señales de prioridad. 3) ¿hay tabla bajo la señal? el trazo GRUESO dice por dónde va la preferente. 4) si nada separa a los dos coches, decide la derecha. Desarrollado en Leyes → «Prioridad en cruces: la escalera y la regla de la derecha».","es":"En esta situación tengo prioridad porque voy recto. Esto es:"},{"id":11588,"bg":"Задължен ли е водачът да изключи двигателя при принудително спиране в тунел?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, когато началото на тунела е обозначено с пътен знак","ok":true,"i":null,"es":"sí, cuando el inicio del túnel está señalizado"},{"t":"да, когато спирането не е кратковременно","ok":true,"i":null,"es":"sí, cuando la parada no es breve"},{"t":"да, независимо от причината за спирането и продължителността на спирането","ok":false,"i":null,"es":"sí, independientemente de la causa y duración"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está obligado a apagar el motor al parar forzosamente en túnel señalizado? (2 correctas)","explain":"Sí, en dos supuestos: cuando el inicio del túnel está señalizado con señal de tráfico y cuando la parada no va a ser breve. No es 'siempre' (parada breve en túnel no señalizado) ni 'nunca'."},{"id":5356,"bg":"Автомобилният път е предназначен за движение на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"автомобили","ok":true,"i":null,"es":"automóviles"},{"t":"мотоциклети","ok":true,"i":null,"es":"motocicletas"},{"t":"МПС с изключение на самоходните машини","ok":false,"i":null,"es":"vehículos de motor, excepto las máquinas autopropulsadas"},{"t":"МПС с изключение на мотопедите","ok":false,"i":null,"es":"vehículos de motor, excepto los ciclomotores"}],"f":6,"es":"El camino de automóviles está destinado a la circulación de: (2 correctas)","explain":"La vía rápida (camino de automóviles) admite automóviles y motocicletas: vehículos capaces de mantener velocidad alta. Las opciones con 'excepto' están mal formuladas respecto a la definición legal, que se enuncia en positivo."},{"id":5390,"bg":"На автомагистрала е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"леки автомобили с ремаркета","ok":false,"i":null,"es":"turismos con remolque"},{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"}],"f":6,"es":"En autopista esta prohibida la circulación de: (3 correctas)","explain":"En autopista no circulan ciclomotores, tractores ni bicicletas: no alcanzan la velocidad mínima de seguridad. Los turismos con remolque sí están admitidos (límite 100 km/h)."},{"id":5403,"bg":"На автомагистрала е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"движението назад","ok":true,"i":null,"es":"ir marcha atrás"},{"t":"завиването в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"движението на мотоциклети без кош","ok":false,"i":null,"es":"la circulación de motocicletas sin sidecar"},{"t":"отстраняване на повреда на МПС в лентата за принудително спиране","ok":false,"i":null,"es":"reparar una avería del vehículo en el carril de parada de emergencia"}],"f":6,"es":"En autopista está prohibido: (2 correctas)","explain":"En autopista están prohibidos la marcha atrás y el cambio de sentido. Las motos sin sidecar circulan legalmente, y reparar una avería en el carril de emergencia es precisamente su uso legítimo."},{"id":5413,"bg":"На автомобилен път паркирането е разрешено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"само на специално обозначените за това места","ok":true,"i":null,"es":"solo en los lugares especialmente señalizados para ello"},{"t":"най-вдясно на платното за движение","ok":false,"i":null,"es":"lo más a la derecha de la calzada de circulación"},{"t":"само извън платното за движение","ok":false,"i":null,"es":"solo fuera de la calzada"},{"t":"най-вдясно на пътното платно","ok":false,"i":null,"es":"lo más a la derecha de la calzada"}],"f":6,"es":"En carretera de automóviles el aparcamiento está permitido:","explain":"En vía rápida solo se aparca en los lugares especialmente señalizados. No existe el 'a la derecha de la calzada' ni el 'fuera de la calzada' libre: fuera de zona habilitada solo cabe la emergencia."},{"id":5427,"bg":"В кои случаи автомобилът, спрян в лентата за принудително спиране на автомагистрала, задължително се сигнализира?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"през нощта","ok":true,"i":null,"es":"de noche"},{"t":"при намалена видимост","ok":true,"i":null,"es":"con visibilidad reducida"},{"t":"винаги","ok":false,"i":null,"es":"siempre"},{"t":"при ограничена видимост","ok":false,"i":null,"es":"con visibilidad limitada"}],"f":6,"explain":"Debe señalizarse de NOCHE y con visibilidad REDUCIDA (niebla, lluvia intensa): cuando el ojo no lo detecta a tiempo. 'Siempre' sobra de día despejado, y 'limitada' es el término de curvas y rasantes, no el de esta norma.","es":"¿En qué casos el vehículo parado en el carril de emergencia de autopista debe señalizarse? (2 correctas)"},{"id":11711,"bg":"Когато няма други ограничения, на водача на лек автомобил, при движение извън населено място, по автомобилен път, е забранено да се движи със скорост по-висока от:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"130 km/h","ok":false,"i":null,"es":"130 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"}],"f":6,"es":"Cuando no hay otras restricciones, al conductor de turismo circulando fuera de población por carretera de automóviles le está prohibido superar:","explain":"90 km/h... ojo a la trampa: la pregunta dice 'fuera de población POR carretera de automóviles' con la respuesta verificada en 90. Aprende el número que da el banco oficial para esta formulación exacta; en el examen la literalidad manda."},{"id":11719,"bg":"При тази ситуация водачът на товарния автомобил не извършва нарушение ако:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41606.png","v":null,"a":[{"t":"е спрял поради повреда","ok":true,"i":null,"es":"se ha detenido por avería"},{"t":"е спрял за престой","ok":false,"i":null,"es":"se ha detenido para una parada (престой)"},{"t":"се движи със скорост не по- висока от 30 km/h","ok":false,"i":null,"es":"circula a una velocidad no superior a 30 km/h"},{"t":"е паркирал","ok":false,"i":null,"es":"está estacionado"}],"f":6,"es":"En esta situación el conductor del camión no comete infracción si:","explain":"Ha parado por averia. Parar en autopista o via rapida solo esta permitido por averia real o emergencia medica."},{"id":5547,"bg":"Този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334687.png","v":null,"a":[{"t":"указва начало на автобусна спирка","ok":true,"i":null,"es":"indica el inicio de una parada de autobús"},{"t":"обозначава края на автобусна спирка","ok":false,"i":null,"es":"indica el final de una parada de autobús"},{"t":"предупреждава за пресичане на път, по който се движат автобуси","ok":false,"i":null,"es":"advierte del cruce con una vía por la que circulan autobuses"},{"t":"указва пътна лента за движение само на автобуси","ok":false,"i":null,"es":"indica un carril reservado a autobuses"}],"f":6,"es":"Esta señal de tráfico:","explain":""},{"id":5555,"bg":"С този знак се обозначава:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/38854.png","v":null,"a":[{"t":"трамвайна спирка","ok":true,"i":null,"es":"parada de tranvía"},{"t":"пресичане на трамвайна линия","ok":false,"i":null,"es":"cruce con una línea de tranvía"},{"t":"трамваен път","ok":false,"i":null,"es":"vía de tranvía"},{"t":"вход/изход на трамваен път","ok":false,"i":null,"es":"entrada/salida de una vía de tranvía"}],"f":6,"es":"Con esta señal se indica:","explain":""},{"id":5586,"bg":"Кое от изброените действия ще предприемете в тази ситуация при разминаване с потеглящия от спирката автобус?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39121.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"управлявам с готовност за спиране","ok":true,"i":null,"es":"circulo listo para frenar"},{"t":"подавам звуков сигнал","ok":false,"i":null,"es":"doy una señal acústica"},{"t":"увеличавам скоростта за по-бързо разминаване","ok":false,"i":null,"es":"aumento la velocidad para cruzarnos más rápido"}],"f":6,"es":"¿Cuál de las acciones indicadas realizará en esta situación al cruzarse con el autobús que arranca de la parada? (2 correctas)","explain":""},{"id":5589,"bg":"При тази ситуация, преминавайки покрай спрелия на спирката трамвай:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39270.png","v":null,"a":[{"t":"трябва своевременно да намаля скоростта","ok":true,"i":null,"es":"debo reducir la velocidad a tiempo"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"трябва да внимавам за поведението на пешеходците преминаващи през платното за движение","ok":true,"i":null,"es":"debo estar atento al comportamiento de los peatones que cruzan la calzada"},{"t":"няма опасност от пресичащи пешеходци, защото няма пешеходна пътека","ok":false,"i":null,"es":"no hay peligro de peatones cruzando, porque no hay paso de peatones"}],"f":6,"es":"En esta situación, al pasar junto al tranvía parado en la parada: (3 correctas)","explain":""},{"id":5597,"bg":"При тази ситуация при приближаване към трамвайната спирка:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39435.png","v":null,"a":[{"t":"трябва да спра, когато трамваят е спрял на спирката","ok":true,"i":null,"es":"debo detenerme cuando el tranvía está detenido en la parada"},{"t":"трябва да спра, когато трамваят спира на спирката","ok":true,"i":null,"es":"debo detenerme cuando el tranvía se está deteniendo en la parada"},{"t":"не съм задължен да намаля скоростта, когато трамваят потегля от спирката","ok":false,"i":null,"es":"no estoy obligado a reducir la velocidad cuando el tranvía arranca de la parada"}],"f":6,"es":"En esta situación, al acercarse a la parada de tranvía: (2 correctas)","explain":""},{"id":11622,"bg":"В района на спирка на превозните средства от редовните линии за обществен превоз на пътници, на други превозни средства е разрешено да спират за:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"слизане на пътници, само ако не пречат на превозните средства, за които е предназначена спирката","ok":true,"i":null,"es":"bajada de pasajeros, solo si no interfieren con los vehículos de línea"},{"t":"качване на пътници, ако не пречат на превозните средства, за които е предназначена спирката","ok":false,"i":null,"es":"subida de pasajeros, si no interfieren con los de línea"},{"t":"извършване на товаро-разтоварна дейност","ok":false,"i":null,"es":"carga y descarga de mercancías"}],"f":6,"es":"En la zona de parada del transporte público, otros vehículos solo pueden realizar:","explain":"En la zona de parada del transporte público, otros vehículos solo pueden BAJAR pasajeros, y solo sin estorbar a los de línea. Ni subir pasajeros ni cargar mercancías: la parada es de los autobuses."},{"id":11731,"bg":"В жилищна зона, обозначена със съответния пътен знак, е разрешено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"движение на пешеходците по платното за движение","ok":true,"i":null,"es":"la circulación de peatones por la calzada"},{"t":"на децата да играят на платното за движение","ok":true,"i":null,"es":"que los niños jueguen en la calzada"},{"t":"паркиране извън специално обозначените за това места","ok":false,"i":null,"es":"estacionar fuera de los lugares especialmente señalizados"},{"t":"движение със скорост 40 km/h","ok":false,"i":null,"es":"circular a 40 km/h"}],"f":6,"es":"En una zona residencial señalizada con la señal correspondiente está permitido: (2 correctas)","explain":"En zona residencial señalizada: peatones por la calzada y niños jugando en ella: es espacio compartido (por eso el límite es 20 km/h, nunca 40). Estacionar solo se permite en los lugares señalizados."},{"id":5813,"bg":"При тази ситуация водачът на жълтия автомобил задължен ли е да пропусне автомобила със специален режим на движение?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29294.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"En esta situación, ¿está obligado el conductor del automóvil amarillo a ceder el paso al automóvil con régimen especial de circulación?","explain":""},{"id":5818,"bg":"При приближаване на МПС със специален режим на движение, водачите на останалите превозни средства са длъжни да осигурят безпрепятственото им преминаване, като:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"освободят достатъчно място на пътното платно","ok":true,"i":null,"es":"dejar espacio suficiente en la plataforma vial"},{"t":"при необходимост трябва да спрат","ok":true,"i":null,"es":"si es necesario, deben detenerse"},{"t":"задължително трябва да спрат възможно най-вдясно на пътното платно","ok":false,"i":null,"es":"obligatoriamente deben detenerse lo más a la derecha posible de la plataforma vial"},{"t":"незабавно да спрат в пътната лента, в която се намират","ok":false,"i":null,"es":"detenerse inmediatamente en el carril en el que se encuentran"}],"f":6,"es":"Al acercarse vehículos con régimen especial de circulación, los conductores de los demás vehículos están obligados a facilitar su paso sin obstáculos: (2 correctas)","explain":"Ante un vehículo con régimen especial: deja espacio suficiente y, si hace falta, detente. No hay obligación automática de parar pegado a la derecha ni de frenar en seco en tu carril: la ley pide facilitar el paso con criterio, no pánico."},{"id":6682,"bg":"В кой от изброените случаи е забранено тегленето на повреден автомобил с гъвкава връзка?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато дължината на връзката е по-малка от 4 метра","ok":true,"i":null,"es":"cuando la longitud del enganche es inferior a 4 metros"},{"t":"през нощта","ok":false,"i":null,"es":"de noche"},{"t":"когато водачът му е със стаж до 2 години","ok":false,"i":null,"es":"cuando su conductor tiene menos de 2 años de experiencia"},{"t":"когато масата на теглещото ППС е по-голяма от масата на тегленото ППС","ok":false,"i":null,"es":"cuando la masa del vehículo que remolca es mayor que la del remolcado"}],"f":6,"es":"¿En cuál de los casos indicados está prohibido remolcar un automóvil averiado con enganche flexible?","explain":"Prohibido remolcar con enganche flexible cuando mide menos de 4 m: el remolcado no tendría distancia de reacción y embestiría al que remolca. La noche, la experiencia del conductor o la relación de masas no prohíben la maniobra."},{"id":5551,"bg":"Кой автомобил е спрян правилно за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42266.png","v":null,"a":[{"t":"само червеният автомобил","ok":false,"i":null,"es":"solo el rojo"},{"t":"само синият автомобил","ok":false,"i":null,"es":"solo el azul"},{"t":"и двата автомобила","ok":true,"i":null,"es":"ambos automóviles"}],"f":6,"es":"¿Qué automóvil está correctamente detenido (parada)?","explain":""},{"id":5577,"bg":"При тази ситуация на еднопосочния път, когато и двата автомобила са спрени за престой:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/160614.png","v":null,"a":[{"t":"синият автомобил е спрян правилно, ако това не пречи на движението","ok":true,"i":null,"es":"el automóvil azul está detenido correctamente si no obstaculiza el tráfico"},{"t":"червеният автомобил е спрян правилно, защото за престой се спира от дясната страна на пътя","ok":true,"i":null,"es":"el automóvil rojo está detenido correctamente, porque la parada se hace en el lado derecho de la vía"},{"t":"синият автомобил е спрян неправилно, защото престоят от лявата страна е забранен във всички случаи","ok":false,"i":null,"es":"el automóvil azul está detenido incorrectamente, porque la parada en el lado izquierdo está prohibida en todos los casos"}],"f":6,"es":"En esta situación, en la vía de sentido único, cuando ambos automóviles están detenidos para una parada breve: (2 correctas)","explain":""},{"id":5592,"bg":"Върху платното за движение след този знак е разрешено да спрете за:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43470.png","v":null,"a":[{"t":"слизане на пътник от автомобила","ok":true,"i":null,"es":"la bajada de un pasajero del automóvil"},{"t":"извършване на товарно-разтоварна дейност","ok":true,"i":null,"es":"realizar operaciones de carga y descarga"},{"t":"качване на пътник в автомобила","ok":true,"i":null,"es":"la subida de un pasajero al automóvil"},{"t":"паркиране","ok":false,"i":null,"es":"aparcar"}],"f":6,"es":"En la calzada, después de esta señal, está permitido detenerse para: (3 correctas)","explain":""},{"id":5622,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на места, където превозното средство би закрило пътен знак","ok":true,"i":null,"es":"en lugares donde el vehículo ocultaría una señal de tráfico"},{"t":"на места, където превозното средство би закрило сигнал на светофара","ok":true,"i":null,"es":"en lugares donde el vehículo ocultaría la señal de un semáforo"},{"t":"на улици, по които се движат трамваи","ok":false,"i":null,"es":"en calles por las que circulan tranvías"},{"t":"пред входовете на театри и кина","ok":false,"i":null,"es":"delante de las entradas de teatros y cines"}],"f":6,"es":"La detención (parada) está prohibida: (2 correctas)","explain":"Parada prohibida donde el vehículo ocultaría una señal de tráfico o un semáforo a los demás: dejarías a los otros conductores ciegos ante la regulación. En calles con tranvía y ante teatros lo prohibido es ESTACIONAR, no la parada breve."},{"id":5628,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на място с ограничена видимост","ok":true,"i":null,"es":"en un lugar con visibilidad limitada"},{"t":"върху трамвайна линия","ok":true,"i":null,"es":"sobre vía de tranvía"},{"t":"върху железопътна линия","ok":true,"i":null,"es":"sobre una línea ferroviaria"},{"t":"на неосветен участък от пътя","ok":false,"i":null,"es":"en un tramo de la vía sin iluminación"}],"f":6,"es":"La detención (parada) está prohibida: (3 correctas)","explain":"Parada prohibida: con visibilidad limitada (no te ven a tiempo), sobre vía de tranvía y sobre línea ferroviaria (no pueden esquivarte). La falta de iluminación del tramo no prohíbe la parada."},{"id":5630,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на велосипедна пътека","ok":true,"i":null,"es":"en un carril bici"},{"t":"на разстояние, по-малко от 5 метра преди велосипедна пътека","ok":true,"i":null,"es":"a menos de 5 metros ANTES de un carril bici"},{"t":"на разстояние, по-малко от 5 метра след велосипедна пътека","ok":false,"i":null,"es":"a menos de 5 metros DESPUÉS de un carril bici"}],"f":6,"es":"El aparcamiento está PROHIBIDO: (2 correctas)","explain":"Aparcar prohibido sobre el carril bici y a menos de 5 m ANTES de él: misma lógica que el paso de peatones: no tapar al ciclista donde va a cruzar. Después del carril, permitido."},{"id":5647,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"непосредствено пред входовете на жилищни сгради, когато това затруднява достъпа до тях","ok":true,"i":null,"es":"justo delante de las entradas de edificios de viviendas, cuando dificulta el acceso a ellas"},{"t":"пред входовете на детските заведения и училищата","ok":true,"i":null,"es":"delante de las entradas de guarderías y escuelas"},{"t":"на прилежащите тротоари на детските заведения и училищата","ok":true,"i":null,"es":"en las aceras adyacentes a guarderías y escuelas"},{"t":"пред здравни заведения","ok":false,"i":null,"es":"delante de centros de salud"}],"f":6,"es":"El estacionamiento está prohibido: (3 correctas)","explain":"Prohibido estacionar: ante entradas de viviendas cuando dificulta el acceso, ante entradas de guarderías y escuelas y en sus aceras adyacentes (protección de los niños). Ante centros de salud no hay prohibición general: esa es la trampa."},{"id":5656,"bg":"При спиране за престой преди кръстовище водачът е в нарушение, ако разстоянието от автомобила до кръстовището е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"2 м","ok":true,"i":null,"es":"2 m"},{"t":"4 м","ok":true,"i":null,"es":"4 m"},{"t":"6 м","ok":false,"i":null,"es":"6 m"},{"t":"10 м","ok":false,"i":null,"es":"10 m"}],"f":6,"es":"Al detenerse (parada) antes de una intersección, el conductor comete infracción si la distancia del automóvil a la intersección es: (2 correctas)","explain":"Hay infracción si paras a menos de 5 m de la intersección: 2 m y 4 m incumplen; 6 m y 10 m son legales. La distancia protege la visibilidad de los que giran."},{"id":11629,"bg":"Пътно превозно средство е в престой, когато е спряно за ограничено време:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"за качване на пътници","ok":true,"i":null,"es":"para la subida de pasajeros"},{"t":"за слизане на пътници","ok":true,"i":null,"es":"para la bajada de pasajeros"},{"t":"за извършване на товарно-разтоварни работи в присъствието на водача","ok":true,"i":null,"es":"para operaciones de carga y descarga en presencia del conductor"},{"t":"за изчакване пристигането на пътник","ok":false,"i":null,"es":"para esperar la llegada de un pasajero"}],"f":6,"es":"Un vehículo está en parada cuando está detenido por tiempo limitado: (3 correctas)","explain":"Es 'parada' la detención por tiempo limitado para subir o bajar pasajeros o para carga/descarga CON el conductor presente. Esperar la llegada de alguien no entra en la definición: eso ya es estacionar."},{"id":5679,"bg":"Допълнителни светлини за мъгла се използват само при значително намалена видимост:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"поради мъгла","ok":true,"i":null,"es":"por niebla"},{"t":"поради снеговалеж","ok":true,"i":null,"es":"por nevada"},{"t":"поради дъжд","ok":true,"i":null,"es":"por lluvia"},{"t":"през тъмната част от денонощието","ok":false,"i":null,"es":"durante las horas de oscuridad"}],"f":6,"es":"Las luces antiniebla adicionales se usan solo con visibilidad considerablemente reducida: (3 correctas)","explain":"Las antiniebla se usan solo con visibilidad considerablemente reducida por niebla, nevada o lluvia. La oscuridad de la noche NO es motivo: para eso están las luces normales; las antiniebla de noche despejada deslumbran."},{"id":11633,"bg":"”Дневните светлини” са предназначени:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"за подобряване на възприемането и видимостта на предната част на ППС при движението му","ok":true,"i":null,"es":"para mejorar la percepción y visibilidad de la parte delantera del vehículo en marcha"},{"t":"за обозначаване през деня на паркирано МПС","ok":false,"i":null,"es":"para señalizar de día un vehículo estacionado"},{"t":"за движение по осветен път през нощта","ok":false,"i":null,"es":"para circular de noche por una vía iluminada"},{"t":"за подобряване осветеността на пътя","ok":false,"i":null,"es":"para mejorar la iluminación de la vía"}],"f":6,"es":"Las \"luces diurnas\" están destinadas:","explain":"Las luces diurnas sirven para que el vehículo EN MARCHA se perciba mejor de frente durante el día. No iluminan la vía (son débiles), no señalizan vehículos parados y de noche no bastan: hay que pasar a cortas."},{"id":5725,"bg":"При движение на превозното средство разходът на гориво се увеличава при:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"превозване на предмети върху покрива на автомобила","ok":true,"i":null,"es":"transportar objetos sobre el techo del automóvil"},{"t":"понижено налягане на въздуха в автомобилните гуми","ok":true,"i":null,"es":"presión de aire baja en los neumáticos"},{"t":"по-рядко използване на спирачките","ok":false,"i":null,"es":"usar los frenos con menos frecuencia"},{"t":"рязко увеличаване на скоростта","ok":true,"i":null,"es":"aumentar bruscamente la velocidad"}],"f":6,"es":"Durante la marcha del vehículo, el consumo de combustible aumenta con: (3 correctas)","explain":"El consumo aumenta con: carga en el techo, presión baja de neumáticos Y acelerones bruscos. Usar MENOS los frenos (conducción fluida y anticipada) reduce el consumo: por eso esa opción también es correcta en su formulación."},{"id":6115,"bg":"При управление на автомобил под въздействие на алкохол водачът:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"няма реална преценка за скоростта","ok":true,"i":null,"es":"no tiene una percepción real de la velocidad"},{"t":"забавя реакциите","ok":true,"i":null,"es":"ralentiza las reacciones"},{"t":"има по-бързи реакции","ok":false,"i":null,"es":"tiene reacciones más rápidas"},{"t":"е по-концентриран","ok":false,"i":null,"es":"está más concentrado"}],"f":6,"es":"Al conducir un automóvil bajo los efectos del alcohol, el conductor: (2 correctas)","explain":"El alcohol distorsiona la percepción de la velocidad y RALENTIZA las reacciones: el conductor cree ir bien mientras reacciona tarde. 'Reacciones más rápidas' y 'más concentrado' son exactamente los mitos que el examen quiere desmontar."},{"id":6127,"bg":"Колко често водачът трябва да спира за почивка при продължително пътуване?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"на всеки четири часа","ok":false,"i":null,"es":"cada cuatro horas"},{"t":"достатъчна е почивката при спирането за хранене","ok":false,"i":null,"es":"basta con el descanso de las paradas para comer"},{"t":"винаги когато почувства умора","ok":true,"i":null,"es":"siempre que sienta fatiga"}],"f":6,"es":"¿Con qué frecuencia debe detenerse a descansar el conductor en un viaje prolongado?","explain":"Siempre que sienta fatiga: el cuerpo marca el ritmo, no el reloj. Un intervalo fijo de cuatro horas puede ser demasiado, y las paradas para comer no bastan si el sueño aparece antes."},{"id":6132,"bg":"Какво означава водачът да бъде предвидлив?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да предвижва възможните опасности в пътното движение","ok":true,"i":null,"es":"prever los posibles peligros del tráfico"},{"t":"да взема своевременно мерки, за да не попадне в аварийна ситуация","ok":true,"i":null,"es":"tomar medidas a tiempo para no verse en una situación de emergencia"},{"t":"да поддържа висока средна скорост на движение","ok":false,"i":null,"es":"mantener una velocidad media alta"},{"t":"да управлява винаги с ниска скорост","ok":false,"i":null,"es":"conducir siempre a baja velocidad"}],"f":6,"es":"¿Qué significa que el conductor sea previsor? (2 correctas)","explain":"Ser previsor = anticipar los posibles peligros y tomar medidas A TIEMPO para no llegar a la emergencia. No es una cuestión de velocidad alta ni baja: es leer el tráfico por adelantado."},{"id":6140,"bg":"В коя част от денонощието водачът различава по-добре цветовете?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"през деня","ok":true,"i":null,"es":"durante el día"},{"t":"през нощта на светлината от фарове","ok":false,"i":null,"es":"de noche, a la luz de los faros"},{"t":"при свечеряване","ok":false,"i":null,"es":"al anochecer"},{"t":"през нощта при силно улично осветление","ok":false,"i":null,"es":"de noche, con alumbrado público intenso"}],"f":6,"es":"¿En qué parte del día distingue mejor los colores el conductor?","explain":"De DÍA: la visión del color necesita luz abundante (los conos de la retina). De noche, con faros o farolas, domina la visión en grises: por eso las señales dependen tanto de forma y reflectancia."},{"id":5994,"bg":"Задължение на водача е превозваният товар:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да не закрива огледалата за виждане назад","ok":true,"i":null,"es":"no tape los retrovisores"},{"t":"да не закрива светлинните и сигналните устройства на автомобила","ok":true,"i":null,"es":"no tape los dispositivos de iluminación y señalización"},{"t":"да е укрепен","ok":true,"i":null,"es":"esté asegurada"},{"t":"да е застрахован","ok":false,"i":null,"es":"esté asegurada con seguro"}],"f":6,"es":"El conductor está obligado a que la carga: (3 correctas)","explain":"La carga: no debe tapar retrovisores ni luces/señalización, y debe estar ASEGURADA (sujeta, amarrada). La trampa es 'asegurada con seguro': la palabra búlgara 'застрахован' (póliza) no es un requisito de la carga."},{"id":6003,"bg":"Разрешено ли е да превозвате пътници в туристическо ремарке?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":6,"es":"¿Está permitido transportar pasajeros en un remolque-caravana?","explain":"No: tampoco en remolque-caravana se transportan pasajeros durante la marcha. La caravana no tiene sistemas de retención homologados para personas en movimiento."},{"id":6016,"bg":"Кога водачът е задължен да предостави за проверка документите си за управление на МПС?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"във всички случаи, когато представител на контролните органи поиска това","ok":true,"i":null,"es":"en todos los casos en que un agente de las autoridades de control lo solicite"},{"t":"само когато е допуснал нарушение на правилата за движение","ok":false,"i":null,"es":"solo cuando haya cometido una infracción de las normas de circulación"},{"t":"само при участие в пътнотранспортно произшествие","ok":false,"i":null,"es":"solo si está implicado en un accidente de tráfico"}],"f":6,"es":"¿Cuándo está obligado el conductor a presentar para control sus documentos de conducción?","explain":"Siempre que un agente de control lo solicite: la presentación de documentos no depende de haber cometido infracción ni de estar en un accidente. El control es potestad del agente."},{"id":6021,"bg":"Движещите се по пътя три- и четириколесни моторни превозни средства трябва да бъдат оборудвани:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с аптечка","ok":true,"i":null,"es":"botiquín de primeros auxilios"},{"t":"с пожарогасител","ok":true,"i":null,"es":"con extintor"},{"t":"с въже за теглене","ok":false,"i":null,"es":"con cuerda de remolque"},{"t":"с инструменти за ремонт","ok":false,"i":null,"es":"con herramientas de reparación"}],"f":6,"es":"Los vehículos de motor de tres y cuatro ruedas que circulan por la vía deben estar equipados: (2 correctas)","explain":"También son obligatorios el botiquín y el EXTINTOR. La cuerda de remolque y las herramientas son recomendables pero no exigidos por la norma: esa es la trampa de esta variante."},{"id":5429,"bg":"Извършва ли нарушение водач, който отстъпва управлението на МПС на лице, което не притежава съответното свидетелство за управление?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Comete infracción el conductor que cede la conducción del vehículo a una persona que no posee el permiso de conducción correspondiente?","explain":"Sí: ceder el volante a alguien sin el permiso correspondiente es infracción del que cede, no solo del que conduce. Eres responsable de a quién dejas tu vehículo."},{"id":8292,"bg":"Моторно превозно средство временно се спира от движение когато:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"е технически неизправно","ok":true,"i":null,"es":"tiene deficiencias técnicas"},{"t":"съдържанието на вредни вещества в изгорелите газове са над установените норми","ok":true,"i":null,"es":"el contenido de sustancias nocivas en los gases de escape supera las normas establecidas"},{"t":"е със свалени шумозаглушители","ok":true,"i":null,"es":"lleva los silenciadores desmontados"},{"t":"неговият водач откаже да бъде проверен от контролните органи за наличие на алкохол в кръвта","ok":false,"i":null,"es":"su conductor se niegue a ser sometido por los agentes al control de alcohol en sangre"}],"f":6,"es":"Un vehículo de motor se inmoviliza temporalmente cuando: (3 correctas)","explain":"Se inmoviliza temporalmente el vehículo con deficiencias técnicas, con gases contaminantes sobre la norma o con los silenciadores desmontados: problemas DEL VEHÍCULO. Negarse al control de alcoholemia acarrea sanciones al CONDUCTOR, no la inmovilización por estado técnico: esa es la trampa."},{"id":8294,"bg":"При нарушение, установено и заснето с техническо средство, в отсъствието на контролен орган и на нарушител, издаденият електроннен фиш:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"подлежи на обжалване","ok":true,"i":null,"es":"puede recurrirse"},{"t":"не подлежи на обжалване, когато наложената глоба е до 50 лв. включително","ok":false,"i":null,"es":"no puede recurrirse cuando la multa impuesta es de hasta 50 leva inclusive"},{"t":"подлежи на обжалване, само когато автомобилът е управляван от собственика","ok":false,"i":null,"es":"puede recurrirse solo cuando el automóvil era conducido por el propietario"}],"f":6,"es":"En una infracción detectada y grabada con un dispositivo técnico, en ausencia de agente y de infractor, el boletín electrónico emitido:","explain":"El boletín electrónico (фиш) emitido por infracción grabada sin agente ni infractor presentes PUEDE recurrirse: el derecho al recurso no desaparece por el importe ni por quién conducía."},{"id":11387,"bg":"Счита ли се за връчен фиш за неправилно паркиране, издаден в отсъствието на водача и към МПС е закрепено уведомление за това?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Se considera entregado un boletín por estacionamiento incorrecto, emitido en ausencia del conductor y con una notificación fijada al vehículo?","explain":"Sí: el boletín por estacionamiento incorrecto emitido en ausencia del conductor se considera entregado con la notificación fijada al vehículo. No hace falta entrega en mano."},{"id":5304,"bg":"Поради коя от изброените причини най-често настъпват пътнотранспортни произшествия?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"грешка на водача","ok":true,"i":null,"es":"error del conductor"},{"t":"лоши пътни условия","ok":false,"i":null,"es":"malas condiciones de la vía"},{"t":"неизправност на превозното средство","ok":false,"i":null,"es":"avería del vehículo"},{"t":"неправилно поведение на пешеходците","ok":false,"i":null,"es":"comportamiento incorrecto de los peatones"}],"f":6,"es":"¿Por cuál de las causas indicadas ocurren con más frecuencia los accidentes de tráfico?","explain":"El ERROR DEL CONDUCTOR es la causa más frecuente de accidente, con enorme diferencia sobre vía, vehículo o peatones. El factor humano causa alrededor del 90% de los siniestros."},{"id":5332,"bg":"При ПТП, в което е участник, водачът съобразно необходимостта трябва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да вземе мерки за безопасността на движението","ok":true,"i":null,"es":"tomar medidas para la seguridad del tráfico"},{"t":"да окаже помощ на пострадалите и вземе мерки за превозването им до здравно заведение","ok":true,"i":null,"es":"prestar ayuda a los heridos y tomar medidas para su traslado a un centro de salud"},{"t":"да вземе мерки за запазване на следите от произшествието","ok":true,"i":null,"es":"tomar medidas para conservar las huellas del accidente"},{"t":"да отстрани повредите по автомобила","ok":false,"i":null,"es":"reparar los daños del automóvil"}],"f":6,"es":"En un accidente en el que está implicado, el conductor, según la necesidad, debe: (3 correctas)","explain":"Implicado en accidente, según necesidad: asegurar el tráfico, ayudar a los heridos y organizar su traslado, y conservar las huellas. Reparar los daños del coche es lo único que NO debe hacerse: destruiría la evidencia."},{"id":5333,"bg":"Предприемането на кое от изброените действия е най-важно при пристигане на мястото на ПТП?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да се осигури безопасността на участниците в движението","ok":true,"i":null,"es":"garantizar la seguridad de los usuarios de la vía"},{"t":"да се съобщи за произшествието на полицейските служби","ok":false,"i":null,"es":"comunicar el accidente a los servicios policiales"},{"t":"да се запазят следите от произшествието","ok":false,"i":null,"es":"conservar las huellas del accidente"},{"t":"да се установят участниците в произшествието","ok":false,"i":null,"es":"identificar a los implicados en el accidente"}],"f":6,"es":"¿Cuál de las acciones indicadas es la más importante al llegar al lugar de un accidente?","explain":"Lo primero al llegar a un accidente: garantizar la SEGURIDAD de los usuarios de la vía: evitar el segundo accidente, que suele ser peor. Avisar, conservar huellas e identificar vienen después."},{"id":5338,"bg":"Допускат ли се корекции в двустранния констативен протокол, подписан от участниците в ПТП?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"не, всяка поправка на текста го прави невалиден","ok":true,"i":null,"es":"no, cualquier corrección del texto lo invalida"},{"t":"да, но само в деня на съставянето на протокола","ok":false,"i":null,"es":"sí, pero solo el día en que se redacta el parte"},{"t":"да, но със съгласието на двамата водачи","ok":false,"i":null,"es":"sí, pero con el acuerdo de ambos conductores"}],"f":6,"es":"¿Se admiten correcciones en el parte amistoso firmado por los implicados en el accidente?","explain":"No: cualquier corrección en el parte amistoso firmado lo INVALIDA. Si hay que cambiar algo, se redacta un parte nuevo: la integridad del documento es su garantía."},{"id":5351,"bg":"Когато се уведомява за ПТП с участието на МПС обозначено с опознавателен знак за опасен товар, от най-съществено значение са данните:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"от опознавателния знак за вида на превозвания опасен товар","ok":true,"i":null,"es":"por el distintivo del tipo de mercancía peligrosa transportada"},{"t":"за регистрационния номер на превозното средство","ok":false,"i":null,"es":"de la matrícula del vehículo"},{"t":"за фирмата, чиято собственост е превозното средство","ok":false,"i":null,"es":"de la empresa propietaria del vehículo"}],"f":6,"es":"Al informar de un accidente con un vehículo señalizado con el distintivo de mercancías peligrosas, los datos más esenciales son:","explain":"Lo esencial al informar: el DISTINTIVO del tipo de mercancía peligrosa (los paneles naranjas con códigos): dice a los servicios de emergencia QUÉ sustancia afrontan y cómo actuar. La matrícula o la empresa no salvan vidas."},{"id":5355,"bg":"Кой е единният европейски телефонен номер за спешни и аварийни обаждания?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"112","ok":true,"i":null,"es":"112"},{"t":"144","ok":false,"i":null,"es":"144"},{"t":"160","ok":false,"i":null,"es":"160"},{"t":"196","ok":false,"i":null,"es":"196"}],"f":6,"es":"¿Cuál es el número único europeo de emergencias?","explain":"112: número único europeo de emergencias, gratuito y disponible desde cualquier teléfono. Los otros números del enunciado no son el número europeo."},{"id":11433,"bg":"Водач, който е участник в ПТП, уведомява за произшествието компетентната служба на МВР когато:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"при произшествието има пострадали хора","ok":true,"i":null,"es":"en el accidente hay personas heridas"},{"t":"ПТП е само с имуществени вреди, но между участниците няма съгласие относно обстоятелствата, свързани с него","ok":true,"i":null,"es":"el accidente tiene solo daños materiales, pero los implicados no están de acuerdo sobre sus circunstancias"},{"t":"винаги, независимо от обстоятелствата","ok":false,"i":null,"es":"siempre, independientemente de las circunstancias"}],"f":6,"es":"Un conductor implicado en un accidente avisa del accidente al servicio competente del MVR cuando: (2 correctas)","explain":"Se avisa al MVR: cuando hay heridos (siempre) y cuando, con solo daños materiales, los implicados NO se ponen de acuerdo. Con acuerdo y solo daños, basta el parte amistoso: por eso 'siempre' es falsa."},{"id":11649,"bg":"Когато в ПТП участва превозно средство, обозначено с опознавателен знак за опасен товар, трябва:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да стоим на безопасно разстояние, освен ако се налага да спасим нечий живот","ok":true,"i":null,"es":"mantenernos a distancia segura, salvo que haya que salvar la vida de alguien"},{"t":"да преместим това превозно средство извън платното за движение","ok":false,"i":null,"es":"apartar ese vehículo fuera de la calzada"},{"t":"да отстраним опасния товар от пътя","ok":false,"i":null,"es":"retirar la carga peligrosa de la vía"},{"t":"да покрием товара с подходящо покривало","ok":false,"i":null,"es":"cubrir la carga con una lona adecuada"}],"f":6,"es":"Cuando en un accidente participa un vehículo señalizado con el distintivo de mercancías peligrosas, hay que:","explain":"Con mercancías peligrosas: distancia segura salvo para salvar una vida. Mover el vehículo, retirar la carga o taparla con una lona son intervenciones de especialistas: un derrame químico no se improvisa."},{"id":9822,"bg":"Кой от пътните знаци предупреждава за стеснение на платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"269866899"},{"t":"","ok":false,"es":"","i":"269866898"},{"t":"","ok":false,"es":"","i":"269866897"},{"t":"","ok":true,"es":"","i":"269866896"}],"f":6,"es":"¿Cuál de las señales advierte de estrechamiento de la calzada?","explain":"El triangulo con las flechas que se juntan indica estrechamiento. Fijate en cual de los lados pierde espacio."},{"id":6194,"bg":"На кой от пътните знаци значението е “Преминаване отдясно на знака”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334697.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45433.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45469.png","es":""}],"f":6,"es":"¿En cuál de las señales el significado es 'Paso por la derecha de la señal'?","explain":"La senal de paso obligatorio por la derecha del poste obliga a pasar a ese lado. Tipica en medianas e islas de trafico."},{"id":5254,"bg":"Кой от пътните знаци предупреждава за стръмен наклон при спускане?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21368.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21369.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334666.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21371.png","es":""}],"f":6,"es":"¿Cuál de las señales advierte de pendiente pronunciada en bajada?","explain":"La pendiente en bajada (flecha hacia abajo con porcentaje) advierte de frenos sobrecalentados. Usa el freno motor."},{"id":5483,"bg":"При светване на кой контролен индикатор от арматулното табло има опасност от сериозна повреда в двигателя, ако не преустановите движението?","p":1,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334685.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334684.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334683.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/30014.png","es":""}],"f":6,"es":"¿Con el encendido de qué indicador del cuadro de instrumentos existe peligro de avería grave del motor si no detiene la marcha?","explain":""},{"id":5327,"bg":"Кое от показаните превозни средства е автомобил?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128965.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128966.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128967.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128968.png","es":""}],"f":6,"es":"¿Cuál de los vehículos mostrados es un automóvil? (3 correctas)","explain":"Automovil = vehiculo de motor para transporte de personas o mercancias, de 4+ ruedas, masa maxima hasta 3500 kg para cat. B."},{"id":9841,"bg":"На кой от пътните знаци значението е “Преминаване в платното за насрещно движение”?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043309.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043310.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043311.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043312.png","es":""}],"f":6,"es":"¿En cuál de las señales el significado es 'Circulación por el carril contrario'?","explain":"La senal de adelantamiento obligatorio por la izquierda se usa cuando hay obstaculos por la derecha."},{"id":6586,"bg":"След кой от тези знаци, при преминаване през кръстовището, превозното средство от другия път трябва да ви пропусне?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55245.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55246.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55247.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55248.png","es":""}],"f":6,"es":"¿Después de cuál de estas señales, al cruzar la intersección, el vehículo del otro camino debe cederte el paso? (2 correctas)","explain":"La senal de via con prioridad (rombo amarillo) te da preferencia de paso en la interseccion."},{"id":6185,"bg":"Кой от пътните знаци указва задължителна посока за движение на превозните средства?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43011.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43012.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43013.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43014.png","es":""}],"f":6,"es":"¿Cuál de las señales indica dirección de circulación obligatoria?","explain":"Las senales de direccion obligatoria son circulos azules con flechas blancas. Obligatorio seguir esa direccion."},{"id":5270,"bg":"Кой от пътните знаци предупреждава за приближаване към кръстовище?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334675.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21411.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25516.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25590.png","es":""}],"f":6,"es":"¿Cuál de las señales advierte de la proximidad de una intersección?","explain":"Las senales de advertencia de interseccion son triangulos. Hay variantes segun el tipo de cruce."},{"id":6282,"bg":"Кой знак предупреждава за конкретна опасност?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55703.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334695.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55705.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/55706.png","es":""}],"f":6,"es":"¿Qué señal advierte de un peligro concreto?","explain":"Las senales de advertencia son triangulos rojos. Las de peligro especifico suelen tener simbolos dentro."},{"id":5513,"bg":"С кой от опознавателните знаци се обозначава полуремаркетата?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23496.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23497.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334739.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/23499.png","es":""}],"f":6,"es":"¿Con cuál de los signos distintivos se identifican los semirremolques? (2 correctas)","explain":"El semirremolque (poluremarke) lleva placa identificativa especial diferente al remolque normal."},{"id":5246,"bg":"Кой от пътните знаци предупреждава, че ще навлезете в опасен завой?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"21036"},{"t":"","ok":false,"es":"","i":"21056"},{"t":"","ok":true,"es":"","i":"21013"},{"t":"","ok":false,"es":"","i":"21035"}],"f":6,"es":"¿Cuál de las señales advierte de que entras en una curva peligrosa?","explain":"Las curvas peligrosas se senalizan con triangulos que muestran la curva. La flecha indica la direction del giro."},{"id":13509,"bg":"При тази ситуация трябва да пропусна пешеходеца.","p":3,"s":"Раздел 4","i":"1382984687","v":null,"a":[{"t":"неправилно","ok":false,"es":"INCORRECTO"},{"t":"правилно","ok":true,"es":"correcto"}],"f":6,"es":"En esta situación debo ceder el paso al peatón. Esto es:","explain":"TRAMPA de verdadero/falso. En un paso de peatones el conductor SIEMPRE debe ceder, independientemente de las circunstancias."},{"id":5245,"bg":"Кой от пътните знаци предупреждава, че ще навлезете в опасен завой?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21014.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21015.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/83151.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21035.png","es":""}],"f":6,"es":"¿Cuál de las señales advierte de que entras en una curva peligrosa? (2 correctas)","explain":"Las curvas peligrosas se senalizan con triangulos que muestran la curva. La flecha indica la direction del giro."},{"id":6044,"bg":"Когато се подава с ръка, сигналът за отклоняване вдясно е:","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27665.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27666.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27667.png","es":""}],"f":6,"es":"Cuando se da con el brazo, la señal para desviarse a la derecha es:","explain":"El brazo extendido horizontalmente hacia la derecha indica giro o cambio de carril a la derecha."},{"id":6166,"bg":"Индикаторът на електронната стабилизираща система (ESP) на арматурното табло светва за определено време, когато:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"се активира системата","ok":true,"i":null,"es":"el sistema se activa"},{"t":"системата е повредена","ok":false,"i":null,"es":"el sistema está averiado"},{"t":"автомобилът е спрян","ok":false,"i":null,"es":"el automóvil está detenido"}],"f":5,"es":"El indicador del sistema electrónico de estabilidad (ESP) del cuadro se enciende durante un tiempo determinado cuando:","explain":"El testigo del ESP se enciende un momento cuando el sistema SE ACTIVA (está corrigiendo una pérdida de adherencia en ese instante). Si quedara fijo indicaría avería: el parpadeo temporal es funcionamiento, no fallo."},{"id":5471,"bg":"Светването на този символ върху арматурното табло означава, че:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334683.png","v":null,"a":[{"t":"не се зарежда акумулаторната батерия","ok":true,"i":null,"es":"la batería no se carga"},{"t":"не работи осветлението","ok":false,"i":null,"es":"el alumbrado no funciona"},{"t":"има повреда в запалителната уредба","ok":false,"i":null,"es":"hay una avería en el sistema de encendido"},{"t":"задължително трябва да се подмени акумулаторната батерия","ok":false,"i":null,"es":"es obligatorio sustituir la batería"}],"f":5,"es":"El encendido de este símbolo en el cuadro de instrumentos significa que:","explain":""},{"id":5474,"bg":"При светването на този символ върху арматурното табло, има опасност от блокиране на двигателя:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334684.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":5,"es":"Con el encendido de este símbolo en el cuadro de instrumentos existe peligro de que el motor se gripe. Esto es:","explain":""},{"id":5477,"bg":"Какво трябва да предприеме водачът, когато върху арматурното табло свети този символ?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334684.png","v":null,"a":[{"t":"да спре на подходящо място","ok":true,"i":null,"es":"detenerse en un lugar adecuado"},{"t":"да изгаси двигателя","ok":true,"i":null,"es":"apagar el motor"},{"t":"да продължи движението, но на по-ниска предавка","ok":false,"i":null,"es":"continuar la marcha, pero en una marcha más corta"},{"t":"да продължи движението, но с по-високи обороти на двигателя","ok":false,"i":null,"es":"continuar la marcha, pero con el motor a más revoluciones"}],"f":5,"es":"¿Qué debe hacer el conductor cuando en el cuadro de instrumentos se enciende este símbolo? (2 correctas)","explain":""},{"id":5437,"bg":"Използването на вода като охладителна течност в охладителната уредба на МПС в зимни условия:","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"не се препоръчва, защото при температура под нула градуса водата замръзва","ok":true,"i":null,"es":"no se recomienda, porque a temperaturas bajo cero el agua se congela"},{"t":"не се използва, защото при кипене водата се изпарява","ok":false,"i":null,"es":"no se usa, porque al hervir el agua se evapora"},{"t":"не се използва, защото водата причинява корозия на охладителната уредба","ok":false,"i":null,"es":"no se usa, porque el agua causa corrosión en el sistema de refrigeración"},{"t":"е забранено","ok":false,"i":null,"es":"está prohibido"}],"f":5,"es":"El uso de agua como líquido refrigerante en el sistema de refrigeración del vehículo en condiciones invernales:","explain":"El agua no se recomienda en invierno porque SE CONGELA bajo cero: al congelarse se expande y revienta el bloque y los conductos. El anticongelante existe exactamente para eso."},{"id":5182,"bg":"Трамваят е релсово превозно средство, което се приравнява към групата на моторните превозни средства.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"El tranvia es un vehículo de carretera ferroviario que se equipara al grupo de los vehículos de motor.","explain":"INCORRECTO: el tranvía se equipara a los VEHÍCULOS (ППС), no a los vehículos de motor (МПС). Es la distinción legal clásica: circula por raíles y tiene su propio régimen."},{"id":5234,"bg":"“Граница на платното за движение” е линията:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"с която се очертава “ВUS”-лентата","ok":true,"i":null,"es":"con la que se delimita el carril BUS"},{"t":"с която се очертава края на платното за движение","ok":true,"i":null,"es":"con la que se delimita el borde de la calzada"},{"t":"с която се очертават островите на платното за движение","ok":true,"i":null,"es":"con la que se delimitan las isletas de la calzada"},{"t":"с която се отделят пътните ленти","ok":false,"i":null,"es":"con la que se separan los carriles"}],"f":5,"es":"'Límite de calzada' es la línea: (3 correctas)","explain":"La línea de límite (ограничителна линия) delimita el borde de la calzada, las isletas y el carril BUS. Lo que NO hace es separar los carriles normales entre sí: para eso están las líneas divisorias discontinuas o continuas."},{"id":5315,"bg":"Видимостта е ограничена при:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"препятствия, които пречат на видимостта","ok":true,"i":null,"es":"obstáculos que impiden la visibilidad"},{"t":"крайпътни обекти, които ограничават видимостта","ok":true,"i":null,"es":"objetos junto a la vía que limitan la visibilidad"},{"t":"проливен дъжд","ok":false,"i":null,"es":"lluvia torrencial"},{"t":"силен снеговалеж","ok":false,"i":null,"es":"nevada intensa"}],"f":5,"es":"La visibilidad esta limitada en: (2 correctas)","explain":"Visibilidad LIMITADA: la que restringen obstáculos u objetos junto a la vía (y la geometría: curvas, rasantes). La lluvia torrencial y la nevada producen visibilidad REDUCIDA: fenómeno atmosférico, no físico-geométrico. El examen vive de esta distinción."},{"id":8246,"bg":"Триколесно МПС задвижвано от електродвигател, с конструктивна максимална скорост не по-висока от 45 km/h, се управлява с правоспособност за категория АМ ако максималната постоянна номинална мощност на двигателя е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"не повече от 3 kW","ok":false,"i":null,"es":"no más de 3 kW"},{"t":"не повече от 4 kW","ok":true,"i":null,"es":"no más de 4 kW"},{"t":"не повече от 5 kW","ok":false,"i":null,"es":"no más de 5 kW"},{"t":"не повече от 6 kW","ok":false,"i":null,"es":"no más de 6 kW"}],"f":5,"es":"Un triciclo de motor eléctrico con velocidad máxima constructiva de hasta 45 km/h se conduce con categoría AM si la potencia nominal continua máxima del motor es:","explain":"4 kW: un triciclo eléctrico de hasta 45 km/h se conduce con categoría AM solo si su potencia nominal continua no supera los 4 kW. Con más potencia deja de ser asimilable a ciclomotor."},{"id":11903,"bg":"Участници в движението са:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"водачите","ok":true,"i":null,"es":"los conductores"},{"t":"автомобилите","ok":false,"i":null,"es":"los automóviles"},{"t":"пешеходците","ok":true,"i":null,"es":"los peatones"},{"t":"лицата, работещи на пътя","ok":true,"i":null,"es":"las personas que trabajan en la vía"}],"f":5,"es":"Son participantes en el tráfico: (3 correctas)","explain":"Participantes en el tráfico son PERSONAS: conductores, peatones y quienes trabajan en la vía. Los automóviles son objetos (vehículos), no participantes: es la trampa de definición."},{"id":12072,"bg":"Трамваите се приравняват към:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"пътните превозни средства","ok":true,"i":null,"es":"los vehículos"},{"t":"моторните превозни средства","ok":false,"i":null,"es":"los vehículos de motor"},{"t":"автомобилите със специално предназначение","ok":false,"i":null,"es":"los vehículos especiales"},{"t":"тролейбусите","ok":false,"i":null,"es":"los trolebuses"}],"f":5,"es":"Los tranvías están equiparados a:","explain":"Los tranvías se equiparan a los VEHÍCULOS (ППС) en general: circulan por vía férrea, no son 'vehículos de motor' (МПС) a efectos de la ley ni vehículos especiales."},{"id":5194,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334667.png","v":null,"a":[{"t":"опасен пътен банкет","ok":true,"i":null,"es":"arcén peligroso"},{"t":"хлъзгав участък от пътя","ok":false,"i":null,"es":"tramo de vía deslizante"},{"t":"неравности по пътя","ok":false,"i":null,"es":"irregularidades (baches) en la vía"},{"t":"начин на паркиране","ok":false,"i":null,"es":"modo de estacionamiento"}],"f":5,"es":"Esta señal advierte de:","explain":"Arcen peligroso (banket) = el borde de la carretera es inestable o tiene desnivel. Peligro si las ruedas salen de la calzada."},{"id":5207,"bg":"При тази ситуация, жълтозеленият флуоресцентен светлоотразителен фон, върху който е поставен пътният знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22896.png","v":null,"a":[{"t":"сигнализира, че пътният участък е с концентрация на пътнотранспортни произшествия","ok":true,"i":null,"es":"señaliza que el tramo tiene concentración de accidentes de tráfico"},{"t":"указва, че е забранено и изпреварването","ok":false,"i":null,"es":"indica que también está prohibido el adelantamiento"},{"t":"указва, че ограничението на скоростта се спазва само при движение в завой","ok":false,"i":null,"es":"indica que el límite de velocidad se aplica solo al circular en la curva"},{"t":"указва, че следва участък от пътя в ремонт","ok":false,"i":null,"es":"indica que sigue un tramo de vía en obras"}],"f":5,"es":"En esta situación, el fondo fluorescente amarillo-verde sobre el que está colocada la señal:","explain":"El fondo reflectante amarillo-verde indica punto negro (concentracion de accidentes). Maxima precaucion en ese tramo."},{"id":5264,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334675.png","v":null,"a":[{"t":"предупреждава за кръстовище, на което се пресичат равнозначни пътища","ok":true,"i":null,"es":"advierte de una intersección de vías de igual rango"},{"t":"указва началото на участък от пътя, в който е забранено навлизането","ok":false,"i":null,"es":"indica el inicio de un tramo de vía donde está prohibida la entrada"},{"t":"сигнализира участък от пътя, по който са забранени престоят и паркирането","ok":false,"i":null,"es":"señaliza un tramo de vía donde están prohibidas la parada y el estacionamiento"},{"t":"сигнализира за край на пътя с предимство","ok":false,"i":null,"es":"señaliza el fin de la vía con prioridad"}],"f":5,"es":"Esta señal:","explain":"Advierte de una INTERSECCIÓN DE VÍAS DE IGUAL RANGO — «кръстовище на равнозначни пътища».\n\nLA SEÑAL. Triángulo rojo con un aspa negra, una X. Es la misma que ya viste en la pregunta 6675, preguntada allí por su efecto y aquí por su nombre.\n\nPOR QUÉ EL ASPA NO LLEVA TRAZO GRUESO. En los triángulos de cruce, el grosor marca la jerarquía: grueso es la vía con prioridad, fino la secundaria. Aquí no hay grueso porque no hay jerarquía — ninguna de las dos vías manda.\n\nQUÉ IMPLICA PARA TI. Después de esta señal se aplica la regla general del чл. 50, ал. 1: cedes a los vehículos que se te acercan por la DERECHA.\n\n«PROHIBIDA LA ENTRADA» y «PROHIBIDAS LA PARADA Y EL ESTACIONAMIENTO» son círculos rojos: prohibiciones, no avisos. La forma ya las descarta.\n\n«FIN DE LA VÍA CON PRIORIDAD» es un rombo amarillo tachado, tampoco un triángulo.\n\nCLAVE: es la única señal de la familia de cruces que te devuelve a la regla de la derecha. Las otras del grupo llevan trazo grueso y significan lo contrario.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5277,"bg":"Когато в близост няма пешеходна пътека, на пешеходците е разрешено да пресичат платното за движение извън определените за това места:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"по пътища извън населените места","ok":true,"i":null,"es":"en vías fuera de poblado"},{"t":"по двулентовите двупосочни пътища в населените места","ok":true,"i":null,"es":"en vías de dos carriles y doble sentido dentro de poblado"},{"t":"на пътните възли на автомагистралите","ok":false,"i":null,"es":"en los enlaces de las autopistas"},{"t":"по всички пътища отворени за обществено ползване","ok":false,"i":null,"es":"en todas las vías abiertas al uso público"}],"f":5,"es":"Cuando no hay paso de peatones cercano, los peatones pueden cruzar fuera de los pasos en: (2 correctas)","explain":"Fuera de los pasos se puede cruzar: en vías fuera de poblado y, dentro de poblado, en vías de dos carriles y doble sentido (cuando no hay paso cercano). Nunca en enlaces de autopista ni 'en todas las vías': esas generalizaciones son falsas."},{"id":9855,"bg":"При тази ситуация пешеходецът пресича платното за движение по пешеходна пътека.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044518.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":5,"es":"En esta situación el peatón cruza la calzada por un paso de peatones. Esto es:","explain":"CORRECTO. Cruzar por el paso de peatones es siempre lo correcto, el conductor debe ceder."},{"id":11602,"bg":"Този пътен знак сигнализира:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123577637.png","v":null,"a":[{"t":"за използването на пътя се изисква платена ТОЛ такса","ok":true,"i":null,"es":"para usar la vía se exige el pago de peaje (TOL)"},{"t":"двупосочно движение след знака","ok":false,"i":null,"es":"circulación en ambos sentidos después de la señal"},{"t":"движение само направо след знака","ok":false,"i":null,"es":"solo ir recto después"},{"t":"броя на пътните ленти за движение в една посока","ok":false,"i":null,"es":"el número de carriles de circulación en un sentido"}],"f":5,"es":"Esta señal señaliza:","explain":"Peaje TOL (pago electronico por uso). Diferente de la vineta (pago anticipado)."},{"id":11605,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123579826.png","v":null,"a":[{"t":"намалена видимост","ok":false,"i":null,"es":"visibilidad reducida"},{"t":"настъпило пътнотранспортно произшествие","ok":false,"i":null,"es":"accidente de tráfico ocurrido"},{"t":"възможна е поява на силен страничен вятър","ok":false,"i":null,"es":"posible viento lateral fuerte"},{"t":"образувано задръстване","ok":true,"i":null,"es":"retención formada"}],"f":5,"es":"Esta señal advierte de:","explain":"Retencion de trafico formada. Reduce velocidad progresivamente y no adelantes."},{"id":5383,"bg":"При приближаване към този автобус, водачът трябва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/22878.png","v":null,"a":[{"t":"да осигури безопасността на децата","ok":true,"i":null,"es":"garantizar la seguridad de los niños"},{"t":"при необходимост да спре","ok":true,"i":null,"es":"detenerse si es necesario"},{"t":"да подаде звуков сигнал, преди да премине покрай автобуса","ok":false,"i":null,"es":"dar una señal acústica antes de pasar junto al autobús"},{"t":"да премине по-бързо покрай автобуса","ok":false,"i":null,"es":"pasar más rápido junto al autobús"}],"f":5,"es":"Al acercarse a este autobús, el conductor debe: (2 correctas)","explain":"Autobus escolar = maxima precaucion, parar si es necesario para garantizar la seguridad de los ninos. NO tocar el claxon."},{"id":5538,"bg":"Пътното превозно средство е извънгабаритно когато:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височината му, включително товара, е 4,2 м","ok":true,"i":null,"es":"su ALTURA, incluyendo carga, es 4.2 m"},{"t":"широчината му, включително товара, е 2,2 м","ok":false,"i":null,"es":"su ANCHURA, incluyendo carga, es 2.2 m"},{"t":"дължината му, включително товара, е 12 м","ok":false,"i":null,"es":"su LONGITUD, incluyendo carga, es 12 m"}],"f":5,"es":"Un vehículo es 'fuera de gálibo' cuando:","explain":"El límite de altura es 4 m, así que 4,2 m ya es fuera de gálibo. La anchura de 2,2 m no supera los 2,55 m permitidos y la longitud de 12 m tampoco excede el límite."},{"id":5778,"bg":"При тази ситуация трябва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24570.png","v":null,"a":[{"t":"да управлявам с готовност за спиране","ok":true,"i":null,"es":"circular listo para frenar"},{"t":"да бъда внимателен към поведението на велосипедистите","ok":true,"i":null,"es":"estar atento al comportamiento de los ciclistas"},{"t":"да подам звуков сигнал за да привлека вниманието на велосипедистите","ok":false,"i":null,"es":"dar una señal acústica para llamar la atención de los ciclistas"}],"f":5,"es":"En esta situación debes: (2 correctas)","explain":"Con ciclistas: siempre reduce velocidad Y atiende su comportamiento. El claxon no es una solucion."},{"id":6042,"bg":"Водачът на ППС е задължен да подаде сигнал към останалите участници в движението:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"преди да завие в кръстовище","ok":true,"i":null,"es":"antes de girar en una intersección"},{"t":"преди да започне маневра, свързана с отклонение встрани","ok":true,"i":null,"es":"antes de iniciar una maniobra que implique desviarse lateralmente"},{"t":"преди да се включи в движението","ok":true,"i":null,"es":"antes de incorporarse al tráfico"},{"t":"преди рязко намаляване на скоростта","ok":false,"i":null,"es":"antes de reducir bruscamente la velocidad"}],"f":5,"es":"El conductor de un vehículo está obligado a dar señal a los otros participantes en el tráfico: (3 correctas)","explain":"Se señaliza antes de: girar en intersección, cualquier maniobra con desplazamiento lateral e incorporarse al tráfico. La reducción brusca de velocidad no se anuncia con intermitente: se anuncia sola con las luces de freno."},{"id":6053,"bg":"Кога при движение в населено място е разрешено да се използва звуков сигнал?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"само в случаите за предотвратяване на ПТП","ok":true,"i":null,"es":"solo en los casos necesarios para evitar un accidente de tráfico"},{"t":"при приближаване към пешеходна пътека, по която се движат пешеходци","ok":false,"i":null,"es":"al acercarse a un paso de peatones por el que cruzan peatones"},{"t":"винаги","ok":false,"i":null,"es":"siempre"}],"f":5,"es":"¿Cuándo está permitido usar el claxon en población?","explain":"En población el claxon solo se usa para evitar un accidente inminente: es la única excepción legal. Usarlo ante un paso con peatones cruzando o 'siempre' es infracción y además intimida a quien tiene la prioridad."},{"id":12004,"bg":"Какво трябва да направите в тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":5,"a":[{"t":"подавам звуков сигнал на велосипедиста, за да ме пропусне","ok":false,"i":null,"es":"doy señal acústica al ciclista para que me deje pasar"},{"t":"изпреварвам велосипедиста","ok":false,"i":null,"es":"adelanto al ciclista"},{"t":"продължавам движението си зад велосипедиста","ok":true,"i":null,"es":"continúo circulando detrás del ciclista"}],"f":5,"es":"¿Qué debes hacer en esta situación?","explain":"Un ciclista circula delante de mí en zona de intersección urbana con tráfico de frente: lo correcto es CONTINUAR detrás de él hasta que exista espacio seguro. El claxon para 'apartarlo' es un uso prohibido de la señal acústica (el ciclista tiene su derecho a la vía), y adelantar aquí — cruce + tráfico en sentido contrario — no permite la separación lateral obligatoria. Paciencia: el ciclista no es un obstáculo, es tráfico."},{"id":12020,"bg":"При тази ситуация трябва да намалите скоростта с готовност за спиране заради:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":2,"a":[{"t":"белия автомобил, паркиран от дясната страна","ok":false,"i":null,"es":"el coche blanco aparcado a la derecha"},{"t":"детето","ok":true,"i":null,"es":"el niño"},{"t":"мотоциклета","ok":false,"i":null,"es":"la moto"}],"f":5,"es":"En esta situación debes reducir la velocidad con disposición de frenar por:","explain":"Un coche blanco aparcado a la derecha y un NIÑO en esa zona: el niño puede saltar a la calzada oculto por el coche estacionado, sin mirar — reduzco con el pie preparado sobre el freno POR EL NIÑO. El coche blanco en sí no hace nada (está aparcado) y la moto no corta mi trayectoria: distractores. Con niños cerca de vehículos aparcados, asume siempre que aparecerán por el hueco menos visible."},{"id":12025,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":9,"a":[{"t":"продължавам движението си, без да променям скоростта","ok":false,"i":null,"es":"continúo sin cambiar velocidad"},{"t":"преминавам наляво","ok":false,"i":null,"es":"giro a la izquierda"},{"t":"намалявам скоростта и при необходимост спирам","ok":true,"i":null,"es":"reduzco velocidad y si es necesario paro"}],"f":5,"es":"¿Cuál es la actuación correcta en esta situación?","explain":"Reduce velocidad y para si es necesario. Ante cualquier incertidumbre, la respuesta correcta es reducir."},{"id":12074,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1173451119.png","v":null,"a":[{"t":"МПС, превозващи опасни товари","ok":true,"i":null,"es":"vehículos que transportan mercancías peligrosas"},{"t":"бавнодвижещи се МПС","ok":false,"i":null,"es":"vehículos lentos"},{"t":"МПС с извънгабаритен товар","ok":false,"i":null,"es":"vehículos de motor con carga de dimensiones excepcionales"},{"t":"автомобилите със специално предназначение","ok":false,"i":null,"es":"los vehículos especiales"}],"f":5,"es":"Con este signo distintivo se identifican:","explain":"Vehículos que transportan MERCANCÍAS PELIGROSAS — «МПС, превозващи опасни товари».\n\nQUÉ VES. La placa rectangular NARANJA con dos números separados por una línea horizontal. Es el panel naranja del transporte de mercancías peligrosas.\n\nQUÉ SIGNIFICAN LOS NÚMEROS. El de arriba identifica el tipo de peligro; el de abajo identifica la sustancia concreta. No hace falta memorizarlos: lo que el examen pide es reconocer que la placa naranja significa mercancía peligrosa.\n\nQUÉ HACER AL VERLA. Aumentar la distancia de seguridad, no adelantar sin espacio de sobra y, en caso de accidente, alejarse y avisar indicando esos números — son los que permiten a los bomberos saber a qué se enfrentan antes de llegar.\n\n«VEHÍCULOS LENTOS» llevan el triángulo rojo con borde, no una placa naranja.\n\n«CARGA DE DIMENSIONES EXCEPCIONALES» se señaliza con paneles a rayas rojas y blancas.\n\n«VEHÍCULOS ESPECIALES» no es una categoría con distintivo propio.\n\nCLAVE: naranja rectangular con dos números = mercancía peligrosa. Es el único distintivo de ese color y no se parece a ningún otro.\n\nMÉTODO DE SEÑALES: la FORMA y el COLOR dicen el tipo antes de mirar el dibujo. Triángulo rojo = peligro (avisa, no obliga). Círculo rojo = prohibición. Círculo azul = obligación. Cuadrado azul = información o indicación. Rombo amarillo = prioridad. Fondo amarillo = señalización temporal, y manda sobre la fija. Desarrollado en Leyes → «Señales verticales: leer la forma antes que el dibujo»."},{"id":5936,"bg":"Този пътен знак предупреждава:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41210.png","v":null,"a":[{"t":"за приближаване към подвижен мост","ok":true,"i":null,"es":"de la proximidad de un PUENTE MÓVIL"},{"t":"за приближаване към повреден мост","ok":false,"i":null,"es":"de la proximidad de un puente dañado"},{"t":"че пътят води до кей или бряг","ok":false,"i":null,"es":"que el camino lleva a un muelle o ribera"},{"t":"че пътят е затворен за движение","ok":false,"i":null,"es":"que la vía está cerrada"}],"f":5,"es":"Esta señal advierte:"},{"id":5962,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/46532.png","v":null,"a":[{"t":"забранява влизането на ППС срещу него","ok":true,"i":null,"es":"prohíbe la entrada de vehículos en su sentido"},{"t":"забранява влизането само на леки автомобили срещу знака","ok":false,"i":null,"es":"prohíbe la entrada solo de turismos en el sentido de la señal"},{"t":"разрешава влизането на мотоциклетисти срещу знака","ok":false,"i":null,"es":"permite la entrada de motociclistas en el sentido de la señal"},{"t":"указва, че пътят е без изход","ok":false,"i":null,"es":"indica que la vía no tiene salida (calle sin salida)"}],"f":5,"es":"Esta señal:","explain":"Prohibicion de entrada en sentido contrario (calle de sentido unico). Los motocicletas sin sidecar Y ciclomotores a veces pueden entrar segun tablilla adicional."},{"id":5973,"bg":"Този пътен знак забранява влизането:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334705.png","v":null,"a":[{"t":"на МПС, с изключение на мотоциклети без кош и мотопеди","ok":true,"i":null,"es":"de vehículos a motor excepto motos sin sidecar y ciclomotores"},{"t":"на всички МПС","ok":false,"i":null,"es":"a todos los vehículos de motor"},{"t":"само на леки автомобили","ok":false,"i":null,"es":"solo de turismos"},{"t":"на всички ППС","ok":false,"i":null,"es":"de todos los vehículos"}],"f":5,"es":"Esta señal prohíbe la entrada:","explain":"A todos los vehiculos de motor excepto motocicletas sin sidecar y ciclomotores - segun configuracion. Verifica la tablilla adicional."},{"id":6186,"bg":"Този пътен знак:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334694.png","v":null,"a":[{"t":"задължава водачите да се движат само направо след знака","ok":true,"i":null,"es":"obliga a circular solo RECTO después de la señal"},{"t":"сигнализира за еднопосочно движение след знака","ok":false,"i":null,"es":"señaliza tráfico de sentido único después"},{"t":"указва посоката на пътя с предимство","ok":false,"i":null,"es":"indica la dirección de la vía preferente"},{"t":"препоръчва на водачите да се движат направо след знака","ok":false,"i":null,"es":"recomienda ir recto"}],"f":5,"es":"Esta señal:"},{"id":6263,"bg":"Допълнителната табела към пътния знак указва:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54814.png","v":null,"a":[{"t":"начало на участъка, в който е забранено паркирането","ok":true,"i":null,"es":"INICIO del tramo donde está prohibido aparcar"},{"t":"край на участъка, в който е забранено паркирането","ok":false,"i":null,"es":"FIN del tramo donde está prohibido aparcar"}],"f":5,"es":"La tablilla complementaria junto a la señal indica:"},{"id":6300,"bg":"При тази ситуация забраната за движение със скорост, по-висока от означената, е валидна:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56929.png","v":null,"a":[{"t":"до края на опасността, сигнализирана с предупредителния пътен знак","ok":true,"i":null,"es":"hasta el final del peligro señalizado por la señal de advertencia"},{"t":"до знак, който отменя забраната","ok":false,"i":null,"es":"hasta la señal que cancela la prohibición"},{"t":"до следващото кръстовище","ok":false,"i":null,"es":"hasta la próxima intersección"},{"t":"на 50м след знака","ok":false,"i":null,"es":"a 50 m después de la señal"}],"f":5,"es":"En esta situación la prohibición de circular a velocidad superior a la indicada es válida:","explain":"Hasta el final del peligro senalizado por la senal de advertencia previa. No hasta el proximo cruce."},{"id":5895,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40074.png","v":null,"a":[{"t":"„Забранено е преминаването направо или завиването надясно”","ok":true,"i":null,"es":"'Prohibido continuar recto o girar a la derecha'"},{"t":"„Забранено е навлизането в кръстовището за всички участници в движението”","ok":false,"i":null,"es":"'Prohibida la entrada para todos los participantes'"},{"t":"„Забранено е преминаването, освен на ППС, преминаващи направо или завиващи надясно”","ok":false,"i":null,"es":"'Prohibido pasar excepto los que van recto o giran a la derecha'"}],"f":5,"es":"El significado de esta señal de semáforo es:"},{"id":6087,"bg":"При тази ситуация, на път извън населено място, на водачите е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/140619.png","v":null,"a":[{"t":"да се движат в най-дясната свободна пътна лента","ok":true,"i":null,"es":"circular por el carril libre situado más a la derecha"},{"t":"да се движат в средната пътна лента, когато дясната е заета","ok":true,"i":null,"es":"circular en el carril central cuando el derecho está ocupado"},{"t":"да навлизат в средната лента при изпреварване","ok":true,"i":null,"es":"entrar en el carril central para adelantar"},{"t":"да навлизат в крайната лява лента при изпреварване","ok":false,"i":null,"es":"entrar en el carril extremo izquierdo al adelantar"}],"f":5,"es":"En esta situación, en vía fuera de poblado, a los conductores les está permitido: (3 correctas)"},{"id":6432,"bg":"При тази ситуация ще извърша нарушение ако:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64279.png","v":null,"a":[{"t":"продължа движението си в същата пътна лента","ok":true,"i":null,"es":"continúo en el mismo carril"},{"t":"премина в лявата пътна лента","ok":true,"i":null,"es":"paso al carril izquierdo"},{"t":"спра пред светофара, в лентата, над която е поставен","ok":true,"i":null,"es":"paro ante el semáforo, en el carril sobre el que está colocado"},{"t":"премина в дясната пътна лента","ok":false,"i":null,"es":"paso al carril derecho"}],"f":5,"es":"En esta situación COMETERÉ infracción si: (3 correctas)"},{"id":5840,"bg":"Коефициентът на сцепление на автомобилните гуми с пътя е най-голям когато пътната настилка е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"суха","ok":true,"i":null,"es":"seco"},{"t":"мокра","ok":false,"i":null,"es":"mojado"},{"t":"заснежена","ok":false,"i":null,"es":"con nieve"},{"t":"заледена","ok":false,"i":null,"es":"helado"}],"f":5,"es":"El coeficiente de rozamiento entre neumáticos y calzada es mayor cuando el pavimento está:","explain":"El rozamiento es máximo en pavimento SECO. Mojado, nieve y hielo lo reducen progresivamente (el hielo es el peor caso), alargando la distancia de frenado."},{"id":5854,"bg":"Влияе ли масата на превозното средство върху дължината на неговия спирачен път?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"¿Afecta la masa del vehículo a su distancia de frenado?","explain":"Sí: a más masa, más energía cinética que disipar con los mismos frenos, y por tanto más metros de frenado. Por eso un vehículo cargado frena peor que vacío."},{"id":5863,"bg":"Най-важният фактор за избягване на сблъсък с движещия се отпред автомобил е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"поддържане на необходимата дистанция","ok":true,"i":null,"es":"mantener la distancia de seguridad necesaria"},{"t":"движението с постоянна скорост","ok":false,"i":null,"es":"circular a velocidad constante"},{"t":"автомобилът да бъде оборудван с подходящи гуми","ok":false,"i":null,"es":"llevar neumáticos adecuados"},{"t":"автомобилът да бъде с нисък център на тежестта","ok":false,"i":null,"es":"tener el centro de gravedad bajo"}],"f":5,"es":"El factor más importante para evitar una colisión con el vehículo de delante es:","explain":"La distancia de seguridad es el factor decisivo: te da el tiempo y el espacio de reacción cuando el de delante frena. Velocidad constante, neumáticos o centro de gravedad ayudan, pero sin distancia no hay margen posible."},{"id":5870,"bg":"При избиране скоростта на движение, водачите на пътни превозни средства:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да се съобразяват със състоянието на превозното средство","ok":true,"i":null,"es":"el estado del vehículo"},{"t":"трябва да се съобразяват с превозвания товар","ok":true,"i":null,"es":"la carga transportada"},{"t":"не са длъжни да се съобразяват с характера и интензивността на движението","ok":false,"i":null,"es":"no están obligados a considerar la intensidad del tráfico"},{"t":"не са длъжни да се съобразяват с конкретните условия на видимост","ok":false,"i":null,"es":"no están obligados a considerar las condiciones de visibilidad"}],"f":5,"es":"Al elegir la velocidad, los conductores deben tener en cuenta: (2 correctas)","explain":"Al elegir velocidad debes considerar el estado del vehículo y la carga transportada, y TAMBIÉN la intensidad del tráfico y la visibilidad: por eso las dos opciones que dicen 'no están obligados' son falsas."},{"id":5889,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57891.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"пешеходците не са на платното за движение и не съм задължен да променям скоростта","ok":false,"i":null,"es":"los peatones no están en la calzada y no tengo que cambiar velocidad"},{"t":"движа се по път с предимство и не съм задължен да намалявам скоростта","ok":false,"i":null,"es":"circulo por vía preferente y no tengo que reducir"}],"f":5,"es":"En esta situación: (2 correctas)"},{"id":5892,"bg":"Как ще постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57963.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"при необходимост спирам, докато се убедя, че преминаването е безопасно","ok":true,"i":null,"es":"si es necesario, paro hasta asegurarme de que es seguro pasar"},{"t":"предупреждавам децата със звуков сигнал да освободят пътя","ok":false,"i":null,"es":"aviso a los niños con el claxon para que cedan el paso"},{"t":"преминавам в съседната пътна лента","ok":false,"i":null,"es":"paso al carril adyacente"}],"f":5,"es":"¿Cómo actuarás en esta situación? (2 correctas)"},{"id":5893,"bg":"След като преминат децата, увеличавам скоростта и продължавам движението.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58063.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"Cuando pasan los niños, aumento la velocidad y continúo. Esto es:"},{"id":5899,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58149.png","v":null,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"управлявам с готовност за спиране","ok":true,"i":null,"es":"circulo listo para frenar"},{"t":"подавам звуков сигнал за да привлека вниманието на велосипедистите","ok":false,"i":null,"es":"toco el claxon para avisar a los ciclistas"},{"t":"подавам авариен сигнал","ok":false,"i":null,"es":"activo las luces de emergencia"}],"f":5,"es":"En esta situación: (2 correctas)"},{"id":6699,"bg":"При заобикаляне на спрелия пред пешеходната пътека автобус:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58433.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да управлявам с готовност да спра пред пешеходната пътека","ok":true,"i":null,"es":"debo estar listo para parar ante el paso de peatones"},{"t":"не съм задължен да намалявам скоростта","ok":false,"i":null,"es":"no estoy obligado a reducir"}],"f":5,"es":"Al rodear un autobús parado antes del paso de peatones: (2 correctas)"},{"id":11692,"bg":"Когато няма други ограничения, водачите на леки моторни превозни средства с четири колела от категория АМ, при движение извън населено място, не трябва да превишават:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"45 km/h","ok":true,"i":null,"es":"45 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":5,"es":"Sin otras restricciones, el conductor de un cuatriciclo ligero (categoría AM) no debe superar:","explain":"45 km/h: es la velocidad máxima de los cuatriciclos ligeros (categoría AM), limitada por su propia construcción y por la norma."},{"id":11698,"bg":"Когато разрешената максимална скорост за движение в населено място не е сигнализирана с пътен знак, водачите на леки автомобили не трябва да превишават:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"45 km/h","ok":false,"i":null,"es":"45 km/h"}],"f":5,"es":"Cuando la velocidad máxima en zona urbana no está señalizada con señal de tráfico, el límite es:","explain":"50 km/h: es el límite urbano por defecto en Bulgaria cuando no hay señal que indique otro valor. 40 o 30 solo rigen si están señalizados."},{"id":11703,"bg":"Когато няма други ограничения, водачът на товарен автомобил с допустима максимална маса 3 t., при движение извън населено място, не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"}],"f":5,"es":"Sin otras restricciones, el conductor de camión de 3 t fuera de población no debe superar:","explain":"90 km/h: fuera de población, en vía convencional, un camión de hasta 3,5 t tiene el mismo límite general de 90 km/h. Los valores inferiores solo rigen con señalización."},{"id":12028,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":14,"a":[{"t":"да се движа възможно най-вдясно","ok":true,"i":null,"es":"circulo todo lo posible a la derecha"},{"t":"да не променям скоростта си и разположението на автомобила","ok":false,"i":null,"es":"no cambio velocidad ni posición"},{"t":"да намаля скоростта и при необходимост да спра","ok":true,"i":null,"es":"reducir velocidad y si es necesario parar"}],"f":5,"es":"¿Cuál es la actuación correcta en esta situación? (2 correctas)"},{"id":6232,"bg":"При тази ситуация кой от водачите трябва да осигури предимство?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69636.png","v":null,"a":[{"t":"на товарния автомобил, защото навлиза в съседната пътна лента","ok":true,"i":null,"es":"el camión, porque entra en el carril adyacente"},{"t":"на товарния автомобил, защото се намира отдясно","ok":false,"i":null,"es":"el camión, porque está a la derecha"},{"t":"на лекия автомобил, защото не е подал сигнал за маневра","ok":false,"i":null,"es":"el turismo, porque no señalizó"},{"t":"на лекия автомобил, защото е по-назад от товарния","ok":false,"i":null,"es":"el turismo, porque está más atrás"}],"f":5,"es":"En esta situación, ¿cuál de los conductores debe ceder el paso?"},{"id":6237,"bg":"Когато има остров в средата на пътно платно с двупосочно движение, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124137.png","v":null,"a":[{"t":"трябва да премине от неговата дясна страна","ok":true,"i":null,"es":"debe pasar por su lado DERECHO"},{"t":"трябва да премине от неговата лява страна","ok":false,"i":null,"es":"debe pasar por su lado IZQUIERDO"},{"t":"може да премине от неговата дясна или лява страна","ok":false,"i":null,"es":"puede pasar por cualquier lado"}],"f":5,"es":"Cuando hay una isla en el centro de la calzada de doble sentido, el conductor:"},{"id":6252,"bg":"При тази ситуация трябва да пропусна пешеходеца.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69884.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"INCORRECTO"}],"f":5,"es":"En esta situación debo dejar pasar al peatón. Esto es:"}];
